-- Чужие вопросы в блоке FAQ карточек.
--
-- scripts/gen_tool_choose_faq.py собирает FAQ со страницы сравнения «A против B»
-- и кладёт один и тот же блок обоим инструментам. Поле choose_if там разделено
-- на choose_a и choose_b, а faq не разделено вовсе. В итоге карточка отвечает
-- на вопросы про конкурента: на странице ChatGPT — четыре вопроса про
-- Character.AI, на странице Perplexity — три про Consensus, и так далее.
--
-- Удаляем вопрос, если он называет другой инструмент из каталога и при этом
-- не называет свой. Вопросы без упоминания инструментов остаются.
-- Индексы посчитаны по английской версии и применены ко всем языкам:
-- порядок вопросов в переводах совпадает.
--
-- Генератор поправлен отдельно, иначе пересборка вернёт всё назад.
-- Идемпотентно: присвоение готовых массивов.

UPDATE tools SET faq = $x$[{"a": "Yes. Adobe Firefly is trained exclusively on Adobe Stock images, openly licensed content, and public domain works. Output is commercially safe to use without copyright concerns — unlike most other AI image generators.", "q": "Is Adobe Firefly copyright safe?"}, {"a": "For artistic and aesthetic quality, Midjourney generally produces more visually striking results. Firefly excels at photorealistic product images and brand-consistent visuals. The gap has narrowed significantly with Firefly 3 (2025).", "q": "Is Midjourney better quality than Adobe Firefly?"}, {"a": "Yes. Adobe Firefly Video Model (launched 2024) generates short video clips from text prompts and is integrated into Adobe Premiere Pro. It focuses on commercially safe video assets for professional production.", "q": "Can Adobe Firefly generate videos?"}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Midjourney V7 sigue siendo superior en calidad artística general. DALL-E 3 es mejor en seguir instrucciones específicas y texto dentro de imágenes. DALL-E 3 está integrado en ChatGPT lo que facilita iteración conversacional. Para arte — Midjourney; para instrucciones precisas en chat — DALL-E 3.", "q": "¿DALL-E 3 o Midjourney para calidad?"}, {"a": "Sí. ChatGPT con DALL-E 3 puede editar imágenes existentes — seleccionar áreas para modificar, añadir o quitar elementos. Adobe Firefly (Generative Fill en Photoshop) es más potente para edición precisa de fotos. Para edición simple — ChatGPT; para edición profesional — Photoshop con Firefly.", "q": "¿ChatGPT puede editar imágenes existentes?"}, {"a": "Según los términos de OpenAI, los usuarios de pago tienen derechos sobre las imágenes generadas. Sin embargo, hay debate legal sobre los derechos de autor de imágenes generadas por IA. Para uso comercial con garantías claras — Adobe Firefly (entrenado con contenido con licencia) es la opción más segura legalmente.", "q": "¿Las imágenes de DALL-E 3 son libres de derechos?"}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "ChatGPT Images nutzt DALL-E 3 (und neuerdings GPT-4o native Bildgenerierung) als Backend. Der Unterschied ist die Integration: In ChatGPT können Sie Bilder im Kontext des Gesprächs verfeinern und iterieren. DALL-E API direkt ist für Entwickler.", "q": "ChatGPT Images vs DALL-E: Ist das dasselbe?"}, {"a": "Ja. Adobe trainiert Firefly ausschließlich mit Adobe Stock-Bildern, gemeinfreien Werken und lizenzierten Inhalten. Das macht es kommerziell sicher ohne Copyright-Risiken. Adobe bietet sogar eine Entschädigung falls es trotzdem zu IP-Problemen kommt.", "q": "Ist Adobe Firefly kommerziell sicher?"}, {"a": "ChatGPT Images mit GPT-4o ist gut für schnelle Marketing-Konzepte und Ideenfindung. Für finale kommerzielle Produktion empfiehlt sich Adobe Firefly (IP-Sicherheit) oder Midjourney (höchste Qualität). ChatGPT für Entwürfe; spezialisierte Tools für Produktion.", "q": "ChatGPT Images für Marketing-Visuals: Ist es gut?"}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Да. Adobe Firefly обучен исключительно на изображениях Adobe Stock, контенте с открытыми лицензиями и материалах общественного достояния. Созданные изображения можно использовать коммерчески без риска нарушения авторских прав — в отличие от большинства других генераторов.", "q": "Безопасен ли Adobe Firefly в плане авторских прав?"}, {"a": "По художественному и эстетическому качеству Midjourney, как правило, выдаёт более выразительные результаты. Firefly превосходит его в фотореалистичных снимках продуктов и брендинговом визуале. С выходом Firefly 3 (2025) разрыв существенно сократился.", "q": "Качество Midjourney выше, чем у Adobe Firefly?"}, {"a": "Да. Видеомодель Adobe Firefly (запущена в 2024 году) создаёт короткие видеоклипы по текстовым запросам и интегрирована в Adobe Premiere Pro. Фокус — на коммерчески чистых видеоматериалах для профессионального производства.", "q": "Может ли Adobe Firefly генерировать видео?"}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "ChatGPT Images (DALL-E 3) зручніший для загального використання і входить до Plus. Adobe Firefly кращий для комерційних проєктів завдяки чіткій ліцензії і інтеграції з Creative Cloud. Для повсякденного — ChatGPT; для комерційного — Firefly.", "q": "ChatGPT Images vs Adobe Firefly — що обрати?"}, {"a": "Adobe Firefly має безкоштовний план з обмеженими кредитами. Також включений у Creative Cloud підписки. ChatGPT Images включений у ChatGPT Plus ($20/міс).", "q": "Adobe Firefly безкоштовний?"}, {"a": "Так. За умовами OpenAI зображення згенеровані через API або ChatGPT можуть використовуватись комерційно. Adobe Firefly також явно комерційно безпечний завдяки навчанню на ліцензованих даних.", "q": "DALL-E 3 можна використовувати комерційно?"}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "DALL-E 3 יצירתי ומבין תיאורים מורכבים. Firefly בטוח מסחרית ומשתלב עם Adobe. יצירה חופשית – DALL-E; עיצוב מקצועי – Firefly.", "q": "ChatGPT Images לעומת Adobe Firefly?"}, {"a": "Firefly מציע 25 Credits חינמיים לחודש; Creative Cloud כולל Firefly Credits. ChatGPT Images כלול ב-ChatGPT Plus ($20/חודש).", "q": "Adobe Firefly חינמי?"}, {"a": "כן. Adobe מאמנת Firefly רק על תוכן מורשה ומציעה ערבות מסחרית. זה יתרון גדול לעסקים שחוששים מבעיות זכויות יוצרים.", "q": "Adobe Firefly – האם הוא בטוח לשימוש מסחרי?"}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "DALL-E 3 suit mieux les instructions textuelles précises. Firefly est meilleur pour l'intégration professionnelle dans Photoshop et la sécurité commerciale. Pour une génération dans ChatGPT → DALL-E 3 ; pour les professionnels Adobe → Firefly.", "q": "DALL-E 3 vs Adobe Firefly — lequel est le meilleur ?"}, {"a": "La génération d'images dans ChatGPT est disponible dans le plan gratuit avec des limites. ChatGPT Plus (20 $/mois) offre plus de générations et une priorité d'accès. Adobe Firefly est inclus dans Creative Cloud.", "q": "ChatGPT Images est-il inclus dans ChatGPT gratuit ?"}, {"a": "Oui. Via Generative Fill dans Photoshop, Firefly peut étendre, supprimer ou remplacer des éléments dans des photos existantes. C'est l'une des fonctionnalités les plus puissantes pour l'édition photo professionnelle.", "q": "Adobe Firefly peut-il modifier des photos existantes ?"}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "DALL-E 3 segue melhor instruções textuais precisas. Firefly é melhor para integração profissional no Photoshop e segurança comercial. Para geração no ChatGPT → DALL-E 3; para profissionais Adobe → Firefly.", "q": "DALL-E 3 vs Adobe Firefly — qual é o melhor?"}, {"a": "A geração de imagens no ChatGPT está disponível no plano gratuito com limites. ChatGPT Plus ($20/mês) oferece mais gerações e prioridade de acesso. Adobe Firefly está incluído no Creative Cloud.", "q": "ChatGPT Images está incluído no plano gratuito?"}, {"a": "Sim. Via Generative Fill no Photoshop, Firefly pode expandir, remover ou substituir elementos em fotos existentes. É uma das funcionalidades mais poderosas para edição de fotos profissional.", "q": "Adobe Firefly pode modificar fotos existentes?"}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'pt';

