UPDATE tools SET faq = $x$[{"a": "Aider is an open-source AI coding assistant that runs in the terminal. It connects to AI models (Claude, GPT-4, Gemini) and can edit multiple files simultaneously, automatically committing changes to git after each step.", "q": "What is Aider?"}, {"a": "They serve different workflows. Aider is better for autonomous multi-file refactoring from the command line. Copilot is better for real-time inline suggestions inside an IDE. Many developers use both.", "q": "Is Aider better than GitHub Copilot?"}, {"a": "Aider itself is free and open-source. You pay for the AI model API you connect it to — Claude or GPT-4 API costs apply per token used.", "q": "Is Aider free?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Aider es un asistente de codificación de IA open-source que funciona en la terminal. Se conecta a modelos de IA (Claude, GPT-4, Gemini) y puede editar múltiples archivos simultáneamente, haciendo un commit automático de los cambios en git después de cada paso.", "q": "¿Qué es Aider?"}, {"a": "Son para casos de uso diferentes. Aider es mejor para refactorización autónoma de múltiples archivos desde la línea de comandos. Copilot es mejor para sugerencias en línea en tiempo real dentro del IDE. Muchos desarrolladores usan ambas.", "q": "¿Aider es mejor que GitHub Copilot?"}, {"a": "Aider como herramienta es gratuito y open-source. Pagas por la API del modelo — los costos de Claude o GPT-4 API se calculan por tokens usados.", "q": "¿Aider es gratuito?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Aider ist ein Open-Source KI-Coding-Assistent für das Terminal. Sie starten Aider in Ihrem Projekt-Verzeichnis, wählen das Modell (Claude, GPT-4, etc.) und können dann in natürlicher Sprache Änderungen anfordern. Aider ändert die Dateien und erstellt automatisch Git-Commits.", "q": "Was ist Aider?"}, {"a": "Aider selbst ist kostenlos und Open-Source. Die Kosten entstehen durch das verwendete Modell — Claude oder GPT-4 API-Nutzung. Mit Ollama und lokalen Modellen kann Aider vollständig kostenlos genutzt werden.", "q": "Ist Aider kostenlos?"}, {"a": "Beide sind Terminal-basierte KI-Coding-Agenten. Claude Code ist tiefer in Anthropics Claude-Ökosystem integriert und generell leistungsfähiger für komplexe Aufgaben. Aider ist Open-Source, modellflexibel und hat eine aktive Community. Claude Code für maximale Qualität; Aider für Open-Source-Flexibilität.", "q": "Aider vs Claude Code: Was ist besser?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Aider — это open-source ИИ-ассистент для написания кода, работающий в терминале. Он подключается к ИИ-моделям (Claude, GPT-4, Gemini) и может редактировать несколько файлов одновременно, автоматически фиксируя изменения в git после каждого шага.", "q": "Что такое Aider?"}, {"a": "Они подходят для разных задач. Aider лучше для автономного рефакторинга нескольких файлов из командной строки. Copilot лучше для встроенных подсказок в реальном времени внутри IDE. Многие разработчики используют оба инструмента.", "q": "Aider лучше GitHub Copilot?"}, {"a": "Aider как инструмент бесплатен и открыт. Вы платите за API-модель — расходы на Claude или GPT-4 API считаются по использованным токенам.", "q": "Aider бесплатный?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Aider — термінальний інструмент що автономно вносить зміни у кодову базу. Copilot — IDE-плагін для автодоповнення і чату. Aider для складних багатофайлових завдань через CLI; Copilot для щоденного написання коду у IDE.", "q": "Aider vs GitHub Copilot — яка різниця?"}, {"a": "Aider відкритий і безкоштовний. Ви платите за API: Claude API, OpenAI API або безкоштовно через DeepSeek або локальні моделі. GitHub Copilot — від $10/міс.", "q": "Aider безкоштовний?"}, {"a": "Aider чудово підходить для Python. Він одна з найпопулярніших зовнішніх ШІ-інструментів в Python-спільноті. Має відмінну підтримку рефакторингів, тестів і великих кодових баз.", "q": "Aider для Python — чи підходить?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Aider הוא כלי טרמינל שמבצע שינויים בבסיס הקוד באופן אוטונומי. Copilot הוא תוסף IDE להשלמה ולצ'אט. Aider למשימות מורכבות רב-קבצים דרך CLI; Copilot לכתיבת קוד יומיומי ב-IDE.", "q": "Aider מול GitHub Copilot — מה ההבדל?"}, {"a": "Aider פתוח וחינמי. אתם משלמים עבור API: Claude API, OpenAI API או חינמית דרך DeepSeek או מודלים מקומיים. GitHub Copilot — מ-10$/חודש.", "q": "האם Aider בחינם?"}, {"a": "Aider מתאים היטב ל-Python. הוא אחד מכלי ה-AI החיצוניים הפופולריים ביותר בקהילת Python. יש לו תמיכה מצוינת לרפקטורים, בדיקות ובסיסי קוד גדולים.", "q": "Aider ל-Python — האם מתאים?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Aider est un outil terminal qui apporte de manière autonome des modifications à la base de code. Copilot est un plugin IDE pour l'autocomplétion et le chat. Aider pour les tâches complexes multi-fichiers via CLI ; Copilot pour l'écriture quotidienne de code dans l'IDE.", "q": "Aider vs GitHub Copilot — quelle est la différence ?"}, {"a": "Aider est open-source et gratuit. Vous payez pour l'API : API Claude, API OpenAI ou gratuitement via DeepSeek ou des modèles locaux. GitHub Copilot — à partir de 10 $/mois.", "q": "Aider est-il gratuit ?"}, {"a": "Aider convient parfaitement à Python. C'est l'un des outils IA externes les plus populaires dans la communauté Python. Excellente prise en charge des refactorisations, tests et grandes bases de code.", "q": "Aider pour Python — est-il adapté ?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Aider é uma ferramenta de terminal que faz alterações autônomas na base de código. Copilot é um plugin de IDE para autocompletar e chat. Aider para tarefas complexas em múltiplos arquivos via CLI; Copilot para escrita diária de código no IDE.", "q": "Aider vs GitHub Copilot — qual é a diferença?"}, {"a": "Aider é open-source e gratuito. Você paga pela API: API Claude, API OpenAI ou gratuitamente via DeepSeek ou modelos locais. GitHub Copilot — a partir de $10/mês.", "q": "Aider é gratuito?"}, {"a": "Aider se encaixa perfeitamente com Python. É uma das ferramentas de IA externas mais populares na comunidade Python. Excelente suporte para refatorações, testes e grandes bases de código.", "q": "Aider para Python — é adequado?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Akkio is a no-code AI analytics platform designed for marketing agencies and business teams. It can build predictive models — churn prediction, lead scoring, forecasting — from CSV or connected data sources without requiring data science knowledge. It's designed to deliver AI insights to clients.", "q": "What is Akkio?"}, {"a": "Akkio focuses on building reusable predictive models and deploying them for ongoing business use. Julius AI focuses on one-off conversational data analysis — ask questions, get answers, generate charts. Akkio is for ongoing ML models; Julius is for interactive data exploration.", "q": "What is the difference between Akkio and Julius AI?"}, {"a": "Akkio has a free trial. Paid plans start at around $49/month. It's priced for agencies and businesses that want to offer AI analytics to multiple clients.", "q": "Is Akkio free?"}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "DataRobot está más orientado a empresas grandes con equipos de datos — más potente pero mucho más caro. Akkio está diseñado para equipos de negocio sin científicos de datos — más accesible y fácil de configurar. Para PMEs y equipos de marketing/ventas — Akkio; para grandes empresas con datos complejos — DataRobot.", "q": "¿Akkio o DataRobot para ML sin código?"}, {"a": "Akkio tiene un plan gratuito limitado con proyectos básicos. Los planes de pago empiezan desde $49/mes. Julius AI tiene plan gratuito con 15 análisis/mes; planes desde $22/mes.", "q": "¿Akkio es gratuito?"}, {"a": "Julius AI puede hacer análisis estadísticos y regresiones básicas, pero no está diseñado para construir modelos predictivos de producción. Akkio está específicamente hecho para crear modelos de predicción (churn, conversión, forecasting) listos para integrar en sistemas de negocio.", "q": "¿Julius AI puede construir modelos predictivos?"}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Akkio ist für prädiktive Machine-Learning-Modelle: Sie trainieren ein Modell das zukünftige Ereignisse vorhersagt. Julius AI ist für explorative Analyse: Sie stellen Fragen an bestehende Daten und erhalten sofort Insights. Akkio für Vorhersagen; Julius für Analyse.", "q": "Akkio vs Julius AI: Was ist der Unterschied?"}, {"a": "Akkio hat einen kostenlosen Plan mit eingeschränkten Funktionen. Kostenpflichtige Pläne ab $50/Monat. Julius AI hat einen kostenlosen Plan; Pro ab $22,99/Monat.", "q": "Ist Akkio kostenlos?"}, {"a": "Ja. Akkio ist populär für CRM-Daten: Lead-Scoring, Churn-Vorhersage und Umsatz-Prognosen aus HubSpot, Salesforce oder CSV-Exporten. Ohne Data-Science-Kenntnisse können Marketing-Teams Vorhersagemodelle trainieren.", "q": "Akkio für CRM-Daten: Ist es geeignet?"}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Akkio строит предиктивные ML-модели (прогнозирование) по вашим данным. Julius AI анализирует данные через диалог: задаёте вопрос — получаете визуализацию. Akkio для прогностики, Julius для исследовательского анализа.", "q": "Akkio vs Julius AI — в чём разница?"}, {"a": "Akkio предлагает бесплатный пробный период. Платные планы от $50/мес. Julius AI предлагает ограниченный бесплатный план; Pro — $20/мес.", "q": "Akkio бесплатный?"}, {"a": "Julius AI специализирован для анализа данных с сильным акцентом на визуализацию и статистику. ChatGPT с Code Interpreter также мощен, но Julius AI оптимизирован именно для датасетов и предлагает более чистый рабочий процесс.", "q": "Julius AI лучше ChatGPT для анализа данных?"}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Akkio будує прогнозні ML-моделі без коду для бізнес-прогнозування. Julius AI аналізує наявні дані через розмову і генерує візуалізації. Akkio для прогнозування; Julius для пізнавальної аналітики.", "q": "Akkio vs Julius AI — яка різниця?"}, {"a": "Akkio має пробний план. Платні плани від $49/міс. Julius AI має безкоштовний план; Pro від $20/міс.", "q": "Akkio безкоштовний?"}, {"a": "Julius AI спеціалізується на аналізі даних. ChatGPT Advanced Data Analysis (раніше Code Interpreter) схожий але більш загальний. Julius AI часто швидший і зручніший для даних; ChatGPT краще для змішаних завдань.", "q": "Julius AI vs ChatGPT Advanced Data Analysis?"}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Akkio לבניית מודלי ML ולחיזוי. Julius AI לניתוח נתונים ויצירת גרפים. Akkio ל-ML; Julius לניתוח ו-EDA.", "q": "Akkio לעומת Julius AI?"}, {"a": "Akkio מציע תקופת ניסיון; מחיר מ-$49/חודש. Julius AI מציע תוכנית חינמית מוגבלת; Pro ב-$28/חודש.", "q": "Akkio חינמי?"}, {"a": "כן, Akkio פופולרי בסוכנויות שיווק לחיזוי Conversion, LTV ו-Churn ללקוחות שלהן. מאפשר לספק תובנות AI ללא מדעני נתונים.", "q": "Akkio לסוכנויות שיווק?"}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Akkio crée des modèles prédictifs ML no-code. Julius AI répond à des questions sur vos données. Akkio pour des prédictions automatisées ; Julius AI pour l'exploration et la visualisation de données ad hoc.", "q": "Akkio vs Julius AI — quelle est la différence ?"}, {"a": "Akkio a un plan gratuit avec des limites. Les plans payants à partir de 49 $/mois. Julius AI a un plan gratuit ; Pro à partir de 28 $/mois.", "q": "Akkio est-il gratuit ?"}, {"a": "Oui. La prédiction de churn est l'un des cas d'usage principaux d'Akkio. Vous importez vos données clients historiques et Akkio crée un modèle qui identifie les clients à risque de churn, sans connaissance en machine learning requise.", "q": "Akkio peut-il prédire le churn clients ?"}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Akkio cria modelos preditivos de ML no-code. Julius AI responde perguntas sobre seus dados e gera visualizações. Akkio para previsões automatizadas; Julius AI para exploração e visualização de dados ad hoc.", "q": "Akkio vs Julius AI — qual é a diferença?"}, {"a": "Akkio tem plano gratuito com limites. Planos pagos a partir de $49/mês. Julius AI tem plano gratuito; Pro a partir de $28/mês.", "q": "Akkio é gratuito?"}, {"a": "Sim. A previsão de churn é um dos principais casos de uso do Akkio. Você importa seus dados históricos de clientes e o Akkio cria um modelo que identifica clientes em risco de churn, sem conhecimento em machine learning.", "q": "Akkio pode prever churn de clientes?"}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Beautiful.ai is an AI presentation tool where slides auto-format as you add content. It's designed for individuals who create business presentations and want professional-looking results without manual design work.", "q": "What is Beautiful.ai used for?"}, {"a": "Beautiful.ai offers a free plan with limited slides and features. The Pro plan starts at $12/month and the Team plan at $40/month per user, providing unlimited slides and collaboration.", "q": "Is Beautiful.ai free?"}, {"a": "Pitch is generally preferred for investor pitches due to its professional templates, viewer analytics (see when investors open your deck), and team collaboration. Beautiful.ai works well for internal business presentations.", "q": "Which is better for investor pitches — Beautiful.ai or Pitch?"}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Beautiful.ai tiene diseño automático superior — los slides se ajustan solos. Google Slides tiene colaboración más familiar y es gratuito. Para calidad de diseño sin esfuerzo — Beautiful.ai. Para colaboración sencilla sin costo — Google Slides. Muchos equipos usan Google Slides para borradores y Beautiful.ai para versiones finales.", "q": "¿Beautiful.ai o Google Slides para equipos?"}, {"a": "Pitch tiene funciones de IA para sugerir contenido y mejorar texto. Para generación completa de presentaciones desde texto — Gamma es más potente. Pitch prioriza la colaboración de equipo y el diseño de calidad; la generación IA es secundaria.", "q": "¿Pitch tiene IA para generar slides?"}, {"a": "Sí. Beautiful.ai permite exportar a PDF y PowerPoint. Esto facilita compartir con personas que no tienen cuenta de Beautiful.ai. La calidad del export a PowerPoint es buena, aunque algunas animaciones automáticas pueden simplificarse en la conversión.", "q": "¿Beautiful.ai puede exportar a PowerPoint?"}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Pitch ist beliebter bei Startups für Investor-Decks: bessere Templates für Fundraising und stärkere Kollaboration. Beautiful.ai ist gut für regelmäßige Unternehmenspräsentationen wo Konsistenz wichtig ist. Für Investor-Pitches — Pitch; für laufende Business-Präsentationen — Beautiful.ai.", "q": "Beautiful.ai vs Pitch: Welches ist besser für Startups?"}, {"a": "Ja. Beautiful.ai unterstützt Branding: eigene Farben, Schriften und Logos. Sie können Brand-Templates erstellen die das gesamte Team für konsistente Präsentationen nutzt. Das ist einer der Hauptvorteile für Marketing-Teams.", "q": "Kann Beautiful.ai Markenschriften und -farben verwenden?"}, {"a": "Pitch hat schönere moderne Templates und stärkere Online-Kollaboration als PowerPoint. PowerPoint ist universeller und offline nutzbar. Für moderne Team-Präsentationen — Pitch; für maximale Kompatibilität und Offline-Nutzung — PowerPoint.", "q": "Pitch vs PowerPoint: Was ist besser?"}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Gamma — инструмент для презентаций с ИИ, который создаёт полноценные спроектированные презентации из текстового запроса. В отличие от традиционных конструкторов слайдов, Gamma создаёт карточные веб-презентации, которыми делятся по ссылкам. Генерирует контент, макет и визуальное оформление одновременно за секунды.", "q": "Что такое Gamma AI?"}, {"a": "Да. Beautiful.ai может экспортировать презентации в формат PowerPoint (.pptx). Полезно, когда нужно делиться файлами с людьми, ожидающими традиционные форматы слайдов. Веб-нативный формат Gamma не экспортируется в PowerPoint так же чисто.", "q": "Может ли Beautiful.ai экспортировать в PowerPoint?"}, {"a": "Для быстрых ИИ-сгенерированных презентаций, которыми делятся в цифровом виде, Gamma быстрее и современнее. Для традиционных бизнес-презентаций, которые могут потребовать экспорта PowerPoint, Beautiful.ai даёт больше контроля. Оба производят профессиональные результаты.", "q": "Что лучше для бизнес-презентаций — Gamma или Beautiful.ai?"}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Gamma генерує контент і дизайн з ШІ — менше ручної роботи. Canva дає більше дизайнерського контролю і шаблонів. Gamma для швидкого старту з ШІ; Canva для кастомного дизайну.", "q": "Gamma vs Canva — що краще для презентацій?"}, {"a": "Так. Gamma дозволяє експортувати презентацію у PDF і PowerPoint формат. Це корисно якщо отримувач потребує .pptx файлу.", "q": "Gamma може зберегти у PowerPoint?"}, {"a": "Так. Beautiful.ai має командні функції: Brand Kit для консистентного стилю, Workspace для спільного доступу і Team Plan. Ідеально для маркетингових команд що хочуть єдиний стиль.", "q": "Beautiful.ai для командних презентацій?"}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Pitch מועדף לגיוס כסף – templates לסטארטאפ ו-Analytics. Beautiful.ai לצוותי שיווק עם Brand. Pitch לגיוס; Beautiful.ai למצגות שיווקיות.", "q": "Beautiful.ai לעומת Pitch לסטארטאפים?"}, {"a": "Beautiful.ai מאפשר להגדיר צבעי Brand, פונות ולוגו. כל המצגות של הצוות ישתמשו בהגדרות אלה אוטומטית. מועיל מאוד לצוותי Marketing.", "q": "Beautiful.ai Brand – כיצד זה עובד?"}, {"a": "Pitch יפה יותר עם templates מודרניים ו-Analytics. Google Slides חינמי לחלוטין ועובד עם Workspace. Pitch לסטארטאפים; Slides לעבודה יומיומית.", "q": "Pitch לעומת Google Slides?"}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Pitch est plus populaire pour les pitch decks d'investisseurs : meilleurs templates pour le fundraising et collaboration plus forte. Beautiful.ai est bon pour les présentations d'entreprise régulières où la cohérence est importante. Pour les pitchs investisseurs → Pitch ; pour les présentations régulières → Beautiful.ai.", "q": "Beautiful.ai vs Pitch — lequel est le meilleur pour les startups ?"}, {"a": "Oui. Beautiful.ai prend en charge le branding : couleurs, polices et logos personnalisés. Vous pouvez créer des templates de marque que toute l'équipe utilise pour des présentations cohérentes. C'est l'un des principaux avantages pour les équipes marketing.", "q": "Beautiful.ai peut-il utiliser les polices et couleurs de marque ?"}, {"a": "Pitch a des templates plus modernes et une meilleure collaboration en ligne que PowerPoint. PowerPoint est plus universel et utilisable hors ligne. Pour les présentations d'équipe modernes → Pitch ; pour la compatibilité maximale et l'utilisation hors ligne → PowerPoint.", "q": "Pitch vs PowerPoint — lequel est le meilleur ?"}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Pitch é mais popular para pitch decks de investidores: melhores templates para fundraising e colaboração mais forte. Beautiful.ai é bom para apresentações corporativas regulares onde a consistência importa. Para pitches de investidores → Pitch; para apresentações regulares → Beautiful.ai.", "q": "Beautiful.ai vs Pitch — qual é o melhor para startups?"}, {"a": "Sim. Beautiful.ai suporta branding: cores, fontes e logos personalizados. Você pode criar templates de marca que toda a equipe usa para apresentações consistentes. É uma das principais vantagens para equipes de marketing.", "q": "Beautiful.ai pode usar fontes e cores da marca?"}, {"a": "Pitch tem templates mais modernos e melhor colaboração online que o PowerPoint. PowerPoint é mais universal e funciona offline. Para apresentações de equipe modernas → Pitch; para compatibilidade máxima e uso offline → PowerPoint.", "q": "Pitch vs PowerPoint — qual é o melhor?"}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Bubble is a no-code application builder — it's for building web apps with databases, logic, and user interactions. Webflow is a no-code website builder focused on design and CMS. Bubble builds apps; Webflow builds websites.", "q": "What is the difference between Bubble and Webflow?"}, {"a": "Yes. Bubble is one of the most popular platforms for building SaaS products without code. It handles user authentication, databases, workflows, and API integrations. Many funded startups use Bubble as their primary platform.", "q": "Is Bubble good for SaaS?"}, {"a": "Webflow's Starter plan is free. Bubble also has a free plan. Paid plans are comparable — Webflow Core starts at $29/mo, Bubble Starter at $32/mo. Costs scale differently: Webflow charges per site traffic, Bubble charges per app workload.", "q": "Which is cheaper — Bubble or Webflow?"}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Depende del producto. Si construyes una aplicación SaaS con usuarios, datos y lógica — Bubble. Si construyes el sitio web de marketing de tu startup — Webflow. Muchas startups usan ambas: Webflow para el sitio de marketing y Bubble para el producto.", "q": "¿Bubble o Webflow para startups?"}, {"a": "Bubble tiene plan gratuito para desarrollar y probar apps (con subdominio bubble.io). Para lanzar en producción, el plan más económico cuesta $32/mes (Starter). Webflow tiene plan gratuito para 2 proyectos con subdominio webflow.io; planes para sites desde $14/mes.", "q": "¿Bubble es gratuito?"}, {"a": "Webflow tiene lógica básica (formularios, filtros, miembros) pero no está diseñado para aplicaciones complejas con base de datos propia y lógica de negocio. Para funcionalidades de app reales — Bubble. Webflow es mejor para sitios con contenido dinámico pero no para productos SaaS.", "q": "¿Puede Webflow construir aplicaciones?"}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Bubble für Web-Apps: Sie brauchen Nutzeraccounts, Datenbank und komplexe Logik — z.B. ein SaaS-Produkt oder Marktplatz. Webflow für Marketing-Websites: Sie brauchen eine schöne, schnelle Website mit CMS aber keine App-Logik.", "q": "Bubble oder Webflow: Was soll ich wählen?"}, {"a": "Bubble hat einen kostenlosen Plan der das Bauen und Testen erlaubt. Kostenpflichtige Pläne ab $29/Monat zum Veröffentlichen ohne Bubble-Branding. Webflow hat einen kostenlosen Plan; kostenpflichtige Pläne ab $18/Monat.", "q": "Ist Bubble kostenlos?"}, {"a": "Webflow hat eingebautes E-Commerce für einfache Online-Shops. Für komplexere E-Commerce-Anforderungen (große Produktkataloge, komplexe Varianten) ist Shopify leistungsfähiger. Webflow ist gut für Design-orientierte kleine Shops.", "q": "Webflow für E-Commerce: Ist das gut?"}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Bubble — конструктор no-code приложений: для создания веб-приложений с базами данных, логикой и пользовательскими взаимодействиями. Webflow — конструктор сайтов с фокусом на дизайн и CMS. Bubble строит приложения, Webflow строит сайты.", "q": "В чём разница между Bubble и Webflow?"}, {"a": "Да. Bubble — одна из самых популярных платформ для создания SaaS-продуктов без кода. Он управляет авторизацией пользователей, базами данных, рабочими процессами и интеграцией API. Многие финансируемые стартапы используют Bubble как основную платформу.", "q": "Bubble подходит для SaaS?"}, {"a": "Стартовый план Webflow бесплатный. У Bubble тоже есть бесплатный план. Платные планы сопоставимы: Webflow Core от $29/мес, Bubble Starter от $32/мес. Стоимость масштабируется по-разному.", "q": "Что дешевле — Bubble или Webflow?"}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Bubble для стартапів що будують SaaS або застосунки з бізнес-логікою і базами даних. Webflow для маркетингових сайтів і агентств. Для MVP з функціональністю — Bubble; для красивого сайту — Webflow.", "q": "Bubble vs Webflow — що обрати для стартапу?"}, {"a": "Bubble має безкоштовний план для розробки. Starter від $32/міс. Webflow безкоштовний для дизайну; Starter від $14/міс.", "q": "Bubble безкоштовний?"}, {"a": "Webflow — візуальний конструктор сайтів з чистим кодом. WordPress — CMS з тисячами плагінів і більшою гнучкістю контенту. Webflow для дизайнерів що хочуть контроль; WordPress для контент-важких сайтів з великою екосистемою.", "q": "Webflow vs WordPress — яка різниця?"}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Bubble לאפליקציות web עם לוגיקה ומסד נתונים. Webflow לאתרים ויזואליים ו-CMS. SaaS ו-Web App – Bubble; אתרי שיווק ועיצוב – Webflow.", "q": "Bubble לעומת Webflow – מה לבחור?"}, {"a": "Bubble מציע תוכנית חינמית; Starter ב-$32/חודש. Webflow Starter חינמי; Basic ב-$14/חודש.", "q": "Bubble חינמי?"}, {"a": "Webflow מצוין ל-SEO – HTML נקי, meta tags, sitemap אוטומטי ו-301 redirects. אחד הפתרונות הטובים ביותר ל-SEO בין בוני האתרים ללא קוד.", "q": "Webflow SEO – כמה זה טוב?"}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Bubble est pour créer des applications web complexes (SaaS, marketplaces). Webflow est pour les sites web marketing et de contenu. Application web avec logique métier → Bubble ; site marketing ou portfolio → Webflow.", "q": "Bubble vs Webflow — lequel est le meilleur ?"}, {"a": "Bubble est no-code mais avec une courbe d'apprentissage significative. Comptez plusieurs semaines pour maîtriser les bases. Pour les applications très complexes, vous aurez besoin d'aide de la communauté ou d'un développeur Bubble.", "q": "Bubble est-il vraiment no-code ?"}, {"a": "Oui. Bubble est capable de créer des marketplaces, des plateformes de réservation et des applications de style Airbnb. Des centaines de startups ont construit leur MVP sur Bubble. La performance peut être limitée à très grande échelle.", "q": "Bubble peut-il créer un clone d'Airbnb ?"}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Bubble é para construir aplicativos com lógica de negócios complexa. Webflow é para criar sites belos com CMS. Para apps SaaS, Bubble; para sites de marketing de alta qualidade, Webflow.", "q": "Bubble vs Webflow — qual escolher?"}, {"a": "Bubble tem plano gratuito para desenvolvimento e testes. Planos de produção a partir de $29/mês. Webflow tem plano gratuito limitado; planos de site a partir de $14/mês.", "q": "Bubble é gratuito?"}, {"a": "Webflow tem funcionalidades básicas de e-commerce. Para lojas menores, funciona bem. Para e-commerce complexo com muitos produtos, Shopify pode ser mais adequado.", "q": "Webflow é bom para e-commerce?"}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "CapCut is a video editor — you import existing video clips and edit them. Kling AI is a video generator — it creates video from text prompts or images. CapCut is for editing; Kling is for generating.", "q": "What is the difference between CapCut and Kling AI?"}, {"a": "CapCut has some AI generation features like Dream, but its primary strength is editing existing footage. For full AI video generation from text prompts, Kling AI, Runway, or Pika are more capable.", "q": "Can CapCut generate AI video?"}, {"a": "CapCut is free with a generous feature set. CapCut Pro ($7.99/month) adds watermark removal, more AI features, and cloud storage. The free version is sufficient for most social media content creation.", "q": "Is CapCut free?"}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Para editar videos de TikTok con templates, música, subtítulos y efectos — CapCut es la herramienta estándar del sector, usada por la mayoría de creadores de TikTok. Kling es para generar clips de video IA que luego podrías editar en CapCut. Son complementarios, no competidores directos.", "q": "¿CapCut o Kling para TikTok?"}, {"a": "CapCut tiene algunas funciones de IA generativa, pero son limitadas comparadas con Kling o Runway. CapCut se centra en edición; Kling en generación. Para texto-a-video de calidad, Kling es significativamente más potente.", "q": "¿Puede CapCut generar video desde texto?"}, {"a": "Sí. CapCut es propiedad de ByteDance, la misma empresa de TikTok. En algunos países ha habido discusiones regulatorias relacionadas. Para usuarios en EE.UU., esto es un factor a considerar en términos de privacidad de datos.", "q": "¿CapCut es de TikTok/ByteDance?"}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Es sind verschiedene Tools. CapCut ist ein Video-Editor für bestehende Footage mit KI-Hilfs-Features. Kling AI generiert komplett neue Videos aus Text oder Bildern. Wenn Sie eigenes Footage haben — CapCut. Wenn Sie Videos von Grund auf generieren wollen — Kling.", "q": "CapCut oder Kling AI: Welches soll ich wählen?"}, {"a": "CapCut hat einen KI-Video-Generator in neueren Versionen, aber er ist weniger leistungsfähig als spezialisierte Tools wie Kling AI oder Runway. CapCut's Stärken liegen bei der Bearbeitung, nicht bei der Generierung.", "q": "Hat CapCut KI-Videoerstellung?"}, {"a": "CapCut ist ein Produkt von ByteDance, demselben Unternehmen das TikTok besitzt. Daher die enge Integration mit TikTok und die Beliebtheit für TikTok-Content-Erstellung. In einigen Ländern gibt es Datenschutzbedenken ähnlich wie bei TikTok.", "q": "Ist CapCut von TikTok?"}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "CapCut — видеоредактор: вы импортируете готовые клипы и монтируете их. Kling AI — видеогенератор: создаёт видео из текстовых запросов или изображений. CapCut — для монтажа, Kling — для генерации.", "q": "В чём разница между CapCut и Kling AI?"}, {"a": "У CapCut есть некоторые функции генерации ИИ (Dream), но основная сила — монтаж готовых материалов. Для полноценной генерации видео из текстовых запросов Kling AI, Runway или Pika значительно мощнее.", "q": "Может ли CapCut генерировать ИИ-видео?"}, {"a": "CapCut бесплатен с широким набором функций. CapCut Pro ($7.99/мес) добавляет удаление водяного знака, больше ИИ-функций и облачное хранилище. Бесплатная версия достаточна для большинства задач в соцсетях.", "q": "CapCut бесплатный?"}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "CapCut — редактор для соціальних медіа з ШІ-функціями. Kling — спеціалізований генератор відео. Для монтажу TikTok і Reels — CapCut; для генерації кінематографічного відео — Kling.", "q": "CapCut чи Kling для відео?"}, {"a": "CapCut розроблений ByteDance — тією самою компанією що і TikTok. Через це у деяких країнах CapCut може зіткнутись з тими самими регуляторними проблемами що і TikTok.", "q": "CapCut від якої компанії?"}, {"a": "Так. CapCut AI Video Generator дозволяє генерувати відеокліпи з текстового опису або зображень. Якість не така висока як у Kling або Runway але для соціальних медіа цілком прийнятна і безкоштовна.", "q": "Чи є у CapCut генерація відео з тексту?"}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "CapCut הוא עורך וידאו עם תכונות AI. Kling AI הוא מחולל וידאו AI מ-prompt. CapCut לעריכת וידאו קיים; Kling ליצירת וידאו חדש מתיאור.", "q": "CapCut מול Kling AI — מה ההבדל?"}, {"a": "CapCut פותח על ידי ByteDance — אותה חברה שמאחורי TikTok. יש חששות פרטיות בחלק ממדינות בשל הבעלות הסינית.", "q": "CapCut של מי?"}, {"a": "כן. CapCut מתוכנן לעבוד היטב עם TikTok: תבניות מותאמות, יחסי גובה-רוחב נכונים ועריכה מהירה. פופולרי מאוד בקרב יוצרי TikTok.", "q": "CapCut ל-TikTok — האם כדאי?"}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "CapCut est un éditeur vidéo avec des fonctionnalités IA. Kling AI est un générateur de vidéo IA de texte/image vers vidéo. CapCut pour éditer votre footage existant ; Kling pour créer de nouvelles vidéos depuis zéro avec l'IA.", "q": "CapCut vs Kling AI — quelle est la différence ?"}, {"a": "Oui. CapCut est disponible en France sur mobile (iOS/Android) et bureau. Notez que CapCut est développé par ByteDance (la société TikTok), ce qui soulève des questions de confidentialité similaires à TikTok.", "q": "CapCut est-il disponible en France ?"}, {"a": "CapCut a des fonctionnalités de génération IA limitées (avatars IA, effets de style vidéo). Pour la génération complète de texte/image vers vidéo, des outils dédiés comme Kling, Runway ou Pika sont beaucoup plus puissants.", "q": "CapCut peut-il générer des vidéos IA ?"}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "CapCut é um editor de vídeo para quem já tem material filmado e quer editá-lo rapidamente. Kling AI é um gerador de vídeo que cria cenas do zero. Use CapCut para editar; Kling para criar do nada.", "q": "CapCut vs Kling AI — para que usar cada um?"}, {"a": "Sim, CapCut tem vários recursos de IA: remoção automática de fundo, legendas automáticas, ajuste de ritmo com a música, efeitos de IA e mais. Não gera vídeo do zero como o Kling, mas tem muita automação.", "q": "CapCut tem inteligência artificial?"}, {"a": "Kling AI é relativamente bom com pessoas, mas como todos os geradores de vídeo de IA, pode ter inconsistências em rostos e movimentos. Para vídeos com pessoas específicas ou muito precisos, ainda é necessário filmagem real.", "q": "Kling AI funciona bem com vídeos de pessoas?"}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'pt';

