UPDATE tools SET faq = $x$[{"a": "Зависит от задачи. Claude в целом лучше справляется с длинными текстами и точнее обрабатывает большие документы. У ChatGPT больше функций (генерация изображений, голос, плагины) и более крупная экосистема. По бенчмаркам кода они конкурируют — Claude 3.7 лидирует во многих.", "q": "Claude лучше ChatGPT?"}, {"a": "Оба имеют бесплатные планы. ChatGPT Free использует GPT-4o mini с ограниченным доступом к GPT-4o. Claude Free использует Claude 3.5 Haiku с ограниченным Claude 3.5 Sonnet. Оба платных плана ($20/мес) открывают лучшие модели с более высокими лимитами.", "q": "Что бесплатно — ChatGPT или Claude?"}, {"a": "Оба отличные. Claude 3.7 Sonnet с расширенным мышлением показывает лучшие результаты на SWE-bench (реальные задачи разработки) по состоянию на 2025 год. Claude Code специально создан для сложных рабочих процессов кодирования. ChatGPT с интерпретатором кода превосходит в анализе данных.", "q": "Какой ИИ лучше для кода — ChatGPT или Claude?"}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'ru';

