 WHERE slug = 'elevenlabs' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Suno génère de la musique complète avec mélodie et paroles. ElevenLabs génère des voix réalistes pour la narration. Ce sont des outils très différents : Suno pour la création musicale ; ElevenLabs pour la voix off et la narration.", "q": "Suno vs ElevenLabs — quelle est la différence ?"}, {"a": "Suno a un plan gratuit avec 50 chansons par jour. Pro à partir de 10 $/mois. ElevenLabs a un plan gratuit avec 10 000 caractères/mois ; payants à partir de 5 $/mois.", "q": "Suno est-il gratuit ?"}, {"a": "Oui. Suno génère de la musique originale que vous pouvez utiliser en fond sonore pour vos vidéos (avec un plan payant pour les droits commerciaux). C'est une alternative à des bibliothèques comme Epidemic Sound.", "q": "Peut-on utiliser Suno pour la musique de fond de vidéos ?"}]$x$::jsonb
