UPDATE tools SET faq = $x$[{"a": "Suno gera músicas completas com instrumentos e vocal cantado. ElevenLabs gera fala realista para narração e dublagem. São ferramentas de áudio diferentes: Suno para música; ElevenLabs para voz falada.", "q": "Suno vs ElevenLabs — qual é a diferença?"}, {"a": "Sim, Suno pode gerar músicas com letras em português. Você pode especificar o idioma e o estilo musical. A qualidade das letras em português é boa, mas pode ter nuances menos precisas que em inglês.", "q": "Suno pode criar música em português?"}, {"a": "Sim, ElevenLabs tem plano gratuito com 10.000 caracteres por mês — suficiente para testar. Planos pagos a partir de $5/mês para uso comercial.", "q": "ElevenLabs tem plano gratuito?"}]$x$::jsonb
 WHERE slug = 'elevenlabs' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Figma AI (launched 2024) includes AI-generated layers and designs from text prompts, AI rename for layers, first draft generation, and prototype generation. It's built into Figma and available to all paid plan users.", "q": "What AI features does Figma have?"}, {"a": "No. Canva and Figma serve different purposes. Canva is for creating marketing content and presentations. Figma is for designing UI/UX interfaces and product prototypes. Designers use Figma; content creators use Canva.", "q": "Can Canva replace Figma?"}, {"a": "Canva is significantly easier for beginners — it's designed for non-designers with drag-and-drop simplicity. Figma has a steeper learning curve and is designed for professional designers. For quick graphics, start with Canva.", "q": "Which is better for beginners — Canva or Figma?"}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "v0 de Vercel está específicamente diseñado para generar componentes React/Tailwind de alta calidad con vista previa visual. Claude es más flexible y razona mejor sobre la lógica del diseño pero sin vista previa. Para componentes UI de producción — v0; para diseño de sistemas complejos con razonamiento — Claude.", "q": "¿Claude o v0 para generar UI en código?"}, {"a": "Figma tiene Dev Mode que muestra código CSS, iOS y Android de los diseños. También hay plugins como Figma to Code. Figma AI está desarrollando capacidades de generación de código más directas. Claude genera código desde cero; Figma convierte diseños existentes a código.", "q": "¿Figma AI puede generar código?"}, {"a": "Si compartes imágenes o descripciones de diseños, Claude puede dar feedback de UX, sugerir mejoras y analizar problemas de usabilidad. Esta capacidad de revisión de diseño conversacional es útil para equipos sin acceso a UX designers dedicados.", "q": "¿Claude puede revisar diseños existentes?"}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Figma AI kann erste Wireframe-Entwürfe und Komponenten-Varianten generieren. Für vollständige Screen-Generierung aus Text sind spezialisierte Tools wie UXpilot oder Uizard leistungsfähiger. Figma AI ist stärker als Produktivitäts-Boost im bestehenden Workflow.", "q": "Kann Figma AI einen ganzen Screen generieren?"}, {"a": "Ja. Design-Teams nutzen Claude für: UX-Writing und Microcopy, User-Story-Generierung, Design-Dokumentation, Competitive-Analysis und Research-Synthese. Es spart Zeit bei textintensiven Design-Aufgaben.", "q": "Ist Claude für Design-Teams nützlich?"}, {"a": "Sie lösen verschiedene Probleme. Figma AI unterstützt UI/UX-Design-Workflows mit Wireframes und Komponenten. Adobe Firefly generiert Bilder für Design-Assets. Für UI-Design — Figma AI; für Bildgenerierung in Design-Projekten — Firefly.", "q": "Figma AI vs Adobe Firefly für Design: Was ist besser?"}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Figma AI (запущен в 2024 году) включает генерацию макетов по текстовым запросам, умное переименование слоёв, создание прототипов и визуальный поиск. Доступен всем пользователям платных планов.", "q": "Какие ИИ-функции есть у Figma?"}, {"a": "Нет. Canva и Figma решают разные задачи. Canva — для создания маркетингового контента и презентаций. Figma — для проектирования UI/UX-интерфейсов и прототипов продуктов. Дизайнеры используют Figma, создатели контента — Canva.", "q": "Может ли Canva заменить Figma?"}, {"a": "Canva значительно проще для новичков — разработана для не-дизайнеров с простым drag-and-drop интерфейсом. Figma имеет более крутой порог вхождения и предназначена для профессиональных дизайнеров. Для быстрой графики начинайте с Canva.", "q": "Что лучше для начинающих — Canva или Figma?"}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Деякі функції Figma AI включені у платні плани Figma. Professional від $15/редактор/міс. Claude має безкоштовний план; Pro від $20/міс.", "q": "Figma AI безкоштовний?"}, {"a": "Так. Claude може генерувати React, HTML/CSS, Tailwind і компоненти UI. Для генерації UI-коду з описів Claude відмінний. Для генерації прямо у Figma — Figma AI або плагіни.", "q": "Чи може Claude генерувати UI-код?"}, {"a": "Figma AI може перейменовувати шари, генерувати текстовий контент для макетів, пропонувати альтернативні дизайни, і допомагати з побудовою компонентів. Функції розширюються — перевірте останні оновлення Figma.", "q": "Що може Figma AI?"}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Figma AI כלול בתוכניות Figma; Professional מ-$15/editor/חודש. Claude Pro ב-$20/חודש.", "q": "Figma AI כמה עולה?"}, {"a": "Claude לא מתחבר ישירות ל-Figma. ניתן להדביק Screenshots או לתאר עיצובים בטקסט. ל-Figma integration ישיר – השתמשו ב-Figma AI.", "q": "Claude יכול לקרוא Figma Files?"}, {"a": "Figma Make הופך עיצובי Figma לקוד React/HTML פונקציונלי. עדיין בשלבי Beta, אך מציע bridge בין עיצוב לפיתוח.", "q": "Figma Make – מה זה?"}]$x$::jsonb
