UPDATE tools SET faq = $x$[{"a": "Claude peut générer du HTML/CSS/React pour des maquettes fonctionnelles mais pas des fichiers Figma. Pour des maquettes visuelles interactives, Figma, Uizard ou v0 sont mieux adaptés.", "q": "Claude peut-il générer des maquettes complètes ?"}, {"a": "Oui. Les fonctionnalités IA de Figma sont intégrées dans l'application. Certaines fonctionnalités IA avancées peuvent nécessiter un plan payant. Figma a un plan gratuit ; Professional à partir de 15 $/éditeur/mois.", "q": "Figma AI est-il inclus dans Figma ?"}, {"a": "Oui. Claude est excellent pour raisonner sur les décisions UX : architecture de navigation, hiérarchie de l'information, meilleures pratiques d'accessibilité. Il peut être un précieux consultant UX même s'il ne génère pas de fichiers Figma.", "q": "Claude peut-il aider avec les décisions de design UX ?"}]$x$::jsonb
