UPDATE tools SET faq = $x$[{"a": "Обидва боти просять дозвіл перед входом у зустріч. Otter.ai і Fireflies.ai видимі для всіх учасників. Завжди повідомляйте учасників що зустріч записується — це вимога законодавства у більшості країн.", "q": "Ці інструменти записують без дозволу?"}, {"a": "Fireflies.ai підтримує транскрипцію кількох мов але якість для української може бути нижчою ніж для англійської. Перевіряйте актуальні мовні можливості на сайті Fireflies.", "q": "Fireflies.ai підтримує українську мову?"}]$x$::jsonb
