UPDATE tools SET faq = $x$[{"a": "Gamma est meilleur pour des présentations générées rapidement par IA avec un design moderne. Prezi est unique avec son approche canvas zoomable qui illustre les connexions visuellement. Gamma pour la rapidité ; Prezi pour le storytelling non-linéaire.", "q": "Gamma vs Prezi — lequel est le meilleur ?"}, {"a": "Prezi a un plan gratuit avec 5 présentations. Premium à partir de 7 $/mois. Gamma a un plan gratuit avec 400 crédits IA ; Plus à partir de 10 $/mois.", "q": "Prezi est-il gratuit ?"}, {"a": "Prezi est populaire dans l'enseignement car il permet de montrer des connexions entre concepts de manière visuelle. Le plan Education offre des tarifs réduits. Pour les cours et conférences, l'approche non-linéaire de Prezi peut renforcer la compréhension.", "q": "Prezi pour l'enseignement — est-il efficace ?"}]$x$::jsonb
