UPDATE tools SET faq = $x$[{"a": "They serve different workflows. Aider is better for autonomous multi-file refactoring from the command line. Copilot is better for real-time inline suggestions inside an IDE. Many developers use both.", "q": "Is Aider better than GitHub Copilot?"}, {"a": "GitHub Copilot requires a GitHub account but works in VS Code, JetBrains, Neovim, and Visual Studio regardless of where your code is hosted. You don't need to push code to GitHub to use it.", "q": "Does GitHub Copilot work without GitHub?"}]$x$::jsonb
