UPDATE tools SET faq = $x$[{"a": "Cursor имеет бесплатный план Hobby с ограниченными запросами (2000 дополнений/мес). Plan Pro — $20/мес с неограниченными дополнениями и 500 быстрыми запросами Claude/GPT-4. Business — $40/пользователь/мес.", "q": "Cursor бесплатный?"}, {"a": "Да, но они будут значительно перекрываться. Большинство разработчиков выбирают один основной инструмент. Cursor обычно предпочтителен за более мощные функции, а Copilot остаётся для команд с корпоративными рабочими процессами GitHub.", "q": "Можно использовать GitHub Copilot и Cursor вместе?"}]$x$::jsonb
