UPDATE tools SET faq = $x$[{"a": "Amazon Q Developer має безкоштовний план з 50 розмовами і 1000 рекомендаціями коду/міс. Pro від $19/користувач/міс. GitHub Copilot Individual від $10/міс; Business від $19/міс.", "q": "Amazon Q Developer безкоштовний?"}, {"a": "GitHub Copilot Business і Enterprise мають розширені налаштування конфіденційності: сніпети коду не використовуються для навчання і не передаються третім сторонам. Enterprise версія краща для відповідності корпоративним вимогам.", "q": "GitHub Copilot і захист даних?"}]$x$::jsonb
