UPDATE tools SET faq = $x$[{"a": "Hemingway Editor analyzes your writing for readability. It highlights long sentences, passive voice, complex words, and unnecessary adverbs — color-coded by severity. It assigns a grade-level readability score. The goal is writing that's clear, direct, and easy to read.", "q": "What does Hemingway Editor do?"}, {"a": "Hemingway Editor has a free web version at hemingwayapp.com. The desktop app (Mac/Windows) is a one-time purchase of $19.99. There is no subscription — pay once and own it permanently.", "q": "Is Hemingway Editor free?"}, {"a": "Hemingway Editor added AI writing features in 2023 powered by GPT-4. You can ask the AI to rewrite highlighted sentences, generate content, or improve passages. The AI is an add-on — the core product remains the readability analysis.", "q": "Does Hemingway Editor have AI writing?"}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Hemingway Editor es una herramienta de escritura que resalta texto difícil de leer. Usa colores para indicar frases demasiado largas (amarillo/rojo), voz pasiva (verde), adverbios (azul) y alternativas más simples (morado). El objetivo es escritura directa y clara.", "q": "¿Qué es Hemingway Editor?"}, {"a": "Hemingway Editor web es gratuito con funciones básicas. La app de escritorio (Mac/Windows) cuesta un pago único de $19.99. Grammarly tiene plan gratuito; Grammarly Premium cuesta $12/mes.", "q": "¿Hemingway Editor es gratuito?"}, {"a": "Úsalos juntos para lo mejor de ambos mundos. Grammarly primero para corrección gramatical y ortográfica, luego Hemingway para simplificar y hacer el texto más directo. Muchos escritores de contenido web siguen este flujo de dos pasos.", "q": "¿Cuándo usar Hemingway Editor y cuándo Grammarly?"}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Sie lösen unterschiedliche Probleme. Grammarly findet Grammatikfehler und gibt allgemeine Schreibvorschläge. Hemingway macht Ihren Schreibstil klarer und direkter. Viele Autoren nutzen beide: Grammarly für Korrektheit, Hemingway für Lesbarkeit.", "q": "Hemingway Editor oder Grammarly: Welches ist besser?"}, {"a": "Hemingway Editor hat eine kostenlose Web-Version auf hemingwayapp.com. Die Desktop-App kostet $19,99 (einmalige Zahlung, keine Abonnement). Grammarly hat einen kostenlosen Plan; Premium ab $12/Monat.", "q": "Ist Hemingway Editor kostenlos?"}, {"a": "Hemingway Editor funktioniert mit deutschen Texten, ist jedoch primär für englische Texte optimiert. Die Lesbarkeitsregeln (Satzlänge, Adverb-Erkennung) funktionieren auch auf Deutsch, aber die Sprachregeln sind nicht so präzise wie für Englisch kalibriert.", "q": "Kann Hemingway Editor auf Deutsch genutzt werden?"}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Hemingway Editor анализирует ваш текст на читаемость. Выделяет длинные предложения, пассивный залог, сложные слова и лишние наречия — с цветовой кодировкой по серьёзности. Присваивает оценку читаемости по уровню образования. Цель — чёткое, прямое и лёгкое для чтения письмо.", "q": "Что делает Hemingway Editor?"}, {"a": "Hemingway Editor имеет бесплатную веб-версию на hemingwayapp.com. Настольное приложение (Mac/Windows) — единоразовая покупка за $19.99. Подписки нет — платите один раз и используете постоянно.", "q": "Hemingway Editor бесплатный?"}, {"a": "Hemingway Editor добавил функции ИИ-написания в 2023 году на базе GPT-4. Можно попросить ИИ переписать выделенные предложения, создать контент или улучшить фрагменты. ИИ — дополнение, основной продукт остаётся анализом читаемости.", "q": "Есть ли у Hemingway Editor ИИ-написание?"}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Вони вирішують різні задачі. Grammarly виявляє граматичні помилки і дає загальні поради. Hemingway робить стиль чіткішим і прямішим. Багато авторів використовують обидва: Grammarly для точності, Hemingway для читабельності.", "q": "Hemingway Editor чи Grammarly — що краще?"}, {"a": "Hemingway Editor безкоштовний на hemingwayapp.com. Десктопний застосунок коштує $19,99 (одноразово, без підписки). Grammarly безкоштовний; Premium від $12/міс.", "q": "Hemingway Editor безкоштовний?"}, {"a": "Hemingway Editor аналізує і українські тексти, але оптимізований насамперед для англійської. Правила читабельності (довжина речень, виявлення прислівників) частково працюють для інших мов.", "q": "Hemingway Editor працює з українською мовою?"}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "הם פותרים בעיות שונות. Grammarly מוצא שגיאות דקדוק ומספק הצעות כלליות. Hemingway הופך את הסגנון לברור וישיר יותר. סופרים רבים משתמשים בשניהם: Grammarly לדיוק, Hemingway לקריאות.", "q": "Hemingway Editor או Grammarly — מה עדיף?"}, {"a": "ל-Hemingway Editor יש גרסת ווב חינמית ב-hemingwayapp.com. אפליקציית שולחן העבודה עולה 19.99$ (תשלום חד פעמי, ללא מנוי). Grammarly חינמי; Premium מ-12$/חודש.", "q": "האם Hemingway Editor בחינם?"}, {"a": "Hemingway Editor מנתח טקסטים בעברית אך מותאם בעיקר לאנגלית. כללי הקריאות (אורך משפטים, זיהוי תארי פועל) עובדים חלקית לשפות אחרות.", "q": "האם Hemingway Editor עובד עם עברית?"}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Ils résolvent des problèmes différents. Grammarly trouve les erreurs de grammaire et donne des conseils généraux. Hemingway rend votre style plus clair et direct. Beaucoup d'auteurs utilisent les deux : Grammarly pour la précision, Hemingway pour la lisibilité.", "q": "Hemingway Editor ou Grammarly — lequel est le meilleur ?"}, {"a": "Hemingway Editor est gratuit sur hemingwayapp.com. L'application de bureau coûte 19,99 $ (paiement unique, pas d'abonnement). Grammarly est gratuit ; Premium à partir de 12 $/mois.", "q": "Hemingway Editor est-il gratuit ?"}, {"a": "Hemingway Editor analyse aussi les textes français, mais est principalement optimisé pour l'anglais. Les règles de lisibilité (longueur des phrases, détection des adverbes) fonctionnent partiellement pour d'autres langues.", "q": "Hemingway Editor fonctionne-t-il en français ?"}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Eles resolvem problemas diferentes. Grammarly encontra erros de gramática e dá conselhos gerais. Hemingway torna seu estilo mais claro e direto. Muitos autores usam os dois: Grammarly para precisão, Hemingway para legibilidade.", "q": "Hemingway Editor ou Grammarly — qual é o melhor?"}, {"a": "Hemingway Editor é gratuito em hemingwayapp.com. O aplicativo desktop custa $19,99 (pagamento único, sem assinatura). Grammarly é gratuito; Premium a partir de $12/mês.", "q": "Hemingway Editor é gratuito?"}, {"a": "Hemingway Editor analisa textos em português, mas é principalmente otimizado para inglês. As regras de legibilidade (comprimento das frases, detecção de advérbios) funcionam parcialmente para outros idiomas.", "q": "Hemingway Editor funciona em português?"}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Hex is a collaborative data platform combining SQL notebooks, Python, and no-code charts into a single workspace. Data teams use it to analyze data and build interactive data apps. Hex Magic (AI) writes SQL and Python from natural language, explains code, and auto-generates visualizations.", "q": "What is Hex?"}, {"a": "Looker Studio creates drag-and-drop visual dashboards — it's a reporting tool for business users. Hex is a data notebook and app builder for data teams who work in SQL and Python. Looker Studio is read-only visual reporting; Hex is interactive analysis and computation.", "q": "What is the difference between Looker Studio and Hex?"}, {"a": "Hex has a free plan for individuals with 2 published apps. Team plan is $24/user/month. Pro and Enterprise plans are available for larger organizations. The free plan is generous for individual analysts.", "q": "How much does Hex cost?"}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Hex es una versión colaborativa y más potente de Jupyter — añade SQL nativo, visualizaciones drag-and-drop, publicación como apps y colaboración en tiempo real. Para análisis individual exploratorio — Jupyter es suficiente y gratuito. Para equipos de datos que necesitan compartir y publicar — Hex.", "q": "¿Hex o Jupyter Notebooks para análisis de datos?"}, {"a": "Hex soporta SQL (para cualquier base de datos) y Python. Puedes combinar celdas SQL y Python en el mismo notebook, lo que lo hace muy flexible para análisis que requieren tanto consultas de BD como procesamiento de datos con Python.", "q": "¿Qué lenguajes soporta Hex?"}, {"a": "Sí. Hex se conecta a BigQuery, Snowflake, Databricks, Redshift, PostgreSQL y muchos otros data warehouses. Looker Studio también conecta a BigQuery de forma nativa. Ambas son buenas opciones para análisis sobre BigQuery; Hex ofrece más capacidad de transformación con código.", "q": "¿Hex puede conectarse a BigQuery?"}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Hex ist eine kollaborative Datenplattform die Notebooks (SQL + Python) mit App-Publishing kombiniert. Data-Teams schreiben Analysen in Hex-Notebooks und veröffentlichen sie als interaktive Dashboards für nicht-technische Stakeholder — ohne separates BI-Tool.", "q": "Was ist Hex?"}, {"a": "Hex hat einen kostenlosen Plan für individuelle Nutzer mit begrenzten Projekten. Team-Pläne beginnen ab $24/Benutzer/Monat. Looker Studio ist vollständig kostenlos.", "q": "Ist Hex kostenlos?"}, {"a": "Jupyter ist kostenlos und Open-Source aber erfordert lokale Installation und hat wenig eingebaute Kollaboration. Hex ist Cloud-basiert, kollaborativ und fügt App-Publishing ohne zusätzliche Tools hinzu. Hex für Teams; Jupyter für individuelle lokale Entwicklung.", "q": "Hex vs Jupyter Notebooks: Was ist besser?"}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Hex — коллаборативная дата-платформа, объединяющая SQL-ноутбуки, Python и no-code графики в одном рабочем пространстве. Дата-команды используют её для анализа данных и создания интерактивных дата-приложений. Hex Magic (ИИ) пишет SQL и Python из естественного языка и автоматически генерирует визуализации.", "q": "Что такое Hex?"}, {"a": "Looker Studio создаёт drag-and-drop визуальные дашборды — инструмент отчётности для бизнес-пользователей. Hex — дата-ноутбук и конструктор приложений для дата-команд, работающих в SQL и Python. Looker Studio — read-only визуальная отчётность, Hex — интерактивный анализ и вычисления.", "q": "В чём разница между Looker Studio и Hex?"}, {"a": "У Hex есть бесплатный план для отдельных специалистов с 2 опубликованными приложениями. Plan Team — $24/пользователь/мес. Доступны Pro и Enterprise планы для крупных организаций.", "q": "Сколько стоит Hex?"}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Jupyter — локальний відкритий ноутбук для розробки. Hex — хмарна платформа де ноутбуки перетворюються на живі застосунки і дашборди для ділення з командою. Hex значно зручніший для командної роботи.", "q": "Hex vs Jupyter Notebook — яка різниця?"}, {"a": "Так. Hex підтримує Python, SQL і R в одному ноутбуці. Ви можете змішувати клітинки SQL і Python у одному документі і результати автоматично передаються між ними.", "q": "Hex підтримує Python і SQL?"}, {"a": "Looker Studio безкоштовний і простіший для Google-екосистеми. Tableau потужніший для складної аналітики і enterprise але дорогий. Для старту і Google-даних — Looker Studio; для серйозної enterprise аналітики — Tableau.", "q": "Looker Studio vs Tableau — що обрати?"}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Hex מיועד לצוותי Data Science שרוצים Notebooks שיתופיים. Looker Studio מיועד לדשבורדים עסקיים. Hex לניתוח עמוק; Looker Studio לדשבורדי KPI.", "q": "Hex לעומת Looker Studio – מה עדיף?"}, {"a": "Hex הוא Jupyter בענן עם שיתוף, ניהול גרסאות ועיצוב יפה יותר. Jupyter מקומי חינמי ומאפשר שליטה מלאה. Hex לצוותים; Jupyter לאנשים בודדים.", "q": "Hex לעומת Jupyter Notebooks?"}, {"a": "כן, Hex מתאים היטב ל-dbt עם חיבור לנתוני dbt ישירות. Hex ו-dbt יחד הם stack פופולרי בצוותי Data.", "q": "Hex תומך ב-dbt?"}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Hex est pour les data scientists et analystes techniques créant des analyses complexes. Looker Studio est pour les équipes non techniques créant des dashboards simples. Analytique avancée avec code → Hex ; rapports marketing simples → Looker Studio.", "q": "Hex vs Looker Studio — lequel est le meilleur ?"}, {"a": "Oui. Hex supporte Python et SQL dans des notebooks collaboratifs. Vous pouvez utiliser des bibliothèques Python comme pandas, numpy et plotly directement dans Hex.", "q": "Hex supporte-t-il Python ?"}, {"a": "Oui. Hex AI Magic génère du SQL à partir de descriptions en langage naturel. Vous décrivez ce que vous voulez analyser et Hex génère la requête SQL correspondante.", "q": "Hex AI peut-il écrire du SQL automatiquement ?"}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Hex é para equipes técnicas de dados que precisam de análise exploratória com código. Looker Studio é para dashboards de negócios sem código. Para data science e análise técnica, Hex; para relatórios de negócios, Looker Studio.", "q": "Hex vs Looker Studio — qual escolher?"}, {"a": "Sim, Hex suporta Python e SQL. Você pode misturar células Python e SQL em um mesmo notebook, o que é muito útil para análises que combinam transformações de dados e visualizações.", "q": "Hex suporta Python?"}, {"a": "Looker Studio é geralmente considerado mais simples para começar, especialmente para dados Google. Power BI é mais poderoso para análises complexas mas tem curva de aprendizado maior.", "q": "Looker Studio vs Power BI — qual é mais fácil?"}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "HeyGen leads on video translation (lip-synced dubbing in 175+ languages) and natural-looking avatar quality. Synthesia leads on enterprise features, compliance, and LMS integration for corporate training. HeyGen targets marketing; Synthesia targets L&D teams.", "q": "What is the difference between HeyGen and Synthesia?"}, {"a": "Yes. HeyGen can clone your voice and create an AI avatar that looks and sounds like you from a short recording. This is used for video translation — your avatar speaks in other languages with your cloned voice.", "q": "Can HeyGen clone my voice?"}, {"a": "HeyGen's Creator plan starts at $29/month (4 minutes of video). Business is $89/month (15 minutes). Enterprise pricing is custom. Video translation credits are sold separately.", "q": "How much does HeyGen cost?"}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Synthesia está más orientado a formación corporativa y eLearning — tiene más integraciones con LMS y flujos de trabajo de L&D. HeyGen es mejor para videos de marketing personalizados y clonación de voz/avatar. Para formación interna a escala — Synthesia; para marketing con avatar propio — HeyGen.", "q": "¿HeyGen o Synthesia para videos de formación?"}, {"a": "HeyGen tiene un plan gratuito con 1 crédito de video (aprox. 1 minuto). Los planes de pago empiezan desde $29/mes (Creator). Synthesia empieza desde $29/mes (Starter) con 10 minutos de video al mes.", "q": "¿Cuánto cuesta HeyGen?"}, {"a": "HeyGen y Synthesia requieren consentimiento explícito para crear avatares de personas reales. Las plataformas tienen políticas de uso aceptable que prohíben la creación de deepfakes no autorizados. Usar avatares con consentimiento para marketing propio o formación corporativa es completamente legal.", "q": "¿Son legales los avatares de IA?"}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "HeyGen ist stärker bei Video-Übersetzung und interaktiven Avataren für Echtzeit-Anwendungen. Synthesia hat mehr Avatare und ist stärker für Enterprise-Trainingsvideos und E-Learning. HeyGen für Video-Lokalisierung; Synthesia für skalierbare Unternehmenskommunikation.", "q": "HeyGen vs Synthesia: Was ist der Unterschied?"}, {"a": "Ja. HeyGen Video Translation ist eines der besten Tools für Video-Lokalisierung. Es übersetzt nicht nur den Audio sondern synchronisiert auch die Lippenbewegungen auf die neue Sprache. 40+ Sprachen werden unterstützt.", "q": "Kann HeyGen Videos übersetzen?"}, {"a": "Moderne KI-Avatare von HeyGen und Synthesia sind für professionelle Präsentationen und E-Learning überzeugend. Sie sind ideal für Schulungsvideos, Produktdemos und interne Kommunikation. Für emotionale Marketingvideos die menschliche Verbindung erfordern sind echte Kameras noch besser.", "q": "Sind KI-Avatar-Videos überzeugend?"}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "HeyGen лидирует по переводу видео (дублированию с синхронизацией губ на 175+ языках) и качеству аватаров. Synthesia лидирует по корпоративным функциям, соответствию требованиям и интеграции LMS для корпоративного обучения. HeyGen — для маркетинга, Synthesia — для L&D-команд.", "q": "В чём разница между HeyGen и Synthesia?"}, {"a": "Да. HeyGen может клонировать ваш голос и создать ИИ-аватар, который выглядит и звучит как вы, из короткой записи. Используется для перевода видео — ваш аватар говорит на других языках вашим клонированным голосом.", "q": "Может ли HeyGen клонировать мой голос?"}, {"a": "Plan Creator HeyGen начинается от $29/мес (4 минуты видео). Business — $89/мес (15 минут). Корпоративные цены — индивидуальные. Кредиты для перевода видео продаются отдельно.", "q": "Сколько стоит HeyGen?"}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Synthesia краще для корпоративного навчання і HR: більше аватарів, мов і enterprise-функцій. HeyGen краще для маркетингу і продажових відео де потрібна персоналізація. Для L&D — Synthesia; для маркетингу — HeyGen.", "q": "HeyGen чи Synthesia для корпоративних відео?"}, {"a": "HeyGen має безкоштовний план з 1 хвилиною відео/міс. Платні від $29/міс. Synthesia від $29/міс; Enterprise за запитом.", "q": "HeyGen безкоштовний?"}, {"a": "Synthesia підтримує 140+ мов включно з українською. Ви можете генерувати навчальні відео з аватарами що говорять українською без записи живого спікера.", "q": "Чи підтримує Synthesia українську мову?"}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'ua';

