UPDATE tools SET faq = $x$[{"a": "Ideogram is an AI image generator specifically optimized for generating text within images. It excels at creating posters, logos, t-shirt designs, and any image where readable text is part of the visual. Ideogram 2.0 (2024) also added strong photorealism and design capabilities.", "q": "What is Ideogram AI?"}, {"a": "Ideogram has a free plan with 10 slow generations per day. Basic plan is $7/month, Plus is $16/month, Pro is $48/month. The free tier is generous for occasional use.", "q": "Is Ideogram free?"}]$x$::jsonb
