UPDATE tools SET faq = $x$[{"a": "Sí, claramente. Ideogram es el modelo líder para renderizar texto dentro de imágenes con precisión. Midjourney históricamente ha tenido problemas con texto — letras incorrectas, deformadas. Ideogram 3.0 genera texto tipográfico muy fiel al prompt. Para cualquier imagen con texto — Ideogram.", "q": "¿Ideogram es mejor que Midjourney para texto en imágenes?"}, {"a": "Ideogram sobresale en: texto tipográfico en imágenes, colores específicos de marca, estilos de diseño gráfico (carteles, logos). Midjourney supera en arte fotorrealista de alta complejidad y estilos artísticos únicos.", "q": "¿Qué puede hacer Ideogram que Midjourney no puede?"}]$x$::jsonb
 WHERE slug = 'ideogram' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Ideogram wurde speziell trainiert, lesbaren Text in Bilder zu integrieren. Das ist eine bekannte Schwäche anderer KI-Bildgeneratoren. Ideogram 3 kann Schriftzüge, Slogans und kurze Texte präzise und ästhetisch ansprechend darstellen.", "q": "Warum ist Ideogram gut für Text in Bildern?"}, {"a": "Für Poster mit Text — eindeutig Ideogram. Für rein visuelle, textfreie Poster — Midjourney liefert ausgereiftere künstlerische Qualität. Für Social-Media-Posts mit Typografie — Ideogram. Für Konzeptkunst und komplexe Illustrationen — Midjourney.", "q": "Ideogram vs Midjourney: Welches ist besser für Poster?"}]$x$::jsonb
 WHERE slug = 'ideogram' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Ideogram — генератор ИИ-изображений, оптимизированный для генерации текста внутри изображений. Превосходит в создании плакатов, логотипов, дизайна футболок и любых изображений, где разборчивый текст — часть визуала. Ideogram 2.0 (2024) также добавил сильный фотореализм.", "q": "Что такое Ideogram AI?"}, {"a": "У Ideogram есть бесплатный план с 10 медленными генерациями в день. Basic plan — $7/мес, Plus — $16/мес, Pro — $48/мес. Бесплатный уровень щедр для периодического использования.", "q": "Ideogram бесплатный?"}]$x$::jsonb
