UPDATE tools SET faq = $x$[{"a": "Jasper is one of the more expensive AI writing tools, starting at $49/month. For individual creators, Claude or ChatGPT offer comparable writing quality at lower cost. Jasper's value is in brand voice training and team collaboration features — worth it for marketing teams of 3+ people.", "q": "Is Jasper worth the price?"}, {"a": "Copy.ai focuses on marketing copy and workflow automation at a more accessible price. Jasper focuses on brand consistency and long-form content for enterprise teams. Copy.ai is better for solo marketers; Jasper is better for teams with strict brand guidelines.", "q": "What is the difference between Copy.ai and Jasper?"}]$x$::jsonb
 WHERE slug = 'jasper' AND lang = 'en';

