UPDATE tools SET faq = $x$[{"a": "У Writesonic есть бесплатный пробный период с 25 кредитами. Individual plan начинается от $16/мес, Small Team — $45/мес. Корпоративные планы — индивидуальные. В целом дешевле Jasper при сопоставимых функциях.", "q": "Writesonic бесплатный?"}, {"a": "Jasper интегрируется с Surfer SEO для оптимизации контента. Эта комбинация — Jasper для написания, Surfer для оптимизации — популярна среди команд контент-маркетинга. Jasper сам по себе не включает SEO-анализ, Surfer нужно добавлять отдельно.", "q": "Есть ли у Jasper SEO-инструменты?"}]$x$::jsonb
