UPDATE tools SET faq = $x$[{"a": "Julius AI is a conversational data analysis tool. You upload CSV files, connect databases, or link Google Sheets, then ask questions in plain language. Julius writes and runs the analysis, generates charts, and explains findings in plain English — no SQL or code needed.", "q": "What is Julius AI?"}, {"a": "Julius AI has a free plan with limited messages per month. Pro plan is $28/month for unlimited messages and advanced features. It's designed for individuals and small teams who analyze data regularly.", "q": "Is Julius AI free?"}, {"a": "Julius AI is purpose-built for data analysis with persistent file uploads, code execution, and chart generation optimized for data tasks. ChatGPT with the data analysis tool (code interpreter) does similar things but is more general-purpose. Julius has a cleaner data-focused UX.", "q": "What is the difference between Julius AI and ChatGPT for data?"}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "DataRobot está más orientado a empresas grandes con equipos de datos — más potente pero mucho más caro. Akkio está diseñado para equipos de negocio sin científicos de datos — más accesible y fácil de configurar. Para PMEs y equipos de marketing/ventas — Akkio; para grandes empresas con datos complejos — DataRobot.", "q": "¿Akkio o DataRobot para ML sin código?"}, {"a": "Akkio tiene un plan gratuito limitado con proyectos básicos. Los planes de pago empiezan desde $49/mes. Julius AI tiene plan gratuito con 15 análisis/mes; planes desde $22/mes.", "q": "¿Akkio es gratuito?"}, {"a": "Julius AI puede hacer análisis estadísticos y regresiones básicas, pero no está diseñado para construir modelos predictivos de producción. Akkio está específicamente hecho para crear modelos de predicción (churn, conversión, forecasting) listos para integrar en sistemas de negocio.", "q": "¿Julius AI puede construir modelos predictivos?"}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Akkio ist für prädiktive Machine-Learning-Modelle: Sie trainieren ein Modell das zukünftige Ereignisse vorhersagt. Julius AI ist für explorative Analyse: Sie stellen Fragen an bestehende Daten und erhalten sofort Insights. Akkio für Vorhersagen; Julius für Analyse.", "q": "Akkio vs Julius AI: Was ist der Unterschied?"}, {"a": "Akkio hat einen kostenlosen Plan mit eingeschränkten Funktionen. Kostenpflichtige Pläne ab $50/Monat. Julius AI hat einen kostenlosen Plan; Pro ab $22,99/Monat.", "q": "Ist Akkio kostenlos?"}, {"a": "Ja. Akkio ist populär für CRM-Daten: Lead-Scoring, Churn-Vorhersage und Umsatz-Prognosen aus HubSpot, Salesforce oder CSV-Exporten. Ohne Data-Science-Kenntnisse können Marketing-Teams Vorhersagemodelle trainieren.", "q": "Akkio für CRM-Daten: Ist es geeignet?"}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Julius AI — инструмент разговорного анализа данных. Загружаете CSV-файлы, подключаете базы данных или Google Sheets, затем задаёте вопросы на обычном языке. Julius пишет и запускает анализ, генерирует графики и объясняет результаты на простом языке — без SQL или кода.", "q": "Что такое Julius AI?"}, {"a": "У Julius AI есть бесплатный план с ограниченным количеством сообщений в месяц. Plan Pro — $28/мес для неограниченных сообщений и расширенных функций. Предназначен для отдельных специалистов и небольших команд, регулярно анализирующих данные.", "q": "Julius AI бесплатный?"}, {"a": "Julius AI специально создан для анализа данных с постоянными загрузками файлов, выполнением кода и генерацией графиков, оптимизированными для задач с данными. ChatGPT с инструментом анализа данных делает аналогичные вещи, но более универсально. У Julius более чистый UX, ориентированный на данные.", "q": "В чём разница между Julius AI и ChatGPT для данных?"}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Julius AI спеціалізований для даних: завантажте файл і отримуйте аналіз. ChatGPT більш загальний і має обмежені можливості роботи з файлами. Для аналізу даних Julius AI зручніший; для загальних задач — ChatGPT.", "q": "Julius AI vs ChatGPT для аналізу даних — яка різниця?"}, {"a": "Julius AI має безкоштовний план з обмеженим числом повідомлень. Pro від $20/міс. Looker Studio повністю безкоштовний.", "q": "Julius AI безкоштовний?"}, {"a": "Так. Julius AI може генерувати SQL-запити і виконувати їх проти ваших даних. Він також пояснює що робить SQL і інтерпретує результати.", "q": "Julius AI може писати SQL?"}]$x$::jsonb
