UPDATE tools SET faq = $x$[{"a": "Khanmigo is Khan Academy's AI tutor powered by GPT-4. It helps students with academic subjects using the Socratic method — asking guiding questions rather than giving direct answers. It's free for students in the US thanks to Khan Academy funding.", "q": "What is Khanmigo?"}, {"a": "Khanmigo is free for students in the United States. For schools and districts, Khanmigo is available through Khan Academy's district programs. Outside the US, it requires a Khan Academy donation of $4+/month to access.", "q": "Is Khanmigo free?"}, {"a": "Duolingo builds vocabulary and basic grammar effectively but is generally not sufficient to reach fluency alone. It works best as a daily habit combined with other practice like speaking with native speakers, watching content, or using tools like iTalki for conversation practice.", "q": "Can Duolingo teach me to be fluent?"}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Coursera Coach está incluido en los planes de pago de Coursera (Coursera Plus desde $59/mes o $399/año). No está disponible en el acceso gratuito. Khanmigo cuesta $9/mes o $44/año independientemente, con Khan Academy gratuito aparte.", "q": "¿Coursera Coach es gratuito?"}, {"a": "Khanmigo puede ayudar con materias universitarias si el contenido está en Khan Academy (cálculo, estadística, ciencias, economía, etc.). Para cursos específicos de plataformas de e-learning como Coursera — el contexto del curso no está disponible para Khanmigo.", "q": "¿Khanmigo puede ayudar con cursos universitarios?"}, {"a": "Alternativas para apoyo en e-learning: Khanmigo (Khan Academy), Synthesis Tutor, herramientas de estudio como Quizlet con IA, o directamente ChatGPT/Claude para preguntas sobre el material del curso. También Duolingo Max para idiomas y Photomath para matemáticas.", "q": "¿Hay alternativas a Coursera Coach?"}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Für Hochschul- und Berufsausbildungs-Kurse — Coursera Coach (direkt im Kurs). Für Schulfächer und Khan Academy-Content — Khanmigo. Beide haben ihren Platz: Coursera für professionelle Weiterbildung; Khanmigo für schulische Grundfächer.", "q": "Coursera Coach vs Khanmigo: Wer ist besser für Studenten?"}, {"a": "Coursera Coach ist in Coursera Plus ($59/Monat oder $399/Jahr) enthalten. Einzelne Kurse auf Coursera können kostenlos auditiert werden aber ohne vollen Zugang zu Coach-Features. Khanmigo kostet $4/Monat.", "q": "Ist Coursera Coach kostenlos?"}, {"a": "Coursera Coach versteht Deutsch und kann auf Deutsch antworten. Viele Coursera-Kurse sind jedoch auf Englisch. Für deutschsprachige Kurse und German-Language-Support funktioniert Coach gut, aber die Kurs-Qualität hängt vom verfügbaren deutschen Content ab.", "q": "Kann Coursera Coach auf Deutsch helfen?"}]$x$::jsonb
