UPDATE tools SET faq = $x$[{"a": "Krea AI ist ein KI-Kreativtool mit einzigartiger Echtzeit-Canvas-Funktion: Sie zeichnen oder platzieren Elemente und KI generiert sofort live ein Bild basierend auf Ihrer Skizze. Außerdem bietet Krea leistungsstarkes Upscaling und Bildverbesserung.", "q": "Was ist Krea AI?"}, {"a": "Krea's Echtzeit-Canvas ist einzigartig — kein anderes Tool der Klasse bietet live KI-Generierung während Sie zeichnen. Midjourney führt bei statischer Bild-Qualität und künstlerischer Ausgereiftheit. Krea für interaktive kreative Exploration; Midjourney für finale Qualität.", "q": "Krea AI vs Midjourney: Was ist einzigartiger?"}, {"a": "Krea's Upscaler ist einer der besten verfügbaren — er erhöht nicht nur die Auflösung sondern verbessert Details und Schärfe erheblich. Für professionelle Bildveredelung ist Krea's Upscaling tool eine der besten Optionen auf dem Markt.", "q": "Krea AI Upscaling: Wie gut ist es?"}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Krea AI предлагает уникальную генерацию в реальном времени и усиление изображений. Midjourney V7 превосходит по художественному качеству и эстетике финальных результатов. Krea — для интерактивного процесса, Midjourney — для лучших результатов.", "q": "Krea AI vs Midjourney — в чём разница?"}, {"a": "Да. Krea AI предлагает бесплатный план с ограниченными генерациями в реальном времени. Starter — $24/мес, Pro — $96/мес для профессиональных объёмов.", "q": "Krea AI бесплатный?"}, {"a": "Да. Krea AI Enhance увеличивает разрешение и улучшает детализацию существующих изображений и фотографий с помощью ИИ. Это одна из ключевых функций платформы наряду с генерацией в реальном времени.", "q": "Krea AI улучшает существующие фотографии?"}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Krea AI орієнтований на інтерактивну генерацію в реальному часі: малюйте і бачте ШІ-результат миттєво. Midjourney орієнтований на найвищу художню якість фінального результату. Krea для ітерації; Midjourney для якості.", "q": "Krea AI vs Midjourney — яка різниця?"}, {"a": "Krea AI має безкоштовний план з обмеженнями. Платні плани від $24/міс. Midjourney від $10/міс; немає безкоштовного плану.", "q": "Krea AI безкоштовний?"}, {"a": "Так. Krea AI дуже популярний серед дизайнерів і концепт-художників за його інтерактивний воркфлоу. Він добре інтегрується в дизайнерські процеси де потрібна швидка ітерація і візуальний зворотній зв'язок.", "q": "Krea AI для дизайнерів?"}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Krea מצוין לעריכה אינטראקטיבית ו-Upscaling. Midjourney הסטנדרט לאיכות אמנות AI. Krea לעריכה וגמישות; Midjourney לאיכות אמנות.", "q": "Krea AI לעומת Midjourney – מה עדיף?"}, {"a": "Krea מציע תוכנית חינמית מוגבלת; Basic מ-$10/חודש. Midjourney מ-$10/חודש; לא מציע תוכנית חינמית.", "q": "Krea AI חינמי?"}, {"a": "Midjourney מבין פרומפטים באנגלית בעיקר. תרגמו פרומפטים לאנגלית לתוצאות מיטביות. הוספת עברית לפרומפט עשויה לעבוד אך לא מיטבי.", "q": "Midjourney לעברית – האם הפרומפטים עובדים?"}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Krea AI se distingue par sa génération en temps réel et ses fonctionnalités d'idéation créative. Midjourney est le standard pour l'art IA de haute qualité avec une communauté massive. Pour l'exploration créative en temps réel → Krea ; pour la qualité artistique finale → Midjourney.", "q": "Krea AI vs Midjourney — quelle est la différence ?"}, {"a": "Krea AI a un plan gratuit avec des crédits limités. Les plans payants à partir de 10 $/mois. Midjourney à partir de 10 $/mois sans plan gratuit permanent.", "q": "Krea AI est-il gratuit ?"}, {"a": "Krea AI Real-Time montre la génération IA en direct pendant que vous dessinez ou modifiez votre prompt. L'image se met à jour en quelques secondes à chaque modification. C'est révolutionnaire pour l'idéation créative rapide.", "q": "Krea AI Real-Time — comment ça fonctionne ?"}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Krea AI se destaca pela geração em tempo real e funcionalidades de ideação criativa. Midjourney é o padrão para arte de IA de alta qualidade com comunidade enorme. Para exploração criativa em tempo real → Krea; para qualidade artística final → Midjourney.", "q": "Krea AI vs Midjourney — qual é a diferença?"}, {"a": "Krea AI tem plano gratuito com créditos limitados. Planos pagos a partir de $10/mês. Midjourney a partir de $10/mês sem plano gratuito permanente.", "q": "Krea AI é gratuito?"}, {"a": "Krea AI Real-Time mostra a geração de IA ao vivo enquanto você desenha ou modifica seu prompt. A imagem se atualiza em segundos a cada modificação. É revolucionário para ideação criativa rápida.", "q": "Krea AI Real-Time — como funciona?"}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Leonardo.ai is an AI image generation platform popular with game developers, concept artists, and designers. It offers fine-tuning on custom image sets, a canvas editor, motion generation, and character reference features for maintaining consistency across a series of images.", "q": "What is Leonardo.ai used for?"}, {"a": "Leonardo.ai has a free plan with 150 tokens per day (roughly 30 standard images). Apprentice Membership is $12/month, Artisan is $30/month, Maestro is $60/month, offering more tokens, priority generation, and additional features.", "q": "Is Leonardo AI free?"}, {"a": "Leonardo.ai is built on top of Stable Diffusion but adds a curated platform experience, fine-tuned models, better UI, and community features. For users who don't want to set up local Stable Diffusion, Leonardo offers similar capabilities with significantly less technical setup.", "q": "Is Leonardo.ai better than Stable Diffusion?"}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Nano Banana es una herramienta de generación de imágenes IA diseñada con simplicidad extrema como prioridad. Su propuesta es hacer accesible la generación de imágenes IA sin la complejidad técnica de otras plataformas. Está orientada a usuarios que quieren resultados rápidos sin aprender parámetros.", "q": "¿Qué es Nano Banana?"}, {"a": "Sí. Leonardo AI tiene un plan gratuito muy generoso con 150 tokens diarios (cada imagen cuesta 1-8 tokens según el modelo y resolución). Esto permite generar decenas de imágenes al día sin pagar. Los planes de pago (desde $12/mes) añaden tokens ilimitados y funciones avanzadas.", "q": "¿Leonardo AI tiene plan gratuito?"}, {"a": "Leonardo AI tiene más funciones que Nano Banana, pero tiene una interfaz razonablemente accesible. El plan gratuito generoso lo hace ideal para experimentar. Para principiantes absolutos — Nano Banana es más simple; para principiantes que quieren aprender más — Leonardo AI con su plan gratuito es excelente.", "q": "¿Leonardo AI es bueno para principiantes?"}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Leonardo AI ist bekannter, ausgereifter und hat mehr Features speziell für Game-Entwickler und kreative Profis. Nano Banana positioniert sich als schnellere, günstigere Alternative. Für professionelle kreative Arbeit — Leonardo; für einfache schnelle Generierung — Nano Banana.", "q": "Nano Banana vs Leonardo AI: Was ist besser?"}, {"a": "Leonardo AI hat einen kostenlosen Plan mit 150 Token täglich (ca. 30-150 Bilder je nach Einstellungen). Pro ab $12/Monat. Das kostenlose Angebot ist für regelmäßige Nutzung sehr großzügig.", "q": "Ist Leonardo AI kostenlos?"}, {"a": "Ja. Leonardo AI hat spezifische Modelle für Game Assets trainiert und bietet 3D-Textur-Generierung. Es wird von vielen Indie-Spieleentwicklern für Character Sprites, Concept Art und Texture Maps genutzt.", "q": "Leonardo AI für Spieleentwickler: Ist es gut?"}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Leonardo.ai — платформа генерации ИИ-изображений, популярная среди разработчиков игр, концепт-художников и дизайнеров. Предлагает дообучение на кастомных наборах изображений, редактор холста, генерацию движения и функции эталонных персонажей для поддержания согласованности в серии изображений.", "q": "Для чего используется Leonardo.ai?"}, {"a": "У Leonardo.ai есть бесплатный план со 150 токенами в день (примерно 30 стандартных изображений). Членство Apprentice — $12/мес, Artisan — $30/мес, Maestro — $60/мес — с большим числом токенов и приоритетной генерацией.", "q": "Leonardo AI бесплатный?"}, {"a": "Leonardo.ai построен поверх Stable Diffusion, но добавляет кураторский платформенный опыт, дообученные модели, лучший UI и функции сообщества. Для пользователей, не желающих настраивать локальный Stable Diffusion, Leonardo предлагает аналогичные возможности с гораздо меньшей технической настройкой.", "q": "Leonardo.ai лучше Stable Diffusion?"}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Leonardo AI дає більше контролю через кастомні моделі і LoRA; підходить для геймдеву і послідовних стилів. Midjourney виробляє якісніший вихідний продукт з меншими зусиллями. Для контролю і геймдеву — Leonardo; для якості — Midjourney.", "q": "Leonardo AI vs Midjourney — різниця?"}, {"a": "Leonardo AI має безкоштовний план з 150 токенів/день. Платні плани від $12/міс. Nano Banana — перевірте поточне ціноутворення на офіційному сайті.", "q": "Leonardo AI безкоштовний?"}, {"a": "Так. Зображення згенеровані у Leonardo AI можна використовувати комерційно на платних планах. Перевірте умови використання для конкретних деталей за поточними правилами.", "q": "Leonardo AI для комерційного використання?"}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Nano Banana מתמקד בפשטות ובמהירות. Leonardo AI מקיף יותר עם כלים מקצועיים. Nano Banana למשתמשים מזדמנים; Leonardo AI לאנשי מקצוע יצירתיים.", "q": "Nano Banana לעומת Leonardo AI?"}, {"a": "Leonardo AI מציע 150 tokens יומיים חינם; Apprentice מ-$12/חודש. בדקו את אתר Nano Banana לפרטי מחיר עדכניים.", "q": "Leonardo AI חינמי?"}, {"a": "כן, Leonardo AI פופולרי מאוד בפיתוח משחקים לגנרציית Sprites, Textures ו-Character Art. יש לו pipeline מובנה לנכסי Game Assets.", "q": "Leonardo AI לגנרציית נכסי משחק?"}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Leonardo AI est plus établi avec plus de fonctionnalités, une communauté plus grande et un plan gratuit généreux. Nano Banana est une alternative plus récente. Pour une plateforme éprouvée → Leonardo AI.", "q": "Nano Banana vs Leonardo AI — lequel est le meilleur ?"}, {"a": "Vérifiez le site actuel de Nano Banana pour les tarifs à jour. Leonardo AI a un plan gratuit avec 150 tokens par jour ; payants à partir de 12 $/mois.", "q": "Nano Banana est-il gratuit ?"}, {"a": "Oui. Leonardo AI est particulièrement apprécié pour les actifs de jeux : personnages cohérents, textures, icônes et environnements. Le fine-tuning permet de maintenir un style visuel cohérent sur plusieurs générations.", "q": "Leonardo AI est-il bon pour les illustrations de jeux ?"}]$x$::jsonb
