UPDATE tools SET faq = $x$[{"a": "Leonardo AI é mais estabelecido com mais funcionalidades, comunidade maior e plano gratuito generoso. Nano Banana é uma alternativa mais recente. Para uma plataforma consolidada → Leonardo AI.", "q": "Nano Banana vs Leonardo AI — qual é o melhor?"}, {"a": "Verifique o site atual do Nano Banana para preços atualizados. Leonardo AI tem plano gratuito com 150 tokens por dia; pagos a partir de $12/mês.", "q": "Nano Banana é gratuito?"}, {"a": "Sim. Leonardo AI é particularmente apreciado para assets de jogos: personagens consistentes, texturas, ícones e ambientes. O fine-tuning permite manter um estilo visual consistente em múltiplas gerações.", "q": "Leonardo AI é bom para ilustrações de jogos?"}]$x$::jsonb
