UPDATE tools SET faq = $x$[{"a": "Lindy is an AI assistant platform that builds personal and business AI agents. Agents can handle email management, meeting preparation, CRM updates, research, and customer support. You connect Lindy to your apps (Gmail, Slack, Salesforce) and define workflows for it to execute.", "q": "What is Lindy AI?"}, {"a": "Lindy has a free plan with 400 tasks per month. Paid plans start at $49.99/month for 5,000 tasks. Teams and Enterprise plans offer higher task limits and multi-user features.", "q": "Is Lindy AI free?"}, {"a": "Zapier automates fixed, rule-based workflows between apps. Lindy uses AI to handle variable situations — reading emails, making decisions, responding contextually. Zapier is better for predictable automation; Lindy is better when tasks require judgment and natural language.", "q": "What is the difference between Lindy and Zapier?"}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Lindy es una plataforma de agentes de IA para automatización personal y empresarial. Permite crear 'Lindys' (agentes) que gestionan correos, programan reuniones, califican leads y ejecutan flujos de trabajo de forma autónoma. Diseñado para usuarios no técnicos.", "q": "¿Qué es Lindy?"}, {"a": "Lindy tiene un plan gratuito con funciones limitadas. Los planes de pago empiezan desde $49/mes. Copilot Studio tiene 25.000 mensajes gratuitos; licencias empresariales desde $200/mes.", "q": "¿Lindy es gratuito?"}, {"a": "Sí. Lindy conecta tu Gmail o Outlook y puede clasificar, responder o reenviar correos según tus instrucciones. Puede calificar leads entrantes o responder preguntas frecuentes automáticamente.", "q": "¿Lindy puede gestionar mi correo electrónico?"}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Lindy ist eine KI-Agenten-Plattform für persönliche und geschäftliche Automatisierung. Sie ermöglicht die Erstellung von 'Lindys' (Agenten), die E-Mails verwalten, Meetings planen, Leads qualifizieren und Workflows autonom ausführen. Für nicht-technische Nutzer konzipiert.", "q": "Was ist Lindy?"}, {"a": "Lindy hat einen kostenlosen Plan mit begrenzten Funktionen. Kostenpflichtige Pläne beginnen ab $49/Monat. Copilot Studio beinhaltet 25.000 kostenlose Nachrichten; Enterprise-Lizenzen ab $200/Monat.", "q": "Ist Lindy kostenlos?"}, {"a": "Ja. Lindy verbindet Ihr Gmail oder Outlook und kann E-Mails klassifizieren, beantworten oder weiterleiten gemäß Ihren Anweisungen. Es kann eingehende Leads qualifizieren oder häufig gestellte Fragen automatisch beantworten.", "q": "Kann Lindy meine E-Mails verwalten?"}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Lindy — платформа ИИ-ассистентов, создающая личных и бизнес-агентов. Агенты могут управлять электронной почтой, подготавливать встречи, обновлять CRM, проводить исследования и обрабатывать клиентскую поддержку. Подключаете Lindy к своим приложениям (Gmail, Slack, Salesforce) и определяете рабочие процессы.", "q": "Что такое Lindy AI?"}, {"a": "У Lindy есть бесплатный план с 400 задачами в месяц. Платные планы начинаются от $49.99/мес для 5000 задач. Планы Teams и Enterprise предлагают более высокие лимиты задач и многопользовательские функции.", "q": "Lindy AI бесплатный?"}, {"a": "Zapier автоматизирует фиксированные, основанные на правилах рабочие процессы между приложениями. Lindy использует ИИ для обработки переменных ситуаций — чтения писем, принятия решений, контекстного ответа. Zapier лучше для предсказуемой автоматизации, Lindy — когда задачи требуют суждения и естественного языка.", "q": "В чём разница между Lindy и Zapier?"}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Lindy — платформа для побудови персональних ШІ-агентів без коду. Агенти Lindy можуть управляти email, планувати зустрічі, відповідати клієнтам і автоматизувати повторювані завдання. Позиціонується як «ШІ-асистент що справді діє».", "q": "Що таке Lindy AI?"}, {"a": "Lindy має безкоштовний план з обмеженнями. Платні плани залежать від кількості дій. Microsoft Copilot Studio від $200/міс.", "q": "Lindy AI безкоштовний?"}, {"a": "Lindy фокусується на агентах — ШІ що приймає рішення і діє самостійно. Zapier — детерміновані автоматизації типу якщо-то. Lindy більш гнучкий для завдань де потрібно розуміння; Zapier більш надійний для структурованих потоків.", "q": "Lindy vs Zapier — різниця?"}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Lindy הוא פלטפורמה לבניית סוכני AI אישיים ללא קוד. סוכני Lindy יכולים לנהל אימייל, לתזמן פגישות, לענות ללקוחות ולאטמט משימות חוזרות. ממוצב כ'עוזר AI שבאמת פועל'.", "q": "מה זה Lindy AI?"}, {"a": "ל-Lindy יש תוכנית חינמית עם הגבלות. תוכניות בתשלום לפי מספר פעולות. Microsoft Copilot Studio מ-200$/חודש.", "q": "האם Lindy AI בחינם?"}, {"a": "Lindy מתמקד בסוכנים — AI שמקבל החלטות ופועל באופן עצמאי. Zapier הוא אוטומציות דטרמיניסטיות מסוג אם-אז. Lindy גמיש יותר למשימות שדורשות הבנה; Zapier אמין יותר לזרימות מובנות.", "q": "Lindy מול Zapier — מה ההבדל?"}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Lindy est une plateforme pour créer des agents IA personnels sans code. Les agents Lindy peuvent gérer les emails, planifier des réunions, répondre aux clients et automatiser les tâches répétitives. Il est positionné comme un 'assistant IA qui agit vraiment'.", "q": "Qu'est-ce que Lindy AI ?"}, {"a": "Lindy a un plan gratuit avec des limites. Les plans payants dépendent du nombre d'actions. Microsoft Copilot Studio à partir de 200 $/mois.", "q": "Lindy AI est-il gratuit ?"}, {"a": "Lindy se concentre sur les agents — des IA qui prennent des décisions et agissent de manière autonome. Zapier automatise des flux déterministes de type si-alors. Lindy est plus flexible pour les tâches nécessitant une compréhension ; Zapier plus fiable pour les flux structurés.", "q": "Lindy vs Zapier — quelle est la différence ?"}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Lindy é uma plataforma para criar agentes de IA pessoais sem código. Os agentes Lindy podem gerenciar emails, agendar reuniões, responder clientes e automatizar tarefas repetitivas. É posicionado como um 'assistente de IA que realmente age'.", "q": "O que é Lindy AI?"}, {"a": "Lindy tem um plano gratuito com limites. Os planos pagos dependem do número de ações. Microsoft Copilot Studio a partir de $200/mês.", "q": "Lindy AI é gratuito?"}, {"a": "Lindy foca em agentes — IAs que tomam decisões e agem autonomamente. Zapier automatiza fluxos determinísticos do tipo se-então. Lindy é mais flexível para tarefas que requerem compreensão; Zapier é mais confiável para fluxos estruturados.", "q": "Lindy vs Zapier — qual é a diferença?"}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Dream Machine is Luma AI's text-to-video and image-to-video generator. It's known for producing smooth, physically realistic motion. The free tier allows daily video generation. Luma AI also makes Genie (3D generation) and builds AI infrastructure for other products.", "q": "What is Luma Dream Machine?"}, {"a": "Luma AI has a free tier with limited monthly credits, watermarks and non-commercial use only. Paid plans are Plus at $30/month, Pro at $90/month and Ultra at $300/month, dropping to $25, $75 and $250 when billed yearly. Team and Enterprise are quoted by sales.", "q": "Is Luma AI free?"}, {"a": "Sora (OpenAI) and Dream Machine target different strengths. Sora produces longer, more complex videos with stronger story coherence. Dream Machine produces excellent short clips with smooth motion at a lower cost and with a free tier. Runway Gen-4.5 is generally considered the current quality leader.", "q": "Is Dream Machine better than Sora?"}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Luma Dream Machine v1.6 produce videos con calidad cinematográfica excelente, especialmente en fluidez de movimiento. Runway Gen-3 Alpha tiene más herramientas de edición integradas. Para generación pura de alta calidad — Dream Machine compite muy bien; para producción integral — Runway.", "q": "¿Luma Dream Machine o Runway Gen-3?"}, {"a": "Luma AI tiene un plan gratuito con créditos mensuales limitados, marca de agua y uso no comercial. Los planes de pago son Plus 30 $/mes, Pro 90 $/mes y Ultra 300 $/mes, que bajan a 25 $, 75 $ y 250 $ con pago anual. Team y Enterprise se cotizan con ventas.", "q": "¿Luma AI es gratuito?"}, {"a": "Luma AI también tiene capacidades de 3D: puede crear escenas 3D y objetos en 3D desde fotos o video usando NeRF (Neural Radiance Fields). Esta funcionalidad 3D es única y complementa la generación de video para producción creativa.", "q": "¿Qué más hace Luma AI además de video?"}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Runway ist insgesamt ausgereifter mit mehr professionellen Kontrollmöglichkeiten. Luma AI (Dream Machine) ist günstiger und hat ausgezeichnete Kamera-Bewegungen. Luma für kosteneffiziente Produktion; Runway für maximale professionelle Kontrolle.", "q": "Luma AI vs Runway: Welches ist besser?"}, {"a": "Luma Dream Machine ist Luma AI's Video-Generierungsmodell. Es erstellt Videos aus Text oder Bildern mit besonders flüssigen Kamerabewegungen. Dream Machine 1.6 hat gegenüber der ersten Version erhebliche Qualitätsverbesserungen gebracht.", "q": "Was ist Luma Dream Machine?"}, {"a": "Luma AI begann als 3D-Capture-Tool: Sie filmen ein Objekt mit Ihrem Smartphone und Luma erstellt ein fotorealistisches 3D-NeRF-Modell. Diese Technologie wird für AR, Produktvisualisierung und Gaming genutzt. Dream Machine ist eine spätere Ergänzung.", "q": "Was macht Luma AI ursprünglich?"}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Dream Machine — генератор text-to-video и image-to-video от Luma AI. Известен плавным, физически реалистичным движением. Бесплатный уровень позволяет ежедневно генерировать видео. Luma AI также создаёт Genie (3D-генерация) и строит ИИ-инфраструктуру для других продуктов.", "q": "Что такое Luma Dream Machine?"}, {"a": "У Luma AI есть бесплатный тариф с ограниченными месячными кредитами, водяным знаком и без коммерческого использования. Платные: Plus $30/мес, Pro $90/мес и Ultra $300/мес; при годовой оплате $25, $75 и $250. Team и Enterprise — через отдел продаж.", "q": "Luma AI бесплатный?"}, {"a": "Sora (OpenAI) и Dream Machine нацелены на разные сильные стороны. Sora производит более длинные, сложные видео с лучшей сюжетной связностью. Dream Machine производит отличные короткие клипы с плавным движением по более низкой цене и с бесплатным уровнем. Runway Gen-4.5 в целом считается текущим лидером по качеству.", "q": "Dream Machine лучше Sora?"}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Luma AI цікавий для 3D-захоплення і Dream Machine відео. Runway — повноцінна відео-платформа з більше інструментами. Для 3D і базових відео — Luma; для повного відео-workflow — Runway.", "q": "Luma AI чи Runway?"}, {"a": "У Luma AI є безкоштовний тариф з обмеженими місячними кредитами, водяним знаком і без комерційного використання. Платні: Plus $30/міс, Pro $90/міс та Ultra $300/міс; за річної оплати $25, $75 і $250. Team та Enterprise — через відділ продажів.", "q": "Luma Dream Machine безкоштовний?"}, {"a": "NeRF (Neural Radiance Fields) — технологія для захоплення 3D-об'єктів з фото і відео. Luma AI спростив NeRF: знімете об'єкт телефоном → отримуєте 3D-модель. Популярно для ігор, доповненої реальності і 3D-дизайну.", "q": "Що таке NeRF і чим відомий Luma AI?"}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Luma AI מוביל בריאליזם פיזיקלי ותנועת מצלמה. Runway מוביל בשליטה מתקדמת ובכלי עריכה. לסצנות ריאליסטיות — Luma; לשליטה ועריכה — Runway.", "q": "Luma AI מול Runway — מה עדיף?"}, {"a": "ל-Luma AI יש שכבה חינמית עם קרדיטים חודשיים מוגבלים, סימן מים ושימוש לא מסחרי. המסלולים בתשלום הם Plus ב-30$ לחודש, Pro ב-90$ ו-Ultra ב-300$; בתשלום שנתי 25$, 75$ ו-250$. Team ו-Enterprise דרך צוות המכירות.", "q": "Luma Dream Machine בחינם?"}, {"a": "Luma AI התחילה בצילום תלת-ממדי (NeRF — Neural Radiance Fields) מסרטי וידאו. ה-Dream Machine הוא מוצר יצירת הוידאו שלהם, שמנצל ידע בפיזיקת תלת-ממד.", "q": "Luma AI לתלת-ממד — מה זה?"}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Luma AI (Dream Machine) est très apprécié pour le réalisme et la qualité de mouvement. Runway a plus de fonctionnalités avancées pour l'édition et le contrôle professionnel. Pour la qualité brute, Luma est souvent cité ; pour le contrôle professionnel, Runway.", "q": "Luma AI vs Runway — lequel est le meilleur ?"}, {"a": "Luma AI propose une offre gratuite avec des crédits mensuels limités, un filigrane et un usage non commercial. Les forfaits payants sont Plus à 30 $/mois, Pro à 90 $/mois et Ultra à 300 $/mois, soit 25 $, 75 $ et 250 $ en facturation annuelle. Team et Enterprise passent par le service commercial.", "q": "Luma AI est-il gratuit ?"}, {"a": "Luma AI a commencé avec la technologie NeRF (Neural Radiance Fields) pour créer des scènes 3D photoréalistes à partir de vidéos tournées avec un smartphone. Dream Machine est leur produit de génération vidéo text-to-video.", "q": "Qu'est-ce que Luma AI NeRF ?"}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Luma AI é líder em fotogrametria 3D e captura de cenas. Runway é melhor para geração e edição criativa de vídeo 2D. Para 3D e RA, Luma; para produção de vídeo criativo, Runway.", "q": "Luma AI vs Runway — qual escolher?"}, {"a": "Luma AI tem plano gratuito com capturas 3D limitadas. O Dream Machine (geração de vídeo) tem plano gratuito limitado. Runway tem plano gratuito com 125 créditos.", "q": "Luma AI é gratuito?"}, {"a": "Sim, Luma AI tem aplicativo iOS que usa a câmera LiDAR dos iPhones Pro para captura 3D de alta qualidade. É uma das maneiras mais fáceis de criar modelos 3D realistas.", "q": "Luma AI funciona em iPhone?"}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Copilot Studio is Microsoft's no-code platform for building custom AI chatbots and agents. It integrates with Microsoft 365, Teams, SharePoint, and Power Platform. Organizations use it to create HR bots, customer service agents, and internal knowledge assistants.", "q": "What is Microsoft Copilot Studio?"}, {"a": "Copilot Studio requires a Microsoft 365 subscription. It includes 25,000 generative AI messages per month per tenant on paid plans. Additional message packs are available. The pricing model is complex — contact Microsoft for enterprise pricing.", "q": "Is Copilot Studio free?"}]$x$::jsonb
 WHERE slug = 'microsoft-copilot-studio' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Microsoft Copilot Studio es una plataforma no-code/low-code para construir agentes de IA personalizados. Antes conocido como Power Virtual Agents, permite crear bots integrados con Microsoft 365, Teams y otras aplicaciones empresariales.", "q": "¿Qué es Copilot Studio?"}, {"a": "Copilot Studio incluye un plan gratuito con 25.000 mensajes mensuales. Los planes de pago empiezan desde $200/mes. Manus tiene acceso limitado gratuito; la suscripción completa requiere pago.", "q": "¿Copilot Studio es gratuito?"}]$x$::jsonb
 WHERE slug = 'microsoft-copilot-studio' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Copilot Studio — платформа Microsoft без кода для создания кастомных ИИ-чатботов и агентов. Интегрируется с Microsoft 365, Teams, SharePoint и Power Platform. Организации используют её для создания HR-ботов, агентов клиентского сервиса и внутренних помощников по знаниям.", "q": "Что такое Microsoft Copilot Studio?"}, {"a": "Copilot Studio требует подписки Microsoft 365. Включает 25 000 генеративных сообщений ИИ в месяц на тенант на платных планах. Доступны дополнительные пакеты сообщений. Модель ценообразования сложная — свяжитесь с Microsoft для корпоративного ценообразования.", "q": "Copilot Studio бесплатный?"}]$x$::jsonb
 WHERE slug = 'microsoft-copilot-studio' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "For artistic and aesthetic quality, Midjourney generally produces more visually striking results. Firefly excels at photorealistic product images and brand-consistent visuals. The gap has narrowed significantly with Firefly 3 (2025).", "q": "Is Midjourney better quality than Adobe Firefly?"}, {"a": "No. As of 2025, Midjourney no longer offers a free trial. The cheapest plan is Basic at $10/month for approximately 200 image generations per month.", "q": "Does Midjourney have a free plan?"}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Krea AI tiene un plan gratuito con generaciones limitadas. Los planes de pago empiezan desde $24/mes (Standard) con mayor resolución y generaciones ilimitadas. Midjourney no tiene plan gratuito; desde $10/mes.", "q": "¿Krea AI es gratuito?"}, {"a": "Para concepto de producto con máxima calidad artística — Midjourney. Para exploración rápida e iterativa donde necesitas ver múltiples variaciones en tiempo real — Krea. Muchos diseñadores de producto usan Krea para exploración rápida y Midjourney para renders finales.", "q": "¿Midjourney o Krea para diseño de producto?"}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Krea's Echtzeit-Canvas ist einzigartig — kein anderes Tool der Klasse bietet live KI-Generierung während Sie zeichnen. Midjourney führt bei statischer Bild-Qualität und künstlerischer Ausgereiftheit. Krea für interaktive kreative Exploration; Midjourney für finale Qualität.", "q": "Krea AI vs Midjourney: Was ist einzigartiger?"}, {"a": "Krea's Upscaler ist einer der besten verfügbaren — er erhöht nicht nur die Auflösung sondern verbessert Details und Schärfe erheblich. Für professionelle Bildveredelung ist Krea's Upscaling tool eine der besten Optionen auf dem Markt.", "q": "Krea AI Upscaling: Wie gut ist es?"}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "FLUX.1 [schnell] — самая быстрая версия — доступна бесплатно с открытой лицензией через Hugging Face и ComfyUI. FLUX.1 [dev] — для некоммерческого использования. FLUX.1 [pro] — через API с оплатой за использование.", "q": "Flux бесплатный?"}, {"a": "Нет. Midjourney убрал бесплатный пробный период. Минимальный план Basic — $10/мес (~200 изображений). Flux в версии schnell — бесплатен.", "q": "Midjourney имеет бесплатный план?"}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Krea AI має безкоштовний план з обмеженнями. Платні плани від $24/міс. Midjourney від $10/міс; немає безкоштовного плану.", "q": "Krea AI безкоштовний?"}, {"a": "Так. Krea AI дуже популярний серед дизайнерів і концепт-художників за його інтерактивний воркфлоу. Він добре інтегрується в дизайнерські процеси де потрібна швидка ітерація і візуальний зворотній зв'язок.", "q": "Krea AI для дизайнерів?"}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Krea מציע תוכנית חינמית מוגבלת; Basic מ-$10/חודש. Midjourney מ-$10/חודש; לא מציע תוכנית חינמית.", "q": "Krea AI חינמי?"}, {"a": "Midjourney מבין פרומפטים באנגלית בעיקר. תרגמו פרומפטים לאנגלית לתוצאות מיטביות. הוספת עברית לפרומפט עשויה לעבוד אך לא מיטבי.", "q": "Midjourney לעברית – האם הפרומפטים עובדים?"}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Krea AI a un plan gratuit avec des crédits limités. Les plans payants à partir de 10 $/mois. Midjourney à partir de 10 $/mois sans plan gratuit permanent.", "q": "Krea AI est-il gratuit ?"}, {"a": "Krea AI Real-Time montre la génération IA en direct pendant que vous dessinez ou modifiez votre prompt. L'image se met à jour en quelques secondes à chaque modification. C'est révolutionnaire pour l'idéation créative rapide.", "q": "Krea AI Real-Time — comment ça fonctionne ?"}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Krea AI tem plano gratuito com créditos limitados. Planos pagos a partir de $10/mês. Midjourney a partir de $10/mês sem plano gratuito permanente.", "q": "Krea AI é gratuito?"}, {"a": "Krea AI Real-Time mostra a geração de IA ao vivo enquanto você desenha ou modifica seu prompt. A imagem se atualiza em segundos a cada modificação. É revolucionário para ideação criativa rápida.", "q": "Krea AI Real-Time — como funciona?"}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Le Chat is Mistral AI's conversational AI assistant, available at mistral.ai. It's powered by Mistral's own frontier models — Mistral Large, Mistral Small, and Pixtral. Mistral is a French AI company emphasizing European data sovereignty and open-weight model development.", "q": "What is Mistral Le Chat?"}, {"a": "Le Chat has a free plan with access to capable Mistral models. Le Chat Pro is €14.99/month for Mistral Large, image generation, and extended context. The free plan is generous for everyday AI tasks.", "q": "Is Le Chat free?"}, {"a": "Mistral releases some models as open weights (Mistral 7B, Mixtral 8x7B, Mistral Small) that anyone can download and run locally. Their frontier models (Mistral Large) are commercial-only through their API and Le Chat. The open models have a strong developer community.", "q": "Are Mistral models open source?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Le Chat es el asistente de IA de Mistral AI, empresa francesa fundada en 2023. Usa los modelos Mistral, que son open-weights y pueden usarse localmente o vía API a precios significativamente menores que OpenAI.", "q": "¿Qué es Mistral Le Chat?"}, {"a": "Mistral publica sus modelos como open-weights — los pesos son libres para descargar y usar. Puedes ejecutar Mistral 7B o Mixtral localmente con Ollama u otras herramientas. Esto los diferencia de OpenAI y Anthropic.", "q": "¿Son los modelos de Mistral de código abierto?"}, {"a": "Sí. Mistral fue entrenado con énfasis en idiomas europeos y tiene excelente soporte para español, francés, alemán e italiano. Para tareas en español, la calidad es competitiva con ChatGPT.", "q": "¿Mistral Le Chat habla bien español?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Le Chat ist der KI-Assistent von Mistral AI, einem 2023 gegründeten französischen Unternehmen. Es verwendet Mistral-Modelle, die Open-Weights sind und lokal oder über API zu deutlich niedrigeren Preisen als OpenAI genutzt werden können.", "q": "Was ist Mistral Le Chat?"}, {"a": "Mistral veröffentlicht seine Modelle als Open-Weights — die Gewichte können frei heruntergeladen und genutzt werden. Sie können Mistral 7B oder Mixtral lokal mit Ollama oder anderen Tools ausführen. Das unterscheidet sie von OpenAI und Anthropic.", "q": "Sind Mistral-Modelle Open-Source?"}, {"a": "Ja. Mistral wurde mit Schwerpunkt auf europäischen Sprachen trainiert und hat ausgezeichnete Unterstützung für Deutsch, Französisch, Spanisch und Italienisch. Für Aufgaben auf Deutsch ist die Qualität mit ChatGPT konkurrenzfähig.", "q": "Spricht Mistral Le Chat gut Deutsch?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Le Chat — бесплатный ИИ-ассистент от французской компании Mistral AI. Работает на собственных моделях Mistral (Mistral Large, Mixtral). Позиционируется как европейская альтернатива ChatGPT с акцентом на конфиденциальность и работу с европейскими языками.", "q": "Что такое Mistral Le Chat?"}, {"a": "По большинству бенчмарков ChatGPT (GPT-5.5) превосходит Mistral. Однако Mistral сильнее в работе с европейскими языками и соответствии нормам ЕС о конфиденциальности данных. Для пользователей в ЕС Le Chat — серьёзная альтернатива.", "q": "Mistral лучше ChatGPT?"}, {"a": "Да. Mistral публикует большинство своих моделей с открытым исходным кодом — их можно запустить локально через Ollama, LM Studio или через API. Это главное преимущество перед ChatGPT, который полностью закрыт.", "q": "Можно ли использовать модели Mistral локально?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Mistral — французька компанія з відкритими моделями і сильними конфіденційністю даних. ChatGPT від OpenAI (США) має більшу екосистему. Для GDPR-вимог і ЄС — Mistral; для максимальної екосистеми — ChatGPT.", "q": "Mistral Le Chat vs ChatGPT — яка різниця?"}, {"a": "Деякі моделі Mistral відкриті (Mistral 7B, Mixtral, Mistral NeMo). Mistral Large — закрита комерційна модель. Відкриті моделі можна розгортати локально через Ollama або HuggingFace.", "q": "Чи Mistral справді відкритий?"}, {"a": "Так. Mistral Large 2 і Codestral (спеціалізована модель для коду) показують відмінні результати. Codestral підтримується у Continue.dev і інших IDE. Для ціни/якості у кодуванні — відмінний вибір.", "q": "Mistral для кодування — чи підходить?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Mistral הוא חברה צרפתית עם מודלים פתוחים ופרטיות נתונים חזקה. ChatGPT מ-OpenAI (ארה\"ב) עם מערכת-אקולוגית גדולה יותר. לדרישות GDPR ואיחוד אירופי — Mistral; למערכת-אקולוגית מרבית — ChatGPT.", "q": "Mistral Le Chat מול ChatGPT — מה ההבדל?"}, {"a": "חלק ממודלי Mistral פתוחים (Mistral 7B, Mixtral, Mistral NeMo). Mistral Large הוא מודל מסחרי סגור. מודלים פתוחים ניתנים לפריסה מקומית דרך Ollama או HuggingFace.", "q": "האם Mistral באמת פתוח?"}, {"a": "כן. Mistral Large 2 ו-Codestral (מודל מיוחד לקוד) מציגים תוצאות מצוינות. Codestral נתמך ב-Continue.dev ועוד IDE. ליחס עלות/ביצועים בקוד — בחירה מצוינת.", "q": "Mistral לקוד — האם מתאים?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Mistral est une société française avec des modèles ouverts et une forte confidentialité des données. ChatGPT d'OpenAI (États-Unis) dispose d'un plus grand écosystème. Pour les exigences RGPD et l'UE, Mistral ; pour l'écosystème maximal, ChatGPT.", "q": "Mistral Le Chat vs ChatGPT — quelle est la différence ?"}, {"a": "Certains modèles Mistral sont ouverts (Mistral 7B, Mixtral, Mistral NeMo). Mistral Large est un modèle commercial fermé. Les modèles ouverts peuvent être déployés localement via Ollama ou HuggingFace.", "q": "Mistral est-il vraiment open-source ?"}, {"a": "Oui. Mistral Large 2 et Codestral (modèle spécialisé pour le code) affichent d'excellents résultats. Codestral est supporté dans Continue.dev et d'autres IDEs. Excellent rapport qualité-prix pour le codage.", "q": "Mistral pour le codage — est-il adapté ?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Mistral é uma empresa francesa com modelos abertos e forte privacidade de dados. ChatGPT da OpenAI (EUA) tem um ecossistema maior. Para requisitos GDPR e UE, Mistral; para o maior ecossistema, ChatGPT.", "q": "Mistral Le Chat vs ChatGPT — qual é a diferença?"}, {"a": "Alguns modelos Mistral são abertos (Mistral 7B, Mixtral, Mistral NeMo). Mistral Large é um modelo comercial fechado. Os modelos abertos podem ser implantados localmente via Ollama ou HuggingFace.", "q": "Mistral é realmente open-source?"}, {"a": "Sim. Mistral Large 2 e Codestral (modelo especializado em código) apresentam excelentes resultados. Codestral é suportado no Continue.dev e outros IDEs. Excelente custo-benefício para programação.", "q": "Mistral para programação — é adequado?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Motion is an AI calendar and task manager that automatically schedules all your tasks into your calendar based on priorities, deadlines, and available time. When meetings are added or tasks run long, Motion automatically rescheduled everything to keep you on track.", "q": "What is Motion?"}, {"a": "Motion is $34/month (or $19/month billed annually) — expensive for a calendar app. Users who struggle with scheduling and prioritization often find it transformative. Those who are already disciplined schedulers may find the value harder to justify. Most offer a 7-day free trial.", "q": "Is Motion worth the price?"}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Motion reorganiza activamente todo tu día — es más agresivo y completo, planificando cada tarea. Reclaim es más sutil: protege bloques de tiempo sin reorganizar todo. Motion es mejor para profesionales con muchas tareas cambiantes; Reclaim para quienes quieren proteger hábitos y tiempo de enfoque.", "q": "¿Motion o Reclaim para gestión de tiempo con IA?"}, {"a": "Motion no tiene plan gratuito permanente, solo prueba de 7 días. Los planes de pago empiezan desde $34/mes (Individual). Reclaim AI tiene un plan gratuito con funciones básicas; planes de pago desde $10/mes.", "q": "¿Motion es gratuito?"}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Motion ist ein vollständiges Produktivitäts-System mit Projektmanagement und KI-Scheduling. Reclaim ist spezifischer: Es schützt Fokuszeiten und optimiert Ihren bestehenden Google-Kalender. Motion für vollständige Planung; Reclaim für intelligente Kalender-Optimierung.", "q": "Motion vs Reclaim AI: Welches ist besser?"}, {"a": "Motion kostet ab $19/Monat (Individual) oder $12/Monat bei jährlicher Zahlung. Reclaim AI hat einen kostenlosen Plan; kostenpflichtige Pläne ab $10/Monat. Beide bieten kostenlose Testphasen.", "q": "Wie viel kostet Motion?"}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Motion — ИИ-планировщик задач и проектов: управляет задачами и автоматически планирует их в календаре. Reclaim.ai — умный помощник по расписанию: защищает время для важных дел в Google Календаре. Motion сложнее и дороже, Reclaim — проще и доступнее.", "q": "Motion vs Reclaim.ai — в чём разница?"}, {"a": "Motion стоит $34/мес (ежемесячно) или $19/мес (ежегодно). Пользователи, которым Motion подходит, отмечают значительный рост продуктивности. Для фрилансеров и специалистов с большим количеством задач — обоснованная инвестиция.", "q": "Motion стоит своих денег?"}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Motion повністю перепланує ваш день навколо завдань і дедлайнів. Reclaim.ai захищає існуючий час і додає розумні звички у ваш Google Calendar. Motion для тих хто хоче повну автоматизацію планування; Reclaim для захисту часу.", "q": "Motion vs Reclaim.ai — яка різниця?"}, {"a": "Motion не має безкоштовного плану. Individual від $34/міс (щомісячно) або $19/міс (щорічно). Reclaim.ai має безкоштовний план; Starter від $10/міс.", "q": "Motion безкоштовний?"}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Motion הוא פתרון תזמון מלא שמחליף את כל ניהול הלו\"ז. Reclaim.ai מוסיף שכבת AI על Google Calendar הקיים. Motion לניהול עמוק; Reclaim לשיפור קל יותר.", "q": "Motion לעומת Reclaim.ai – מה עדיף?"}, {"a": "Motion עולה $34/חודש לאדם יחיד. Reclaim.ai מציע תוכנית חינמית; Starter ב-$10/חודש.", "q": "כמה עולה Motion?"}]$x$::jsonb
