UPDATE tools SET faq = $x$[{"a": "Nano Banana is an AI image generation platform specializing in character consistency and AI influencer creation. It's designed for creators who need to generate the same person or character across many different scenes, outfits, and settings while maintaining a consistent look.", "q": "What is Nano Banana?"}, {"a": "Nano Banana offers a free plan with limited generations. Paid plans provide more credits and higher quality generations. It's a specialized tool — the free tier lets you test whether the character consistency meets your needs before subscribing.", "q": "Is Nano Banana free?"}]$x$::jsonb
 WHERE slug = 'nano-banana' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Nano Banana es una herramienta de generación de imágenes IA diseñada con simplicidad extrema como prioridad. Su propuesta es hacer accesible la generación de imágenes IA sin la complejidad técnica de otras plataformas. Está orientada a usuarios que quieren resultados rápidos sin aprender parámetros.", "q": "¿Qué es Nano Banana?"}, {"a": "Ideogram tiene mejor reputación por calidad y generación de texto dentro de imágenes, con plan gratuito sólido. Nano Banana prioriza simplicidad. Para resultados de calidad con plan gratuito — Ideogram; para máxima simplicidad — Nano Banana.", "q": "¿Nano Banana vs Ideogram para imágenes simples?"}]$x$::jsonb
 WHERE slug = 'nano-banana' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Leonardo AI ist bekannter, ausgereifter und hat mehr Features speziell für Game-Entwickler und kreative Profis. Nano Banana positioniert sich als schnellere, günstigere Alternative. Für professionelle kreative Arbeit — Leonardo; für einfache schnelle Generierung — Nano Banana.", "q": "Nano Banana vs Leonardo AI: Was ist besser?"}, {"a": "Nano Banana fokussiert auf Geschwindigkeit und einfache Preisgestaltung für hohe Bildvolumen. Es ist besser für technische Integrationen via API als für kreative End-Nutzer die ein vollständiges Design-Ökosystem suchen.", "q": "Was macht Nano Banana besonders?"}]$x$::jsonb
 WHERE slug = 'nano-banana' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Nano Banana — упрощённый ИИ-генератор изображений, ориентированный на простоту и доступность. Менее известен, чем крупные платформы, и предлагает базовые возможности генерации без сложной настройки.", "q": "Что такое Nano Banana?"}, {"a": "Leonardo AI превосходит для игровых ассетов, LoRA-обучения и технического контента. Midjourney V7 лидирует по художественной эстетике. Leonardo AI щедрее в бесплатных кредитах. Для игровых разработчиков — Leonardo, для художников — Midjourney.", "q": "Leonardo AI vs Midjourney — что выбрать?"}]$x$::jsonb
 WHERE slug = 'nano-banana' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Leonardo AI дає більше контролю через кастомні моделі і LoRA; підходить для геймдеву і послідовних стилів. Midjourney виробляє якісніший вихідний продукт з меншими зусиллями. Для контролю і геймдеву — Leonardo; для якості — Midjourney.", "q": "Leonardo AI vs Midjourney — різниця?"}, {"a": "LoRA (Low-Rank Adaptation) — техніка тонкого налаштування що дозволяє навчати модель на невеликому наборі зображень для відтворення конкретного стилю або персонажа. Leonardo AI підтримує завантаження і використання LoRA-моделей.", "q": "Що таке LoRA у Leonardo AI?"}]$x$::jsonb
 WHERE slug = 'nano-banana' AND lang = 'ua';

