UPDATE tools SET faq = $x$[{"a": "NotebookLM is Google's AI research assistant powered by Gemini. You upload documents, PDFs, YouTube videos, or web pages and it creates a notebook where you can ask questions, get summaries, and generate audio overviews (podcast-style conversations about your content).", "q": "What is NotebookLM?"}, {"a": "NotebookLM is free for all Google account users at notebooklm.google.com. NotebookLM Plus (available through Google One AI Premium at $19.99/month or Google Workspace) offers higher limits on notebooks, sources, and audio generation.", "q": "Is NotebookLM free?"}, {"a": "Yes. NotebookLM can use YouTube video URLs as sources — it processes the transcript and lets you ask questions about video content. This makes it useful for analyzing lectures, interviews, podcasts, and any content available as a YouTube video.", "q": "Can NotebookLM analyze YouTube videos?"}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Perplexity busca en internet en tiempo real — ideal para temas actuales y preguntas sobre el mundo. NotebookLM trabaja solo con documentos que tú cargas — ideal para analizar material específico con citas precisas. Perplexity para investigar el mundo; NotebookLM para analizar tu propio material.", "q": "¿Perplexity o NotebookLM para investigación?"}, {"a": "Sí. NotebookLM de Google es gratuito con hasta 50 fuentes por notebook y 500.000 palabras por fuente. NotebookLM Plus está disponible con Google One AI Premium ($19.99/mes). Perplexity tiene plan gratuito; Pro ($20/mes) desbloquea modelos avanzados y más búsquedas.", "q": "¿NotebookLM es gratuito?"}, {"a": "Sí. Perplexity Pro permite cargar PDFs y hacer preguntas sobre ellos. Sin embargo, NotebookLM está más especializado en análisis profundo de documentos con citaciones exactas. Para un PDF ocasional — Perplexity Pro funciona; para investigación intensiva con múltiples documentos — NotebookLM.", "q": "¿Perplexity puede analizar PDFs?"}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Perplexity fasst die Antwort direkt zusammen mit zitierten Quellen — kein Link-Scrollen nötig. Google gibt Links die Sie selbst besuchen müssen. Perplexity ist schneller für direkte Antworten; Google ist besser für explorative Suche und komplexe Themen.", "q": "Perplexity vs Google: Was ist der Unterschied?"}, {"a": "Perplexity hat einen kostenlosen Plan mit begrenzten Pro-Suchen. Perplexity Pro ($20/Monat) bietet unbegrenzte Pro-Suchen, GPT-4o, Claude, Gemini und Bildgenerierung. NotebookLM ist kostenlos.", "q": "Ist Perplexity kostenlos?"}, {"a": "Perplexity ist gut für schnelle Literatursuche und Überblicke. Für tiefe akademische Forschung sind Semantic Scholar, Elicit oder Consensus besser — sie sind speziell für peer-reviewed Literatur optimiert. Perplexity als erster Schritt; spezialisierte Tools für tiefere Analyse.", "q": "Perplexity für akademische Recherche: Ist es gut?"}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Perplexity ищет в интернете и возвращает ответы со свежими источниками. NotebookLM анализирует только ваши загруженные документы. Perplexity для поиска информации, NotebookLM для анализа своих материалов.", "q": "Perplexity vs NotebookLM — в чём разница?"}, {"a": "Да. NotebookLM бесплатен с неограниченными ноутбуками. NotebookLM Plus ($19.99/мес) добавляет больше аудиообзоров и приоритетный доступ. Perplexity бесплатен с 5 Pro-поисками в день; Perplexity Pro — $20/мес.", "q": "NotebookLM бесплатный?"}, {"a": "Perplexity приводит источники для каждого утверждения, что упрощает проверку. Но как любой ИИ, он может ошибаться или галлюцинировать. Используйте для исследований, проверяйте критически важные факты.", "q": "Перплексити точнее Гугла?"}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Perplexity синтезує відповідь з кількох джерел і дає цитати. Google показує список посилань де ви самі шукаєте відповідь. Perplexity швидший для прямих відповідей; Google повніший для глибокого пошуку.", "q": "Perplexity vs Google — яка різниця?"}, {"a": "Perplexity безкоштовний з базовими функціями. Pro $20/міс з розширеними моделями і більше пошуків. NotebookLM повністю безкоштовний від Google.", "q": "Perplexity безкоштовний?"}, {"a": "Perplexity непогано для попередніх досліджень але не завжди посилається на рецензовані джерела. Для академічних досліджень Consensus, Elicit або Semantic Scholar з верифікованими науковими публікаціями надійніші.", "q": "Perplexity для академічних досліджень?"}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Perplexity מחפש מידע באינטרנט בזמן אמת. NotebookLM עובד רק עם המסמכים שהעלאתם. Perplexity לחיפוש עדכני; NotebookLM לניתוח עמוק של מקורות ספציפיים.", "q": "Perplexity לעומת NotebookLM – מה ההבדל?"}, {"a": "כן, NotebookLM חינמי לחלוטין. NotebookLM Plus זמין ב-Google One AI Premium ב-$19.99/חודש. Perplexity חינמי; Pro ב-$20/חודש.", "q": "האם NotebookLM חינמי?"}, {"a": "NotebookLM מבין מסמכים בעברית ויכול לענות על שאלות בעברית. Audio Overview (פודקאסט AI) פועל בעיקר לאנגלית כרגע.", "q": "NotebookLM תומך בעברית?"}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Perplexity recherche sur internet pour des informations en temps réel. NotebookLM analyse vos propres documents. Pour la recherche web avec sources, Perplexity ; pour analyser vos propres PDFs et notes, NotebookLM.", "q": "Perplexity vs NotebookLM — lequel est le meilleur ?"}, {"a": "Oui. NotebookLM est gratuit. NotebookLM Plus (via Google One AI Premium à 19,99 $/mois) offre plus de fonctionnalités. Perplexity est gratuit ; Pro à partir de 20 $/mois.", "q": "NotebookLM est-il gratuit ?"}, {"a": "Oui. NotebookLM analyse des documents en français. Vous pouvez poser des questions en français sur vos documents français et obtenir des réponses précises basées sur vos sources.", "q": "NotebookLM peut-il analyser des PDFs en français ?"}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Perplexity é para pesquisa na web em tempo real. NotebookLM é para analisar seus próprios documentos. Para informações atuais da web, Perplexity; para trabalhar com seus documentos e materiais, NotebookLM.", "q": "Perplexity vs NotebookLM — qual usar?"}, {"a": "Perplexity tem plano gratuito com buscas ilimitadas. Perplexity Pro custa $20/mês com mais pesquisas profundas e acesso a modelos avançados. NotebookLM é gratuito do Google.", "q": "Perplexity é gratuito?"}, {"a": "Sim, Perplexity cita todas as fontes usadas nas respostas. Você pode verificar cada informação clicando nas referências. Este é um dos diferenciais principais da plataforma.", "q": "Perplexity cita suas fontes?"}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "OpenCode is an open-source, terminal-based AI coding agent. It works similarly to Claude Code or Aider but supports multiple AI providers including Anthropic, OpenAI, Google, and local models via Ollama. It's free to use — you only pay for the API tokens consumed.", "q": "What is OpenCode?"}, {"a": "OpenCode itself is free and open-source. You pay for whatever AI model API you connect it to. Using Anthropic Claude costs per token; using local models via Ollama is free with no API costs.", "q": "Is OpenCode free?"}, {"a": "Both are open-source terminal coding agents with multi-model support. Aider has a longer track record, stronger git integration, and larger community. OpenCode is newer with a more modern TUI (terminal user interface). They're similar in capability — try both to see which workflow fits better.", "q": "What is the difference between OpenCode and Aider?"}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "OpenCode es un agente de código de terminal open-source inspirado en Claude Code. Funciona con múltiples modelos de IA (Claude, GPT-4, modelos locales) y puede realizar tareas de desarrollo autónomas: leer código, hacer cambios, ejecutar tests. Es la alternativa open-source más directa a Claude Code.", "q": "¿Qué es OpenCode?"}, {"a": "Claude Code requiere una suscripción de Claude (Pro $20/mes o Max $100-$200/mes). El uso intensivo de Claude Code consume créditos de API rápidamente. OpenCode es gratuito como herramienta, pero el costo depende del modelo API que uses.", "q": "¿Claude Code es gratuito?"}, {"a": "Claude Code tiene ventaja en calidad de razonamiento al estar optimizado específicamente para Claude 3.7/3.5. OpenCode es más flexible al soportar múltiples modelos. Para la mejor calidad absoluta — Claude Code con Claude Sonnet; para flexibilidad y open-source — OpenCode.", "q": "¿OpenCode es tan bueno como Claude Code?"}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "OpenCode ist ein Open-Source Terminal-KI-Coding-Assistent ähnlich Claude Code oder Aider. Er unterstützt mehrere Modelle (OpenAI, Anthropic, Ollama) und arbeitet direkt im Terminal für agentenhafte Coding-Aufgaben.", "q": "Was ist OpenCode?"}, {"a": "Claude Code ist leistungsfähiger für komplexe Aufgaben da es von Anthropic optimiert wurde und den besten Claude-Modell-Zugang hat. OpenCode ist flexibler und kostenlos — ideal wenn Sie verschiedene Modelle testen oder Kosten sparen wollen.", "q": "OpenCode vs Claude Code: Welches ist besser?"}, {"a": "Claude Code selbst ist kostenlos als CLI-Tool. Sie zahlen für Claude API-Nutzung basierend auf verarbeiteten Tokens. Für intensive Nutzung empfiehlt sich ein Claude Max-Plan ($100/Monat) der API-Nutzung inklusive hat.", "q": "Ist Claude Code kostenlos?"}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Claude Code — официальный агент кодирования от Anthropic, работающий исключительно на Claude. OpenCode — open-source альтернатива с поддержкой множества провайдеров. Claude Code более отполирован, OpenCode более гибкий.", "q": "OpenCode vs Claude Code — в чём разница?"}, {"a": "OpenCode как инструмент — бесплатный open-source. Оплачиваются только API-токены выбранной модели. Claude Code требует подписку на Anthropic (Max $100 или $200/мес) или API-ключ.", "q": "OpenCode бесплатный?"}, {"a": "Claude Code имеет преимущество благодаря прямому доступу к API Anthropic и глубокой оптимизации для моделей Claude. OpenCode предлагает гибкость выбора модели и полную прозрачность открытого кода.", "q": "Claude Code лучше OpenCode?"}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "OpenCode — відкритий термінальний ШІ-помічник для кодування схожий на Claude Code або Aider. Підтримує кілька моделей (OpenAI, Anthropic, Ollama) і працює прямо в терміналі для агентних завдань кодування.", "q": "Що таке OpenCode?"}, {"a": "Claude Code потужніший для складних завдань бо оптимізований Anthropic і має найкращий доступ до Claude-моделей. OpenCode гнучкіший і безкоштовний — ідеально якщо хочете тестувати різні моделі або заощаджувати.", "q": "OpenCode vs Claude Code — що краще?"}, {"a": "Claude Code CLI безкоштовний. Ви платите за використання Claude API за токенами. Для інтенсивного використання Claude Max ($100/міс) включає більші API-ліміти. OpenCode — безкоштовний, платите лише за API вибраної моделі.", "q": "Claude Code безкоштовний?"}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "OpenCode הוא עוזר קוד Terminal פתוח בדומה ל-Claude Code. תומך במודלים מרובים – OpenAI, Anthropic, Ollama.", "q": "מה זה OpenCode?"}, {"a": "Claude Code חזק יותר עם מיטוב ל-Anthropic. OpenCode גמיש יותר וחינמי. Anthropic Max ל-Claude Code; גמישות – OpenCode.", "q": "OpenCode לעומת Claude Code – מה עדיף?"}, {"a": "Claude Code CLI חינמי. משלמים עבור API לפי tokens. שימוש אינטנסיבי – Claude Max ($100/חודש) כולל API usage.", "q": "Claude Code חינמי?"}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "OpenCode est un assistant de codage IA terminal open-source similaire à Claude Code ou Aider. Il supporte plusieurs modèles (OpenAI, Anthropic, Ollama) et travaille directement dans le terminal pour des tâches de codage agentiques.", "q": "Qu'est-ce que OpenCode ?"}, {"a": "Claude Code est plus puissant pour les tâches complexes car optimisé par Anthropic avec le meilleur accès aux modèles Claude. OpenCode est plus flexible et gratuit — idéal pour tester différents modèles ou réduire les coûts.", "q": "OpenCode vs Claude Code — lequel est le meilleur ?"}, {"a": "Claude Code CLI est gratuit comme outil. Vous payez pour l'utilisation de l'API Claude basée sur les tokens traités. Pour une utilisation intensive, un plan Claude Max (100 $/mois) inclut une utilisation API plus importante.", "q": "Claude Code est-il gratuit ?"}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "OpenCode é um assistente de codificação com IA no terminal open-source similar ao Claude Code ou Aider. Suporta múltiplos modelos (OpenAI, Anthropic, Ollama) e trabalha diretamente no terminal para tarefas de codificação agênticas.", "q": "O que é o OpenCode?"}, {"a": "Claude Code é mais poderoso para tarefas complexas pois é otimizado pela Anthropic com melhor acesso aos modelos Claude. OpenCode é mais flexível e gratuito — ideal para testar diferentes modelos ou reduzir custos.", "q": "OpenCode vs Claude Code — qual é o melhor?"}, {"a": "Claude Code CLI é gratuito como ferramenta. Você paga pelo uso da API Claude baseado nos tokens processados. Para uso intensivo, um plano Claude Max ($100/mês) inclui maior uso de API.", "q": "Claude Code é gratuito?"}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Otter.ai transcribes meetings in real-time and creates searchable notes. It joins Zoom, Google Meet, and Teams automatically or records in-person conversations. It's used for meeting notes, journalism interviews, lecture notes, and any situation requiring accurate transcription.", "q": "What is Otter.ai used for?"}, {"a": "Otter.ai has a free plan with 300 minutes of transcription per month and up to 3 audio imports. Pro is $16.99/month for 1,200 minutes. Business is $30/user/month for team features and advanced integrations.", "q": "Is Otter.ai free?"}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Whisper es open-source (modelo gratuito de OpenAI para descargar y usar localmente). Vía la API de OpenAI, cuesta $0.006/minuto. Otter AI tiene plan gratuito con 300 minutos/mes; planes de pago desde $16.99/mes.", "q": "¿Whisper es gratuito?"}, {"a": "Whisper large-v3 tiene una de las mayores precisiones de transcripción disponibles, especialmente en inglés. En español y otros idiomas también es muy competitivo. Para audio limpio, la precisión supera el 95%. Para audio de baja calidad — la precisión baja pero sigue siendo buena comparada con alternativas.", "q": "¿Qué precisión tiene Whisper?"}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Whisper ist ein Transkriptions-Modell für Entwickler und technische Nutzer. Otter AI ist ein fertiges Business-Tool für Meeting-Transkription mit Kollaborations-Features. Whisper für technische Integration; Otter für sofort nutzbare Business-Lösung.", "q": "Whisper vs Otter AI: Was ist der Unterschied?"}, {"a": "Whisper ist Open-Source und kostenlos lokal nutzbar. Die OpenAI-API-Version kostet $0,006/Minute Audio. Otter AI hat einen kostenlosen Plan mit 600 Minuten/Monat; Pro ab $16,99/Monat.", "q": "Ist Whisper kostenlos?"}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Оба транскрибируют встречи, но с разными акцентами. Otter.ai известен высокой точностью транскрипции в реальном времени и интеграцией с Salesforce. Fireflies.ai предлагает более широкую языковую поддержку, аналитику разговоров и больше CRM-интеграций.", "q": "Otter.ai vs Fireflies.ai — в чём разница?"}, {"a": "Да. Otter.ai предлагает бесплатный план с 600 минутами транскрипции в месяц и 3 импортами. Pro — $17/мес. Fireflies.ai также имеет бесплатный план с ограниченным хранилищем транскрипций.", "q": "Otter.ai бесплатный?"}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Otter.ai сильніший для транскрипції в реальному часі і особистої продуктивності. Fireflies.ai кращий для команд продажів з CRM-інтеграціями і пошуком по зустрічах. Otter для особистого використання; Fireflies для командного і продажового.", "q": "Otter.ai vs Fireflies.ai — яка різниця?"}, {"a": "Otter.ai має безкоштовний план з 600 хвилин/міс транскрипції. Pro $16,99/міс. Fireflies.ai безкоштовний з обмеженнями; Pro $18/міс.", "q": "Otter.ai безкоштовний?"}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Whisper Open Source API לפיתוחים. Otter.ai מוצר מוכן לשימוש לפגישות. Whisper למפתחים; Otter.ai לאנשי עסקים.", "q": "Whisper לעומת Otter.ai?"}, {"a": "Whisper Open Source חינמי לחלוטין. OpenAI Whisper API ב-$0.006/דקה. Otter.ai מציע 300 דקות חינם; Pro ב-$16.99/חודש.", "q": "Whisper חינמי?"}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Whisper est un modèle de transcription open-source à intégrer dans vos propres outils. Otter.ai est un service complet de notes de réunion avec interface. Pour des développeurs intégrant la transcription → Whisper ; pour des notes de réunion prêtes à l'emploi → Otter.ai.", "q": "Whisper vs Otter.ai — quelle est la différence ?"}, {"a": "Le modèle Whisper est open-source et gratuit à utiliser localement. L'API Whisper via OpenAI est payante (environ 0,006 $/minute). Otter.ai a un plan gratuit avec 300 minutes/mois.", "q": "Whisper est-il gratuit ?"}]$x$::jsonb
