UPDATE tools SET faq = $x$[{"a": "Perplexity searches the web including academic sources, but it doesn't specialize in peer-reviewed papers the way Consensus does. For academic research requiring study citations and evidence quality, Consensus is more reliable. Perplexity is better for broad current-events research.", "q": "Is Perplexity good for academic research?"}]$x$::jsonb
