UPDATE tools SET faq = $x$[{"a": "Perplexity מתמחה בחיפוש עם ציטוטים ומקורות. ChatGPT מגוון יותר אך ידע הבסיסי מוגבל לתאריך חיתוך. לחיפוש עדכני עם מקורות – Perplexity; לשיחה וכתיבה – ChatGPT.", "q": "Perplexity לעומת ChatGPT – מה עדיף לחיפוש?"}]$x$::jsonb
