UPDATE tools SET faq = $x$[{"a": "Photomath is free for basic step-by-step solutions. Photomath Plus ($9.99/month or $69.99/year) adds animated video explanations, multiple solution methods, and access to a math expert for deeper understanding.", "q": "Is Photomath free?"}, {"a": "Yes. Photomath can solve word problems — you can type or photograph text-based math problems, not just equations. It handles algebra word problems, but complex multi-step reasoning problems may require a more capable AI like Khanmigo or Wolfram Alpha.", "q": "Can Photomath solve word problems?"}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Photomath tiene una versión gratuita que resuelve problemas y muestra pasos básicos. Photomath Plus ($9.99/mes o $29.99/año) desbloquea pasos animados, más métodos de solución y práctica adicional. Duolingo Max ($14.99/mes, incluido en Super Duolingo en algunos planes).", "q": "¿Photomath es gratuito?"}, {"a": "Photomath puede resolver problemas automáticamente, lo que algunos usan para copiar en lugar de aprender. La herramienta está diseñada para aprender los pasos, no para obtener respuestas sin entender. Usarla responsablemente — entender cada paso — hace la diferencia entre aprender y copiar.", "q": "¿Puede Photomath hacer trampa en los deberes?"}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Photomath ist kostenlos mit grundlegenden Lösungsschritten. Photomath Plus ($9,99/Monat oder $69,99/Jahr) bietet detailliertere Erklärungen und Animationen. Duolingo Max kostet ab $13,99/Monat als Upgrade.", "q": "Ist Photomath kostenlos?"}, {"a": "Duolingo Plus entfernt Werbung und bietet Offline-Modus. Duolingo Max ($13,99/Monat) fügt KI-Features hinzu: 'Explain My Answer' (KI erklärt Fehler) und 'Roleplay' (KI-Konversationsübungen). Max ist teurer aber bietet echten KI-Mehrwert.", "q": "Duolingo Max vs Duolingo Plus: Was ist der Unterschied?"}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Photomath бесплатен с базовыми решениями. Photomath Plus ($9.99/мес или $59.99/год) добавляет анимированные пошаговые объяснения. Duolingo Max — $30/мес или $168/год.", "q": "Photomath бесплатный?"}, {"a": "Оба хороши, но по-разному. Photomath специализируется на математике и пошаговых решениях — очень точен для школьного уровня. ChatGPT охватывает более широкий математический контекст, но может ошибаться в сложных задачах.", "q": "Что точнее — Photomath или ChatGPT для математики?"}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Photomath спеціалізований на шкільній математиці з візуальними покроковими поясненнями. Wolfram Alpha потужніший для університетської математики, фізики і наукових розрахунків. Photomath для школярів; Wolfram Alpha для університету.", "q": "Photomath vs Wolfram Alpha — яка різниця?"}, {"a": "Так. Photomath чудово вирішує алгебраїчні рівняння, нерівності, системи рівнянь і функції. Покрокові пояснення допомагають зрозуміти метод а не просто скопіювати відповідь.", "q": "Photomath допомагає з алгеброю?"}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Photomath חינמי לפתרונות בסיסיים; Photomath Plus ב-$9.99/חודש לפתרונות מפורטים. Duolingo Plus ב-$14.99/חודש; Duolingo Max ב-$29.99/חודש.", "q": "Photomath חינמי?"}, {"a": "Photomath עוזר להבין פתרונות אך אינו תחליף לתרגול. לבגרות, מומלץ לפתור ולהשתמש ב-Photomath לבדיקה ולהבנת שלבים, לא להעתקה.", "q": "Photomath לבגרות מתמטיקה?"}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Photomath a un plan gratuit avec des étapes de base. Plus à partir de 9,99 $/mois pour des explications complètes. Duolingo Max à partir de 13,99 $/mois en plus de Duolingo Super.", "q": "Photomath est-il gratuit ?"}, {"a": "Photomath couvre les mathématiques jusqu'au niveau bac et partiellement les mathématiques universitaires. Pour les mathématiques avancées de prépa ou licence, des outils comme Wolfram Alpha ou Symbolab sont plus appropriés.", "q": "Photomath peut-il aider en prépa ou en université ?"}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Photomath tem recursos gratuitos robustos. Photomath Plus custa $9,99/mês ou $29,99/ano para recursos avançados como animações e dicas adicionais. Duolingo Max custa $29,99/mês ou $167,99/ano.", "q": "Photomath é gratuito?"}, {"a": "Photomath funciona com álgebra, geometria, cálculo, trigonometria e mais. Para matemática muito avançada do nível universitário, pode ter limitações, mas cobre bem o currículo até o ensino médio.", "q": "Photomath funciona com qualquer tipo de matemática?"}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Pika is an AI video generator known for creative effects and stylized output. Its Pikaffects features (explode, crush, melt, deflate) create dramatic visual transformations. Pika 2.2 (2025) added Scene Ingredients for compositing specific characters into scenes.", "q": "What is Pika AI?"}, {"a": "Pika has a free plan with 150 credits on signup and 50 monthly credits. Standard is $8/month, Pro is $28/month, Unlimited is $98/month. The free credits reset monthly on the standard plans.", "q": "Is Pika free?"}, {"a": "Pika specializes in creative effects and stylized short videos. Kling focuses on realistic, longer-form video with better physics simulation. Pika is better for creative social content; Kling is better for cinematic realism and professional video generation.", "q": "What is the difference between Pika and Kling?"}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Pika es más fuerte en efectos creativos y transformaciones de video — ideal para contenido viral con efectos únicos. Kling es mejor para videos generados de mayor duración y calidad cinematográfica. Para efectos especiales y clips cortos creativos — Pika; para video generado de mayor calidad — Kling.", "q": "¿Pika o Kling para videos de redes sociales?"}, {"a": "Pika tiene un plan gratuito con créditos limitados. Los planes de pago empiezan desde $8/mes (Basic). Kling tiene plan gratuito y planes de pago desde $10/mes.", "q": "¿Pika es gratuito?"}, {"a": "Pika Effects son transformaciones creativas especiales: Pikaffects permite añadir efectos como 'explotar', 'deflate', 'melt' sobre objetos en videos o imágenes. Son populares para contenido viral en TikTok. También tiene 'Add Sound' para generar efectos de sonido automáticamente.", "q": "¿Qué son los Pika Effects?"}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Kling AI ist stärker für realistische Videos mit physikalisch glaubwürdiger Bewegung. Pika ist einzigartiger für kreative Effekte und Stilisierungen die viral gehen können. Für Realismus — Kling; für kreative Experimente und virale Effekte — Pika.", "q": "Pika vs Kling AI: Welches ist besser?"}, {"a": "Pikaffects sind Pikas einzigartige kreative Effekte die Videos transformieren: 'Inflate' (aufblasen), 'Explode' (explodieren lassen), 'Melt' (schmelzen), 'Crush' (zerquetschen). Diese Effekte haben auf Social Media für viele virale Momente gesorgt.", "q": "Was sind Pikaffects?"}, {"a": "Pika hat einen kostenlosen Plan mit begrenzten monatlichen Credits. Standard ab $8/Monat, Pro ab $28/Monat. Kling AI hat ebenfalls einen kostenlosen Plan; Pro ab ca. $15/Monat.", "q": "Ist Pika kostenlos?"}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Kling AI 3.0 генерирует более реалистичное движение и поддерживает нативный 4K. Pika 2.5 проще в использовании и имеет уникальные эффекты (Pikaffects). Для профессионального качества — Kling, для простоты и творческих эффектов — Pika.", "q": "Pika vs Kling AI — что лучше?"}, {"a": "Pika предлагает бесплатный план с ограниченными генерациями. Pika Standard — $8/мес. Kling AI также имеет бесплатный уровень с 66 ежедневными кредитами — это щедрее, чем у многих конкурентов.", "q": "Pika бесплатный?"}, {"a": "Kling AI 3.0 может генерировать клипы до 3 минут — это намного больше, чем большинство конкурентов (Runway и Pika: 4–10 секунд). Для длинных нарративных видео Kling превосходит конкурентов.", "q": "Какое видео длиннее генерирует Kling?"}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Kling AI виробляє більш реалістичне і якісне відео. Pika простіший у використанні і має унікальні ефекти. Для якості — Kling; для простоти і експериментів — Pika.", "q": "Pika чи Kling — що краще?"}, {"a": "Pika має безкоштовний план з обмеженнями. Платні плани від $8/міс. Kling AI також має безкоштовний план; від $8,8/міс.", "q": "Pika безкоштовний?"}, {"a": "Pikaffects — унікальні ефекти трансформації в Pika. Наприклад: inflate (роздування), melt (плавлення), explode (вибух) об'єктів на зображенні. Чудово для творчих і вірусних відео.", "q": "Що таке Pikaffects?"}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Pika קל יותר לשימוש ומתאים למתחילים. Kling AI מציג תנועה ריאליסטית יותר. לניסיון ראשון — Pika; לאיכות מרבית — Kling AI.", "q": "Pika מול Kling AI — מה לבחור?"}, {"a": "ל-Pika יש תוכנית חינמית עם קרדיטים מוגבלים. Basic מ-8$/חודש. Kling AI חינמי עם 66 קרדיטים/יום.", "q": "האם Pika בחינם?"}, {"a": "Pika Labs היא סטארטאפ יצירת וידאו AI שהוקמה ב-2023. גייסה מימון משמעותי ומתחרה עם Runway ו-Kling ביצירת וידאו AI.", "q": "Pika Labs — מי הם?"}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Kling est généralement supérieur en qualité vidéo et cohérence physique. Pika est excellent pour les effets créatifs et la créativité expressive. Pour une qualité réaliste, Kling ; pour des effets créatifs et du fun, Pika.", "q": "Pika vs Kling AI — lequel est le meilleur ?"}, {"a": "Pika a un plan gratuit avec des crédits limités. Les plans payants à partir de 8 $/mois. Kling AI à partir de 8 $/mois également.", "q": "Pika est-il gratuit ?"}, {"a": "Oui. Pika a introduit la génération de son IA synchronisé avec la vidéo. C'est une fonctionnalité innovante qui rend les vidéos plus immersives sans avoir besoin d'outils audio séparés.", "q": "Pika peut-il générer du son dans les vidéos ?"}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Pika é mais fácil e acessível para clipes curtos e criativos. Kling AI gera vídeos mais longos com melhor qualidade de movimento. Para experimentos rápidos, Pika; para vídeos mais longos e profissionais, Kling.", "q": "Pika vs Kling AI — qual é o melhor?"}, {"a": "Pika tem plano gratuito com créditos limitados. Planos pagos a partir de $8/mês. Kling AI tem plano gratuito; planos pagos a partir de $9,99/mês.", "q": "Pika é gratuito?"}, {"a": "Sim, um dos principais recursos do Pika é animar fotos estáticas. Você pode fazer objetos se moverem, adicionar efeitos e criar vídeos curtos a partir de qualquer imagem.", "q": "Pika consegue animar imagens?"}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Yes. Pitch includes AI slide generation, AI content suggestions, and AI-powered design assistance. It also offers real-time collaboration, viewer analytics, and team workspaces — differentiating it from solo-focused tools.", "q": "Does Pitch have AI features?"}, {"a": "Pitch is generally preferred for investor pitches due to its professional templates, viewer analytics (see when investors open your deck), and team collaboration. Beautiful.ai works well for internal business presentations.", "q": "Which is better for investor pitches — Beautiful.ai or Pitch?"}]$x$::jsonb
 WHERE slug = 'pitch' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Beautiful.ai tiene una prueba gratuita de 14 días. Los planes de pago empiezan desde $12/mes (Pro). Pitch tiene plan gratuito con presentaciones ilimitadas; planes de team desde $25/mes.", "q": "¿Cuánto cuesta Beautiful.ai?"}, {"a": "Sí. Beautiful.ai permite exportar a PDF y PowerPoint. Esto facilita compartir con personas que no tienen cuenta de Beautiful.ai. La calidad del export a PowerPoint es buena, aunque algunas animaciones automáticas pueden simplificarse en la conversión.", "q": "¿Beautiful.ai puede exportar a PowerPoint?"}]$x$::jsonb
