UPDATE tools SET faq = $x$[{"a": "У Pitch есть бесплатный план для неограниченных колод с базовой совместной работой. Plan Pro — $25/мес для расширенной аналитики, собственных доменов и премиальных шаблонов. Бизнес-планы начинаются от $100/мес для крупных команд.", "q": "Pitch бесплатный?"}, {"a": "Pitch — коллаборативная платформа презентаций для команд. Используется для питчей инвесторам, продажных колод, клиентских презентаций и корпоративных всеобщих собраний. Ключевые дифференциаторы: совместное редактирование в реальном времени, аналитика зрителей и видеообмен сообщениями на слайдах.", "q": "Для чего используется Pitch?"}]$x$::jsonb
