UPDATE tools SET faq = $x$[{"a": "Pitch має безкоштовний план для до 3 членів команди. Pro від $8/член/міс. Gamma має безкоштовний план; Plus від $10/міс.", "q": "Pitch безкоштовний?"}, {"a": "Pitch спеціалізований для бізнес-презентацій з командою і аналітикою. Canva більш загальний з тисячами шаблонів. Pitch для командних бізнес-пітчів; Canva для різноманітних дизайн-потреб.", "q": "Pitch vs Canva для презентацій?"}]$x$::jsonb
