UPDATE tools SET faq = $x$[{"a": "Prezi is still used and has added AI features. However, its zooming presentation style has become less fashionable, and newer tools like Gamma have surpassed it for AI generation quality and modern design. Prezi's main remaining differentiator is its unique non-linear presentation format.", "q": "Is Prezi still relevant in 2026?"}, {"a": "Yes. Prezi AI (launched 2023) can generate presentations from prompts and transform documents into presentations. The AI quality has improved but is generally considered below Gamma or Tome for design output.", "q": "Does Prezi have AI?"}, {"a": "Prezi remains active and profitable but has declined from its peak popularity around 2012-2016. It pivoted to Prezi Video (presenting with overlays on video calls) and Prezi Design, and added AI features. It still has millions of users, particularly in education.", "q": "What happened to Prezi?"}]$x$::jsonb
 WHERE slug = 'prezi' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Prezi puede ser más memorable para presentaciones donde la estructura espacial ayuda a entender relaciones entre conceptos (mapas mentales, timelines). Gamma es más rápido para crear y mejor para texto e imágenes generados por IA. Para profesores con poco tiempo — Gamma; para presentaciones educativas visuales únicas — Prezi.", "q": "¿Gamma o Prezi para presentaciones educativas?"}, {"a": "Prezi tiene un plan gratuito con 5 presentaciones públicas. Los planes de pago empiezan desde $5/mes (Student) o $15/mes (Standard). Gamma tiene plan gratuito con 400 créditos; planes desde $10/mes.", "q": "¿Prezi es gratuito?"}, {"a": "No. Gamma genera presentaciones con estilo de slides tradicional mejoradas con diseño IA. El zoom dinámico espacial es la característica distintiva de Prezi y no está replicado en Gamma. Para narrativa con zoom — Prezi es único en el mercado.", "q": "¿Gamma puede hacer el efecto zoom de Prezi?"}]$x$::jsonb
 WHERE slug = 'prezi' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Gamma ist besser für schnelle KI-generierte Präsentationen mit modernem Design. Prezi ist einzigartiger mit seinem zoombaren Canvas-Ansatz der Zusammenhänge visuell darstellt. Gamma für Geschwindigkeit und Einfachheit; Prezi für nicht-lineares Storytelling.", "q": "Gamma vs Prezi: Was ist besser?"}, {"a": "Prezi hat einen kostenlosen Plan mit 5 Präsentationen. Premium ab $7/Monat. Gamma hat einen kostenlosen Plan mit 400 KI-Credits; Plus ab $10/Monat.", "q": "Ist Prezi kostenlos?"}, {"a": "Prezi ist bei Schülern und Studenten beliebt weil es anders aussieht als PowerPoint und beeindruckt. Der kostenlose Plan ist für Bildungsnutzung ausreichend. Für Uni-Präsentationen bietet Prezi Education vergünstigte Pläne an.", "q": "Prezi für Schule und Uni: Ist es gut?"}]$x$::jsonb
 WHERE slug = 'prezi' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Prezi всё ещё используется и добавил ИИ-функции. Однако стиль масштабируемых презентаций стал менее модным, и более новые инструменты, такие как Gamma, превзошли его по качеству ИИ-генерации и современному дизайну. Главный отличительный признак Prezi — уникальный нелинейный формат.", "q": "Prezi всё ещё актуален в 2026 году?"}, {"a": "Да. Prezi AI (запущен в 2023 году) может генерировать презентации из запросов и преобразовывать документы в презентации. Качество ИИ улучшилось, но в целом считается ниже Gamma по качеству дизайна.", "q": "Есть ли у Prezi ИИ?"}, {"a": "Prezi остаётся активным и прибыльным, но снизился с пика популярности 2012-2016 годов. Pivot к Prezi Video (презентация с наложениями на видеозвонках) и Prezi Design, добавлены ИИ-функции. По-прежнему имеет миллионы пользователей, особенно в образовании.", "q": "Что случилось с Prezi?"}]$x$::jsonb
 WHERE slug = 'prezi' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Gamma краще для швидких ШІ-презентацій із сучасним дизайном. Prezi унікальний з його зумуючим canvas-підходом що показує зв'язки. Gamma для швидкості і простоти; Prezi для нелінійного сторітелінгу.", "q": "Gamma чи Prezi — що краще?"}, {"a": "Prezi має безкоштовний план з 5 презентаціями. Преміум від $7/міс. Gamma має безкоштовний план з 400 ШІ-кредитами; Plus від $10/міс.", "q": "Prezi безкоштовний?"}, {"a": "Prezi популярний серед студентів бо виглядає інакше ніж PowerPoint. Безкоштовний план достатній для навчання. Prezi Education пропонує знижки для студентів.", "q": "Prezi для університету — чи підходить?"}]$x$::jsonb
 WHERE slug = 'prezi' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Gamma מהיר יותר עם AI generation ומצגות web. Prezi ייחודי עם Canvas zooming. Gamma לעיצוב מהיר; Prezi להצגה חיה מרשימה.", "q": "Gamma לעומת Prezi – מה עדיף?"}, {"a": "Prezi מציע תוכנית חינמית עם 5 מצגות; Premium מ-$7/חודש. Gamma חינמי עם 400 נקודות AI; Plus ב-$10/חודש.", "q": "Prezi חינמי?"}, {"a": "Prezi ייחודי ומרשים יותר ויזואלית. PowerPoint אוניברסלי וקל יותר לשיתוף. Prezi לעוצמה ויזואלית; PowerPoint לתאימות.", "q": "Prezi לעומת PowerPoint – מה עדיף?"}]$x$::jsonb
 WHERE slug = 'prezi' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Gamma est meilleur pour des présentations générées rapidement par IA avec un design moderne. Prezi est unique avec son approche canvas zoomable qui illustre les connexions visuellement. Gamma pour la rapidité ; Prezi pour le storytelling non-linéaire.", "q": "Gamma vs Prezi — lequel est le meilleur ?"}, {"a": "Prezi a un plan gratuit avec 5 présentations. Premium à partir de 7 $/mois. Gamma a un plan gratuit avec 400 crédits IA ; Plus à partir de 10 $/mois.", "q": "Prezi est-il gratuit ?"}, {"a": "Prezi est populaire dans l'enseignement car il permet de montrer des connexions entre concepts de manière visuelle. Le plan Education offre des tarifs réduits. Pour les cours et conférences, l'approche non-linéaire de Prezi peut renforcer la compréhension.", "q": "Prezi pour l'enseignement — est-il efficace ?"}]$x$::jsonb
