UPDATE tools SET faq = $x$[{"a": "Gamma é melhor para apresentações geradas rapidamente por IA com design moderno. Prezi é único com sua abordagem de canvas com zoom que ilustra conexões visualmente. Gamma para rapidez; Prezi para storytelling não-linear.", "q": "Gamma vs Prezi — qual é o melhor?"}, {"a": "Prezi tem plano gratuito com 5 apresentações. Premium a partir de $7/mês. Gamma tem plano gratuito com 400 créditos de IA; Plus a partir de $10/mês.", "q": "Prezi é gratuito?"}, {"a": "Prezi é popular no ensino pois permite mostrar conexões entre conceitos de forma visual. O plano Education oferece preços reduzidos. Para aulas e palestras, a abordagem não-linear do Prezi pode reforçar a compreensão.", "q": "Prezi para educação — é eficaz?"}]$x$::jsonb
