UPDATE tools SET faq = $x$[{"a": "QuillBot specializes in paraphrasing and rewriting — transforming existing text into new forms. Grammarly specializes in grammar checking and real-time writing suggestions. QuillBot is better for rephrasing; Grammarly is better for correctness and style improvement.", "q": "What is the difference between QuillBot and Grammarly?"}, {"a": "QuillBot has a free plan with 125 words per paraphrase and limited modes. QuillBot Premium is $4.17/month (annual) or $9.95/month for unlimited paraphrasing, all modes, faster processing, and summarization.", "q": "Is QuillBot free?"}, {"a": "Yes. QuillBot includes a grammar checker as part of its suite. However, Grammarly's grammar checking is more comprehensive and its browser extension works everywhere. QuillBot's grammar tool is secondary to its paraphrasing core feature.", "q": "Can QuillBot fix grammar?"}]$x$::jsonb
 WHERE slug = 'quillbot' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Depende de la necesidad. Grammarly es mejor para verificar gramática y estilo. QuillBot es mejor para parafrasear fuentes y hacer textos más originales. Muchos estudiantes usan ambos: QuillBot para reformular, Grammarly para revisar el resultado.", "q": "¿QuillBot o Grammarly para escritura académica?"}, {"a": "Sí. QuillBot tiene una herramienta de detección de plagio (en el plan Premium) que verifica texto contra páginas web. También tiene verificación de plagio de IA.", "q": "¿QuillBot detecta plagio?"}, {"a": "QuillBot tiene un plan gratuito con parafraseo hasta 125 palabras por vez y 2 modos. QuillBot Premium ($9.95/mes o $4.17/mes anual) desbloquea palabras ilimitadas, todos los modos y herramientas adicionales.", "q": "¿QuillBot es gratuito?"}]$x$::jsonb
 WHERE slug = 'quillbot' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Beide sind wertvoll aber für unterschiedliche Zwecke. QuillBot hilft beim Umformulieren und Zusammenfassen. Grammarly verbessert Grammatik und Stil. Für akademisches Schreiben: Grammarly für Korrektheit, QuillBot zum Variieren des Ausdrucks. Plagiat-Check mit QuillBot oder Grammarly Premium vor der Abgabe.", "q": "QuillBot oder Grammarly für Studenten?"}, {"a": "QuillBot hat einen kostenlosen Plan mit begrenzter Paraphrasierungslänge (125 Wörter) und 3 Schreibmodi. Premium ($9,99/Monat) bietet unbegrenzte Wörter, alle 8 Modi und fortgeschrittene Funktionen. Grammarly hat einen kostenlosen Plan; Premium ab $12/Monat.", "q": "Ist QuillBot kostenlos?"}, {"a": "QuillBot kann Texte umschreiben, aber das Einreichen paraphrasierter fremder Werke als eigene Arbeit verstößt gegen akademische Integritätsrichtlinien. QuillBot ist nützlich um eigene Ideen klarer auszudrücken oder Wiederholungen zu vermeiden — nicht um Plagiate zu verschleiern.", "q": "Kann QuillBot akademische Arbeiten umschreiben?"}]$x$::jsonb
 WHERE slug = 'quillbot' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "QuillBot специализируется на перефразировании — переписывает готовый текст с другим стилем. Grammarly фокусируется на проверке грамматики и улучшении написанного текста в реальном времени. QuillBot меняет то, что уже написано, Grammarly помогает писать правильно с первого раза.", "q": "В чём разница QuillBot и Grammarly?"}, {"a": "Да. QuillBot предлагает бесплатный план с базовым перефразированием (ограниченные режимы) и суммаризатором. Premium ($9.95/мес) открывает все режимы, быстрее и без лимитов. Grammarly также бесплатен с базовой проверкой.", "q": "QuillBot бесплатный?"}, {"a": "Да, QuillBot популярен среди студентов для парафраза источников и перефразирования собственных текстов. Включает генератор цитат (APA, MLA). Однако злоупотребление перефразированием для обхода проверки на плагиат нарушает академические правила.", "q": "QuillBot хорош для академических работ?"}]$x$::jsonb
 WHERE slug = 'quillbot' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Обидва корисні але для різних цілей. QuillBot допомагає перефразувати і різноманітити вирази. Grammarly виправляє граматику і стиль. Для академічного письма: Grammarly для точності, QuillBot для урізноманітнення виразів.", "q": "QuillBot чи Grammarly для студентів?"}, {"a": "QuillBot має безкоштовний план з обмеженнями (125 слів, 3 режими). Premium ($9,99/міс) — необмежено. Grammarly безкоштовний; Premium від $12/міс.", "q": "QuillBot безкоштовний?"}, {"a": "QuillBot може перефразовувати текст, але подавати перефразований чужий текст як власний — порушення академічної доброчесності. QuillBot корисний для кращого вираження власних ідей, не для приховування плагіату.", "q": "Чи можна використовувати QuillBot для рефератів?"}]$x$::jsonb
 WHERE slug = 'quillbot' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "שניהם שימושיים אבל למטרות שונות. QuillBot עוזר לנסח ולגוון ביטויים. Grammarly מתקן דקדוק וסגנון. לכתיבה אקדמית: Grammarly לדיוק, QuillBot לגיוון ביטויים.", "q": "QuillBot או Grammarly לסטודנטים?"}, {"a": "ל-QuillBot יש תוכנית חינמית עם מגבלות (125 מילים, 3 מצבים). Premium (9.99$/חודש) — ללא הגבלה. Grammarly חינמי; Premium מ-12$/חודש.", "q": "האם QuillBot בחינם?"}, {"a": "QuillBot יכול לנסח מחדש טקסט, אבל הגשת יצירה של אחרים שנוסחה מחדש כשלכם מפרה כללי יושרה אקדמית. QuillBot שימושי להבעת רעיונות שלכם בצורה ברורה יותר, לא להסתרת פלגיאט.", "q": "האם אפשר להשתמש ב-QuillBot לעבודות?"}]$x$::jsonb
 WHERE slug = 'quillbot' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Les deux sont utiles mais pour des objectifs différents. QuillBot aide à paraphraser et à varier les expressions. Grammarly corrige la grammaire et le style. Pour la rédaction académique : Grammarly pour la précision, QuillBot pour varier les expressions.", "q": "QuillBot ou Grammarly pour les étudiants ?"}, {"a": "QuillBot a un plan gratuit avec des limites (125 mots, 3 modes). Premium (9,99 $/mois) — illimité. Grammarly est gratuit ; Premium à partir de 12 $/mois.", "q": "QuillBot est-il gratuit ?"}, {"a": "QuillBot peut paraphraser du texte, mais soumettre un texte d'autrui paraphrasé comme son propre travail viole les règles d'intégrité académique. QuillBot est utile pour mieux exprimer ses propres idées, pas pour dissimuler un plagiat.", "q": "Peut-on utiliser QuillBot pour des dissertations ?"}]$x$::jsonb
 WHERE slug = 'quillbot' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Ambos são úteis, mas para objetivos diferentes. QuillBot ajuda a parafrasear e variar expressões. Grammarly corrige gramática e estilo. Para redação acadêmica: Grammarly para precisão, QuillBot para variar expressões.", "q": "QuillBot ou Grammarly para estudantes?"}, {"a": "QuillBot tem plano gratuito com limites (125 palavras, 3 modos). Premium ($9,99/mês) — ilimitado. Grammarly é gratuito; Premium a partir de $12/mês.", "q": "QuillBot é gratuito?"}, {"a": "QuillBot pode parafrasear texto, mas submeter texto de outro parafraseado como trabalho próprio viola regras de integridade acadêmica. QuillBot é útil para expressar melhor suas próprias ideias, não para ocultar plágio.", "q": "É possível usar o QuillBot para trabalhos acadêmicos?"}]$x$::jsonb
