UPDATE tools SET faq = $x$[{"a": "Reclaim.ai is a smart calendar tool that automatically protects time for habits, tasks, and focus blocks in your Google Calendar. It also has intelligent meeting scheduling and calendar sync to prevent conflicts across multiple calendars.", "q": "What is Reclaim.ai?"}, {"a": "Reclaim.ai has a free plan with basic features for one user. Starter is $8/user/month, Business is $12/user/month, and Enterprise is custom. It's significantly cheaper than Motion for teams.", "q": "Is Reclaim.ai free?"}]$x$::jsonb
