UPDATE tools SET faq = $x$[{"a": "Sí. Reclaim tiene integración con Jira, Asana, Linear y Todoist. Importa tus tareas y las programa automáticamente en tu calendario según disponibilidad y prioridad. Esta integración con herramientas de desarrollo es una de las razones por las que es popular entre equipos técnicos.", "q": "¿Reclaim AI puede sincronizar con Jira?"}, {"a": "Sí. Motion tiene funciones de gestión de proyectos de equipo — asignar tareas, gestionar deadlines y coordinar workload entre miembros. La IA planifica el trabajo de cada persona según su disponibilidad real en el calendario. Es más potente que Reclaim para gestión de proyectos.", "q": "¿Motion puede gestionar proyectos de equipo?"}]$x$::jsonb
 WHERE slug = 'reclaim-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Ja. Reclaim AI ist primär für Google Kalender entwickelt und integriert sich tief. Es schützt Fokuszeiten, plant Habits ein und optimiert Meeting-Scheduling automatisch. Outlook-Integration ist ebenfalls verfügbar.", "q": "Funktioniert Reclaim mit Google Kalender?"}, {"a": "Ja. Motion hat Team-Features: gemeinsame Projektplanung, Task-Zuweisung und Team-Kalender. Es plant Aufgaben automatisch basierend auf Verfügbarkeit und Priorität für das gesamte Team.", "q": "Kann Motion Teamprojekte verwalten?"}]$x$::jsonb
 WHERE slug = 'reclaim-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Да. Reclaim.ai предлагает бесплатный план для 1 пользователя с базовой автоматизацией. Starter — $8/мес, Business — $12/мес. Motion не имеет бесплатного плана.", "q": "Reclaim.ai бесплатный?"}, {"a": "Да. Motion интегрируется с Google Календарём и Outlook. Он читает существующие события и планирует задачи вокруг них. Reclaim.ai также работает с Google Календарём.", "q": "Работает ли Motion с Google Календарём?"}]$x$::jsonb
 WHERE slug = 'reclaim-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Todoist — традиційний task manager де ви самі вирішуєте коли робити завдання. Motion автоматично планує коли виконати кожне завдання виходячи з дедлайнів і доступного часу. Motion для автоматичного планування; Todoist для структурованих списків.", "q": "Motion vs Todoist — яка різниця?"}, {"a": "Reclaim.ai оптимізований для Google Calendar. Підтримка Outlook обмежена. Якщо ваша компанія на Microsoft 365 — перевірте актуальну сумісність на сайті Reclaim.ai.", "q": "Reclaim.ai працює з Outlook?"}]$x$::jsonb
 WHERE slug = 'reclaim-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Reclaim.ai תומך בעיקר ב-Google Calendar. תמיכה ב-Outlook מוגבלת. לשילוב עם Microsoft 365, Clockwise או Microsoft Copilot Calendar עשויים להתאים יותר.", "q": "Reclaim.ai עובד עם Outlook?"}, {"a": "עבור אנשים שמרוויחים בשעה יותר מ-$34, Motion שווה את ההשקעה אם הוא אכן חוסך שעה לשבוע בתזמון. ניסיון חינמי זמין לפני ההחלטה.", "q": "Motion שווה את המחיר?"}]$x$::jsonb
 WHERE slug = 'reclaim-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Reclaim AI a un plan gratuit pour 1 calendrier avec des fonctionnalités de base. Plus à partir de 10 $/utilisateur/mois. Motion n'a pas de plan gratuit permanent.", "q": "Reclaim AI est-il gratuit ?"}, {"a": "Oui. Motion s'intègre avec Google Calendar et Microsoft Outlook. Il lit vos réunions existantes et planifie vos tâches dans les créneaux disponibles. La synchronisation est bidirectionnelle.", "q": "Motion fonctionne-t-il avec Google Calendar ?"}]$x$::jsonb
 WHERE slug = 'reclaim-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Sim, Motion sincroniza com Google Calendar e Outlook. Ele gerencia seus compromissos existentes e adiciona blocos de tempo para tarefas automaticamente.", "q": "Motion funciona com Google Calendar?"}, {"a": "Sim, este é um dos casos de uso populares do Reclaim. Você define quando quer se exercitar e por quanto tempo, e o Reclaim encontra automaticamente os melhores slots na sua agenda.", "q": "Reclaim AI pode agendar exercícios?"}]$x$::jsonb
 WHERE slug = 'reclaim-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Retool is a low-code platform for building internal tools. Developers connect to databases and APIs, then build admin panels, dashboards, and CRUD apps using drag-and-drop components. Unlike dashboards, Retool apps can take actions — edit database records, trigger workflows, send data.", "q": "What is Retool?"}, {"a": "Retool has a free plan for up to 5 users with basic features. Team plan is $10/user/month, Business is $50/user/month, and Enterprise is custom. The free plan is functional for small teams building internal tools.", "q": "Is Retool free?"}, {"a": "Retool is low-code rather than no-code. It requires some technical knowledge — connecting to databases, writing SQL queries, and understanding APIs. It's designed for developers and technical teams, not business users without technical background.", "q": "Is Retool a no-code tool?"}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Retool está diseñado específicamente para herramientas internas de empresa — se conecta a bases de datos y APIs existentes con menos configuración. Bubble es mejor para aplicaciones de cara al usuario con base de datos propia. Para herramientas internas de equipo — Retool; para apps de usuario final — Bubble.", "q": "¿Retool o Bubble para apps internas?"}, {"a": "Retool tiene plan gratuito para hasta 5 usuarios con apps ilimitadas. Los planes de pago empiezan desde $10/usuario/mes (Team). Looker Studio es completamente gratuito.", "q": "¿Retool es gratuito?"}, {"a": "Sí. Retool se conecta a más de 100 fuentes de datos: PostgreSQL, MySQL, MongoDB, REST APIs, GraphQL, Airtable, Salesforce, Stripe y muchas más. Esta compatibilidad amplia es una de sus mayores fortalezas para construcción de herramientas internas.", "q": "¿Retool puede conectarse a cualquier base de datos?"}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Retool ist eine Low-Code-Plattform für interne Tools. Entwickler verbinden Datenbanken und APIs und bauen Admin-Panels, CRUD-Interfaces und Operations-Dashboards visuell. Retool AI fügt KI-gestützte Komponenten-Generierung und Workflow-Automation hinzu.", "q": "Was ist Retool?"}, {"a": "Retool hat einen kostenlosen Plan für bis zu 5 Benutzer. Team-Pläne ab $10/Benutzer/Monat. Looker Studio ist vollständig kostenlos. Retool ist deutlich teurer aber bietet volle Interaktivität und Backend-Integration.", "q": "Wie viel kostet Retool?"}, {"a": "Ja. Retool verbindet sich direkt mit PostgreSQL, MySQL, MongoDB, Supabase und vielen anderen Datenbanken. Sie können SQL-Queries schreiben und die Ergebnisse direkt in interaktiven UI-Komponenten anzeigen.", "q": "Kann Retool mit PostgreSQL verbinden?"}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Retool — конструктор внутренних приложений: создаёт операционные инструменты с CRUD-интерфейсами. Looker Studio — BI-инструмент для визуализации: создаёт аналитические дашборды. Retool строит приложения, Looker Studio строит отчёты.", "q": "Retool vs Looker Studio — в чём разница?"}, {"a": "Да. Looker Studio полностью бесплатен от Google. Retool бесплатен до 5 пользователей с базовыми функциями; Business-план от $10/пользователь/мес.", "q": "Looker Studio бесплатный?"}, {"a": "Retool сокращает время разработки внутренних инструментов в 10 раз, но требует технического пользователя. Для создания сложных приложений с нестандартной логикой всё равно нужен разработчик.", "q": "Заменяет ли Retool разработку?"}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Обидва low-code конструктори внутрішніх інструментів. AppSmith відкритий і безкоштовний. Retool має більше компонентів і кращу підтримку але платний. Для open-source і self-hosted — AppSmith; для швидшого старту з підтримкою — Retool.", "q": "Retool vs AppSmith — яка різниця?"}, {"a": "Retool має безкоштовний план для 5 користувачів. Team від $10/користувач/міс. Looker Studio повністю безкоштовний.", "q": "Retool безкоштовний?"}, {"a": "Looker Studio кращий для маркетологів у Google-екосистемі — безкоштовний і відмінно інтегрується з GA4 і Google Ads. Power BI кращий якщо компанія на Microsoft 365. Для Google-маркетингу — Looker Studio однозначно.", "q": "Looker Studio vs Power BI для маркетингу?"}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Retool לבניית כלים פנימיים ואפליקציות. Looker Studio לדשבורדי BI. Retool לצוותים טכניים שבונים כלים; Looker לצוותי עסקים שצופים בנתונים.", "q": "Retool לעומת Looker Studio – מה ההבדל?"}, {"a": "Retool מציע תוכנית חינמית ל-5 משתמשים; Team ב-$10/משתמש/חודש. Looker Studio חינמי לחלוטין.", "q": "כמה עולה Retool?"}, {"a": "Retool מתאים לכלים פנימיים ולנתונים מסד. Bubble מתאים לאפליקציות ציבוריות עם משתמשי קצה. Retool לops tools; Bubble ל-SaaS ולאפליקציות לקוחות.", "q": "Retool לעומת Bubble?"}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Retool crée des outils internes et des applications admin avec du code. Looker Studio crée des dashboards de BI sans code. Applications internes → Retool ; dashboards de reporting → Looker Studio.", "q": "Retool vs Looker Studio — quelle est la différence ?"}, {"a": "Retool a un plan gratuit jusqu'à 5 utilisateurs. Team à partir de 10 $/utilisateur/mois. Looker Studio est entièrement gratuit.", "q": "Retool est-il gratuit ?"}, {"a": "Oui. Retool est très populaire parmi les startups pour créer rapidement des outils internes : panneaux admin, outils de support client, interfaces opérationnelles. C'est souvent plus rapide que de développer ces outils from scratch.", "q": "Retool est-il adapté aux startups ?"}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Retool é para ferramentas internas interativas com lógica de negócios. Looker Studio é para dashboards de visualização de dados de marketing. São ferramentas diferentes: Retool para apps internos; Looker para relatórios.", "q": "Retool vs Looker Studio — qual usar?"}, {"a": "Retool tem plano gratuito para até 5 usuários. Planos pagos a partir de $10/usuário/mês. Looker Studio é completamente gratuito.", "q": "Retool AI é gratuito?"}, {"a": "Sim, Retool é muito popular em startups. Permite criar ferramentas internas em horas em vez de semanas. O plano gratuito é generoso para equipes pequenas.", "q": "Retool é bom para startups?"}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "It depends on your priority. Runway Gen-4.5 leads on benchmark quality and offers a multi-model subscription. Kling 3.0 offers better value — more free credits, native 4K, and lower paid pricing. For professionals, Runway. For value, Kling.", "q": "Is Kling AI better than Runway in 2026?"}, {"a": "Runway Gen-4.5 is Runway's latest video model, ranking #1 on text-to-video quality leaderboards as of 2025. It's available on all paid Runway plans and one subscription also includes Veo 3.1, Kling 3.0, Seedance, and FLUX.", "q": "What is Runway Gen-4.5?"}]$x$::jsonb
 WHERE slug = 'runway' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Seedance 2.0 es un modelo de generación de video IA desarrollado por ByteDance (la empresa de TikTok). Genera videos de alta calidad desde texto o imágenes con física realista y buena coherencia temporal. Compite en el tier superior de generadores de video junto a Runway, Kling y Veo.", "q": "¿Qué es Seedance 2.0?"}, {"a": "Runway está disponible globalmente aunque con algunas restricciones regionales. Los planes y precios son los mismos internacionalmente. Seedance puede tener disponibilidad más limitada según la región dado que es más reciente.", "q": "¿Runway está disponible en todos los países?"}]$x$::jsonb
 WHERE slug = 'runway' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Seedance ist ein KI-Video-Generator von ByteDance (TikTok-Muttergesellschaft). Seedance 2.0 generiert hochwertige Videos aus Text oder Bildern mit besonderem Fokus auf flüssige Bewegungen und Konsistenz. Es positioniert sich als qualitativ hochwertiger und günstiger Runway-Konkurrent.", "q": "Was ist Seedance?"}, {"a": "Prüfen Sie die aktuelle Preisgestaltung auf der Seedance-Website da sich Preise bei neuen KI-Tools schnell ändern. Runway beginnt ab $15/Monat.", "q": "Wie viel kostet Seedance?"}]$x$::jsonb
 WHERE slug = 'runway' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Зависит от приоритетов. Runway Gen-4.5 лидирует по качеству бенчмаркам и предлагает многомодельную подписку. Kling 3.0 предлагает лучшую ценность — больше бесплатных кредитов, нативное 4K и более низкую цену. Для профессионалов — Runway, для соотношения цена/качество — Kling.", "q": "Kling AI лучше Runway в 2026 году?"}, {"a": "Runway Gen-4.5 — последняя видеомодель Runway, занимающая первое место в рейтингах text-to-video по состоянию на 2025 год. Доступна на всех платных планах Runway, а подписка также включает Veo 3.1, Kling 3.0, Seedance и FLUX.", "q": "Что такое Runway Gen-4.5?"}]$x$::jsonb
 WHERE slug = 'runway' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Runway є більш зрілим і широко прийнятим у галузі з кращим набором функцій. Seedance є сильним конкурентом для відео з природнім рухом. Для виробничого відео — Runway; для тестування нових можливостей руху — Seedance.", "q": "Seedance vs Runway — що краще?"}, {"a": "Seedance 2.0 — оновлена версія з покращеним рухом персонажів і фізикою. Конкурує з моделями Gen-4 від Runway і Kling від Kuaishou. Перевірте офіційний сайт для актуальних можливостей.", "q": "Seedance 2.0 що новго?"}]$x$::jsonb
 WHERE slug = 'runway' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Runway הסטנדרט המקצועי עם הכלים המלאים ביותר. Seedance נגיש יותר ועם Motion איכותי. Runway לפרודקשן; Seedance לתוכן מהיר.", "q": "Seedance לעומת Runway?"}, {"a": "Runway Gen-3 Alpha מייצר וידאו ריאליסטי ועקבי ברמה גבוהה. אחד מהמודלים המובילים לווידאו AI יחד עם Kling ו-Sora.", "q": "Runway Gen-3 – כמה זה מרשים?"}]$x$::jsonb
 WHERE slug = 'runway' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Runway est plus établi avec plus de fonctionnalités d'édition avancées. Seedance 2.0 est apprécié pour la cohérence des personnages. Essayez les deux avec leurs plans gratuits ou d'essai pour voir lequel convient le mieux à vos besoins.", "q": "Seedance 2.0 vs Runway — lequel est le meilleur ?"}, {"a": "Runway génère des vidéos jusqu'à 10 secondes par génération avec Gen-3. Pour des vidéos plus longues, vous chaînez plusieurs générations. D'autres outils comme Google Veo 3 permettent des vidéos plus longues en une seule génération.", "q": "Runway peut-il générer des vidéos longues ?"}]$x$::jsonb
 WHERE slug = 'runway' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Runway é mais estabelecido com mais funcionalidades de edição avançadas. Seedance 2.0 é apreciado pela consistência de personagens. Experimente os dois com seus planos de avaliação para ver qual atende melhor às suas necessidades.", "q": "Seedance 2.0 vs Runway — qual é o melhor?"}, {"a": "Runway gera vídeos de até 10 segundos por geração com Gen-3. Para vídeos mais longos, você encadeia várias gerações. Outras ferramentas como Google Veo 3 permitem vídeos mais longos em uma única geração.", "q": "Runway pode gerar vídeos longos?"}]$x$::jsonb
 WHERE slug = 'runway' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Scite is an academic research tool that shows how scientific papers have been cited — specifically whether citations are supporting, contrasting, or mentioning the original claim. This helps researchers evaluate the reliability and controversy around specific findings.", "q": "What is Scite?"}, {"a": "Scite has a free plan with limited reference checks per month. Scite Pro is $20/month or $144/year for unlimited access. Institutional and group plans are available.", "q": "Is Scite free?"}, {"a": "Google Scholar shows how many times a paper was cited. Scite shows how it was cited — supporting, contrasting, or mentioning — giving context on whether subsequent research validated or challenged the original findings. Scite adds qualitative citation analysis that Google Scholar lacks.", "q": "What is the difference between Scite and Google Scholar?"}]$x$::jsonb
 WHERE slug = 'scite' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Smart Citations de Scite clasifica automáticamente las citas de un paper según si citas posteriores lo apoyan (supporting), contradicen (contrasting) o simplemente lo mencionan (mentioning). Esto te permite evaluar rápidamente si un paper ha sido validado o refutado por la comunidad científica.", "q": "¿Qué son las Smart Citations de Scite?"}, {"a": "Scite se centra en clasificar citaciones (supporting/contrasting). ResearchRabbit es mejor para descubrir literatura relacionada visualmente — crea mapas de investigación conectando papers por similitud y autores. Para verificar claims — Scite; para explorar un campo nuevo — ResearchRabbit.", "q": "¿Scite vs ResearchRabbit?"}, {"a": "Semantic Scholar cubre todas las disciplinas académicas: ciencias, medicina, informática, ciencias sociales, humanidades, ingeniería y más. Con 200 millones de papers, es una de las bases de datos académicas más completas disponibles gratuitamente.", "q": "¿Qué disciplinas cubre Semantic Scholar?"}]$x$::jsonb
 WHERE slug = 'scite' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Scite analysiert wie Studien in späteren Papers zitiert werden — ob die zitierende Studie die ursprüngliche Findung unterstützt, widerlegt oder neutral erwähnt. Das gibt Ihnen sofort einen Überblick über die wissenschaftliche Akzeptanz einer Studie.", "q": "Was sind Smart Citations bei Scite?"}, {"a": "PubMed ist die primäre Datenbank für biomedizinische Literatur — am vollständigsten und aktuellsten für Medizin. Scite fügt eine wichtige Dimension hinzu: die Qualität der Zitationen. Für biomedizinische Forschung — PubMed als Primärquelle, Scite für Qualitätsbewertung.", "q": "Scite vs PubMed: Was ist besser?"}, {"a": "Semantic Scholar kann deutsche Suchanfragen verarbeiten, aber die Datenbank enthält überwiegend englischsprachige Publikationen. Für deutschsprachige wissenschaftliche Literatur sind Datenbanken wie DBIS oder spezifische Fach-Repositorien besser.", "q": "Kann Semantic Scholar auf Deutsch arbeiten?"}]$x$::jsonb
 WHERE slug = 'scite' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Scite уникален тем, что показывает, как статья процитирована — поддерживающие, опровергающие или нейтральные упоминания. Semantic Scholar — бесплатный ИИ-поисковик по научным работам с суммаризацией. Scite для оценки доказательной базы, Semantic Scholar для широкого поиска.", "q": "Scite vs Semantic Scholar — в чём разница?"}, {"a": "Semantic Scholar добавляет ИИ-функции: суммаризация, связанные работы, граф влияния. Google Scholar охватывает больше источников, включая патенты и диссертации. Для академических работ — Semantic Scholar, для широкого поиска — Google Scholar.", "q": "Semantic Scholar лучше Google Scholar?"}, {"a": "Да. Scite индексирует биомедицинские исследования, совместимые с PubMed, и показывает Smart Citations для медицинских статей. Это особенно ценно для медицинских исследователей, проверяющих консенсус по клиническим данным.", "q": "Scite работает с PubMed?"}]$x$::jsonb
 WHERE slug = 'scite' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Google Scholar показує хто цитує статтю. Scite показує як цитує — підтримуючи, суперечачи чи нейтрально. Scite дає якісний аналіз цитувань; Google Scholar ширше покриття.", "q": "Scite vs Google Scholar — яка різниця?"}, {"a": "Semantic Scholar — безкоштовна пошукова система наукових публікацій від Allen Institute for AI. Охоплює понад 220 мільйонів статей і використовує ШІ для аналізу важливості і зв'язків між публікаціями.", "q": "Що таке Semantic Scholar?"}, {"a": "Так. Scite дуже корисний для медичних досліджень — розуміти чи підтверджені результати клінічних досліджень наступними роботами. Дозволяє оцінити надійність доказової бази.", "q": "Scite для медичних досліджень?"}]$x$::jsonb
 WHERE slug = 'scite' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Scite מתמחה בניתוח ציטוטים לפי הקשר – תומך, סותר או ניטרלי. Semantic Scholar הוא מנוע חיפוש אקדמי כללי עם AI. Scite לאימות מחקר; Semantic Scholar לחיפוש ספרות.", "q": "Scite לעומת Semantic Scholar – מה ההבדל?"}, {"a": "שניהם חינמיים ומאנדקסים מאמרים אקדמיים. Semantic Scholar מציע AI כמו TLDR ו-Paper Recommendations. Google Scholar מכסה יותר מקורות ויש לו אינדקס גדול יותר.", "q": "Semantic Scholar לעומת Google Scholar?"}, {"a": "כן, Scite מצוין ל-Evidence-based Medicine. Smart Citations מאפשרות לראות האם מחקרים אחרים תמכו או הפריכו ממצא קליני ספציפי.", "q": "Scite לרפואה מבוססת ראיות?"}]$x$::jsonb
 WHERE slug = 'scite' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Scite est unique pour analyser comment une étude est citée (soutenue ou contredite). Semantic Scholar est meilleur pour la découverte large de littérature gratuite. Évaluation de la robustesse des preuves → Scite ; découverte de littérature → Semantic Scholar.", "q": "Scite vs Semantic Scholar — lequel est le meilleur ?"}, {"a": "Semantic Scholar est principalement en anglais mais indexe aussi des publications en d'autres langues. L'interface est en anglais. Pour la recherche francophone, PubMed et Google Scholar sont aussi de bonnes options.", "q": "Semantic Scholar est-il disponible en français ?"}, {"a": "Scite peut indiquer si un article est peu cité ou contredit, ce qui peut signaler des problèmes. Mais pour les rétractations officielles, Retraction Watch est la référence spécifique.", "q": "Scite peut-il détecter la rétractation d'articles ?"}]$x$::jsonb
 WHERE slug = 'scite' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Scite é para análise qualitativa de citações — entender como papers são citados. Semantic Scholar é para descoberta e recomendação de papers. Para análise de evidências, Scite; para descoberta de literatura, Semantic Scholar.", "q": "Scite vs Semantic Scholar — qual usar?"}, {"a": "Sim, Semantic Scholar é desenvolvido pelo Allen Institute for AI e é amplamente usado por pesquisadores. Cobre mais de 200 milhões de papers com dados de citações precisos.", "q": "Semantic Scholar é confiável?"}, {"a": "Scite analisa papers em múltiplos idiomas, mas o corpus principal é em inglês. Para literatura científica em português, a cobertura é menor.", "q": "Scite funciona com papers em português?"}]$x$::jsonb
 WHERE slug = 'scite' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Seedance 2.0 is ByteDance's AI video generation model, known for high-quality video output with realistic motion. It's the model underlying some CapCut AI video features and is available to developers via APIs like fal.ai. ByteDance developed it as a direct competitor to Runway and Kling.", "q": "What is Seedance 2.0?"}, {"a": "Seedance 2.0 produces video quality competitive with Runway Gen-4.5 at potentially lower API costs. However, Runway offers a complete production platform with multiple models, editing tools, and professional workflows that Seedance alone doesn't match. For raw generation quality, they're comparable; for production use, Runway has more tools.", "q": "Is Seedance better than Runway?"}, {"a": "Seedance 2.0 is primarily accessible through developer APIs (fal.ai, Replicate) or indirectly through CapCut's AI video features. There's no dedicated Seedance consumer product — it's an underlying model accessed through other platforms.", "q": "How do I access Seedance 2.0?"}]$x$::jsonb
 WHERE slug = 'seedance-2-0' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Seedance 2.0 es un modelo de generación de video IA desarrollado por ByteDance (la empresa de TikTok). Genera videos de alta calidad desde texto o imágenes con física realista y buena coherencia temporal. Compite en el tier superior de generadores de video junto a Runway, Kling y Veo.", "q": "¿Qué es Seedance 2.0?"}, {"a": "Seedance 2.0 y Kling 2.0 compiten directamente en calidad. Kling tiene mayor disponibilidad de acceso y más experiencia en el mercado. Seedance 2.0 muestra resultados impresionantes especialmente en física de movimiento. La competencia entre ambos es intensa en 2025.", "q": "¿Seedance es mejor que Kling?"}, {"a": "Runway está disponible globalmente aunque con algunas restricciones regionales. Los planes y precios son los mismos internacionalmente. Seedance puede tener disponibilidad más limitada según la región dado que es más reciente.", "q": "¿Runway está disponible en todos los países?"}]$x$::jsonb
 WHERE slug = 'seedance-2-0' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Seedance ist ein KI-Video-Generator von ByteDance (TikTok-Muttergesellschaft). Seedance 2.0 generiert hochwertige Videos aus Text oder Bildern mit besonderem Fokus auf flüssige Bewegungen und Konsistenz. Es positioniert sich als qualitativ hochwertiger und günstiger Runway-Konkurrent.", "q": "Was ist Seedance?"}, {"a": "Beide sind von chinesischen Unternehmen entwickelt und konkurrieren im Premium-Segment. Kling AI ist etablierter und bekannter. Seedance 2.0 hat starke technische Grundlagen durch ByteDances Forschung. Für bewährt gute Qualität — Kling; für ByteDances neueste Technologie — Seedance.", "q": "Seedance vs Kling AI: Was ist besser?"}, {"a": "Prüfen Sie die aktuelle Preisgestaltung auf der Seedance-Website da sich Preise bei neuen KI-Tools schnell ändern. Runway beginnt ab $15/Monat.", "q": "Wie viel kostet Seedance?"}]$x$::jsonb
 WHERE slug = 'seedance-2-0' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Runway Gen-4.5 занимает верхние строки в большинстве лидербордов качества ИИ-видео. Seedance 2.0 от ByteDance — сильный конкурент с отличным соотношением цены и качества. Runway более зрелая платформа; Seedance может быть дешевле для сопоставимого качества.", "q": "Seedance vs Runway — что лучше?"}, {"a": "Seedance 2.0 — ИИ-видеомодель от ByteDance (создатели TikTok). Специализируется на реалистичном движении и динамичных сценах. Доступен через API и ряд платформ.", "q": "Что такое Seedance 2.0?"}, {"a": "Runway предлагает 125 вступительных кредитов. Standard — $15/мес, Pro — $35/мес. Стоимость генерации видео зависит от длины и качества.", "q": "Runway бесплатный?"}]$x$::jsonb
 WHERE slug = 'seedance-2-0' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Runway є більш зрілим і широко прийнятим у галузі з кращим набором функцій. Seedance є сильним конкурентом для відео з природнім рухом. Для виробничого відео — Runway; для тестування нових можливостей руху — Seedance.", "q": "Seedance vs Runway — що краще?"}, {"a": "Runway має безкоштовний план з обмеженими кредитами. Standart від $15/міс; Pro від $35/міс. Seedance — перевірте поточні плани на сайті.", "q": "Runway безкоштовний?"}, {"a": "Seedance 2.0 — оновлена версія з покращеним рухом персонажів і фізикою. Конкурує з моделями Gen-4 від Runway і Kling від Kuaishou. Перевірте офіційний сайт для актуальних можливостей.", "q": "Seedance 2.0 що новго?"}]$x$::jsonb
 WHERE slug = 'seedance-2-0' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Runway הסטנדרט המקצועי עם הכלים המלאים ביותר. Seedance נגיש יותר ועם Motion איכותי. Runway לפרודקשן; Seedance לתוכן מהיר.", "q": "Seedance לעומת Runway?"}, {"a": "Runway מציע 125 Credits חינם; Standard מ-$15/חודש. Seedance – בדקו את האתר לפרטי תמחור עדכניים.", "q": "Runway חינמי?"}, {"a": "Runway Gen-3 Alpha מייצר וידאו ריאליסטי ועקבי ברמה גבוהה. אחד מהמודלים המובילים לווידאו AI יחד עם Kling ו-Sora.", "q": "Runway Gen-3 – כמה זה מרשים?"}]$x$::jsonb
 WHERE slug = 'seedance-2-0' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Runway est plus établi avec plus de fonctionnalités d'édition avancées. Seedance 2.0 est apprécié pour la cohérence des personnages. Essayez les deux avec leurs plans gratuits ou d'essai pour voir lequel convient le mieux à vos besoins.", "q": "Seedance 2.0 vs Runway — lequel est le meilleur ?"}, {"a": "Vérifiez les tarifs actuels de Seedance sur leur site. Runway a un plan gratuit avec des crédits limités ; Standard à partir de 15 $/mois.", "q": "Seedance 2.0 est-il gratuit ?"}, {"a": "Runway génère des vidéos jusqu'à 10 secondes par génération avec Gen-3. Pour des vidéos plus longues, vous chaînez plusieurs générations. D'autres outils comme Google Veo 3 permettent des vidéos plus longues en une seule génération.", "q": "Runway peut-il générer des vidéos longues ?"}]$x$::jsonb
 WHERE slug = 'seedance-2-0' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Runway é mais estabelecido com mais funcionalidades de edição avançadas. Seedance 2.0 é apreciado pela consistência de personagens. Experimente os dois com seus planos de avaliação para ver qual atende melhor às suas necessidades.", "q": "Seedance 2.0 vs Runway — qual é o melhor?"}, {"a": "Verifique os preços atuais do Seedance no site deles. Runway tem plano gratuito com créditos limitados; Standard a partir de $15/mês.", "q": "Seedance 2.0 é gratuito?"}, {"a": "Runway gera vídeos de até 10 segundos por geração com Gen-3. Para vídeos mais longos, você encadeia várias gerações. Outras ferramentas como Google Veo 3 permitem vídeos mais longos em uma única geração.", "q": "Runway pode gerar vídeos longos?"}]$x$::jsonb
 WHERE slug = 'seedance-2-0' AND lang = 'pt';

