UPDATE tools SET faq = $x$[{"a": "Slidesgo is a library of free and premium presentation templates for Google Slides and PowerPoint. It offers thousands of professionally designed templates for business, education, marketing, and creative purposes. Slidesgo AI can generate presentations from text prompts as complete Google Slides files.", "q": "What is Slidesgo?"}, {"a": "Slidesgo offers free templates with limited selection and Slidesgo branding. Premium plan is $5.99/month or $49.99/year for access to all templates without branding. Slidesgo AI generation requires a premium subscription.", "q": "Is Slidesgo free?"}, {"a": "Both offer presentation templates, but Slidesgo specializes in presentation templates for Google Slides and PowerPoint. Canva is a broader design platform with presentations as one of many format types. Slidesgo has more presentation-specific templates; Canva has more overall design versatility.", "q": "What is the difference between Slidesgo and Canva?"}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Slidesgo tiene miles de plantillas gratuitas accesibles sin registro. Slidesgo Premium ($7.99/mes) desbloquea todas las plantillas y funciones avanzadas. Gamma tiene plan gratuito con 400 créditos; planes desde $10/mes. Para plantillas gratis — Slidesgo; para generación IA de contenido — Gamma.", "q": "¿Slidesgo es gratuito?"}, {"a": "Slidesgo tiene Slidesgo AI Presentation Maker que genera presentaciones desde un prompt de texto, similar a Gamma pero con menor potencia de IA. La principal fortaleza de Slidesgo son sus templates de diseño para Google Slides y PowerPoint, no la generación de contenido.", "q": "¿Slidesgo tiene IA?"}, {"a": "Canva tiene más funciones de diseño personalizable y herramientas de IA más potentes. Slidesgo se especializa en plantillas para Google Slides y PowerPoint específicamente. Para diseño personalizado completo — Canva; para plantillas de calidad directamente en Google Slides — Slidesgo.", "q": "¿Qué es mejor, Slidesgo o Canva para presentaciones?"}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Slidesgo ist eine Plattform mit kostenlosen und kostenpflichtigen Präsentationsvorlagen für PowerPoint und Google Slides. Slidesgo AI kann Präsentationen aus Beschreibungen generieren und direkt in Google Slides oder PowerPoint öffnen.", "q": "Was ist Slidesgo?"}, {"a": "Slidesgo hat viele kostenlose Templates. Premium ab $8,25/Monat für alle Templates ohne Einschränkungen. Gamma hat einen kostenlosen Plan mit 400 KI-Credits; Plus ab $10/Monat.", "q": "Ist Slidesgo kostenlos?"}, {"a": "Gamma ist besser wenn Sie keinen Content haben und von Null starten. Slidesgo AI ist besser wenn Sie bereits wissen was Sie präsentieren möchten und eine schöne Vorlage in Google Slides oder PowerPoint wollen. Gamma ist output-Tool; Slidesgo ist template-basiert.", "q": "Slidesgo AI vs Gamma: Was ist besser?"}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Slidesgo даёт шаблоны для самостоятельного создания презентаций в Google Slides/PowerPoint. Gamma генерирует всю презентацию по описанию с помощью ИИ. Slidesgo для тех, кто хочет контроль над дизайном, Gamma — для тех, кто хочет скорость.", "q": "Slidesgo vs Gamma — что лучше?"}, {"a": "Slidesgo предлагает сотни бесплатных шаблонов. Premium ($5.99/мес) открывает все шаблоны и функции. Gamma бесплатен с ограниченными ИИ-генерациями; Pro — $10/мес.", "q": "Slidesgo бесплатный?"}, {"a": "Gamma создаёт интерактивные документы-презентации, которые лучше работают в браузере. Для традиционных слайдов в корпоративной среде PowerPoint остаётся стандартом. Gamma отлично подходит для питчей и онлайн-презентаций.", "q": "Gamma заменяет PowerPoint?"}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Slidesgo — платформа з безкоштовними і платними шаблонами презентацій для PowerPoint і Google Slides. Slidesgo AI може генерувати презентації з описів і відкривати їх прямо в Google Slides або PowerPoint.", "q": "Що таке Slidesgo?"}, {"a": "Slidesgo має багато безкоштовних шаблонів. Преміум від $8,25/міс для всіх шаблонів без обмежень. Gamma має безкоштовний план з 400 ШІ-кредитами; Plus від $10/міс.", "q": "Slidesgo безкоштовний?"}, {"a": "Gamma краще якщо у вас нема контенту і ви починаєте з нуля. Slidesgo AI краще якщо ви вже знаєте що хочете презентувати і потрібен красивий шаблон у Google Slides або PowerPoint.", "q": "Slidesgo AI чи Gamma — що краще?"}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Slidesgo לתבניות ב-Google Slides ו-PowerPoint. Gamma ליצירה מלאה מ-AI. Slidesgo לעובדי Google Slides; Gamma לאלה שרוצים AI מלא.", "q": "Slidesgo לעומת Gamma – מה עדיף?"}, {"a": "Slidesgo מציע templates חינמיים; Premium מ-$8.25/חודש. Gamma חינמי עם 400 נקודות; Plus ב-$10/חודש.", "q": "Slidesgo חינמי?"}, {"a": "Slidesgo AI מייצר template ב-Google Slides. Gamma AI מייצר תוכן ועיצוב מלאים. Slidesgo ל-template; Gamma לגנרציה מלאה.", "q": "Slidesgo AI לעומת Gamma AI?"}]$x$::jsonb
