UPDATE tools SET faq = $x$[{"a": "Slidesgo est une plateforme avec des templates de présentation gratuits et payants pour PowerPoint et Google Slides. Slidesgo AI peut générer des présentations à partir de descriptions et les ouvrir directement dans Google Slides ou PowerPoint.", "q": "Qu'est-ce que Slidesgo ?"}, {"a": "Slidesgo a de nombreux templates gratuits. Premium à partir de 8,25 $/mois pour tous les templates sans restrictions. Gamma a un plan gratuit avec 400 crédits IA ; Plus à partir de 10 $/mois.", "q": "Slidesgo est-il gratuit ?"}, {"a": "Gamma est meilleur si vous n'avez pas de contenu et démarrez de zéro. Slidesgo AI est meilleur si vous savez déjà ce que vous voulez présenter et voulez un beau template dans Google Slides ou PowerPoint. Gamma est un outil de génération ; Slidesgo est basé sur les templates.", "q": "Slidesgo AI vs Gamma — lequel est le meilleur ?"}]$x$::jsonb
