UPDATE tools SET faq = $x$[{"a": "Slidesgo é uma plataforma com templates de apresentação gratuitos e pagos para PowerPoint e Google Slides. Slidesgo AI pode gerar apresentações a partir de descrições e abri-las diretamente no Google Slides ou PowerPoint.", "q": "O que é o Slidesgo?"}, {"a": "Slidesgo tem muitos templates gratuitos. Premium a partir de $8,25/mês para todos os templates sem restrições. Gamma tem plano gratuito com 400 créditos de IA; Plus a partir de $10/mês.", "q": "Slidesgo é gratuito?"}, {"a": "Gamma é melhor se você não tem conteúdo e está começando do zero. Slidesgo AI é melhor se você já sabe o que quer apresentar e quer um belo template no Google Slides ou PowerPoint. Gamma é uma ferramenta de geração; Slidesgo é baseado em templates.", "q": "Slidesgo AI vs Gamma — qual é o melhor?"}]$x$::jsonb
