UPDATE tools SET faq = $x$[{"a": "Socratic is Google's AI homework help app for students. You photograph a problem or type a question, and Socratic provides step-by-step explanations, visual aids, videos, and resources. It covers math, science, history, literature, and more. Available free on iOS and Android.", "q": "What is Socratic by Google?"}, {"a": "Yes. Socratic by Google is completely free with no subscription required. It's available on iOS and Android. Google funds it as an educational initiative with no in-app purchases.", "q": "Is Socratic free?"}, {"a": "Socratic is specifically optimized for homework and academic questions with curriculum-aligned explanations. A regular Google search returns links you have to read through. Socratic synthesizes the relevant information into a direct, student-friendly explanation with visual aids.", "q": "Is Socratic better than Google?"}]$x$::jsonb
 WHERE slug = 'socratic-by-google' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Sí. Socratic es completamente gratuito, disponible como app de iOS y Android. Es de Google y no tiene planes de pago. Khanmigo cuesta $9/mes o $44/año.", "q": "¿Socratic by Google es gratuito?"}, {"a": "Socratic puede ayudar con cálculo y matemáticas avanzadas de secundaria. Para cálculo universitario complejo, Wolfram Alpha o Symbolab son más potentes. Khanmigo tiene más contenido de Khan Academy para cálculo con explicaciones pedagógicas estructuradas.", "q": "¿Socratic puede resolver problemas de cálculo?"}, {"a": "Socratic cubre más materias (no solo matemáticas) y explica el concepto detrás del problema. PhotoMath es más especializado en matemáticas y muestra los pasos con mayor detalle. Para solo matemáticas con pasos muy detallados — PhotoMath; para múltiples materias y conceptos — Socratic.", "q": "¿Socratic o PhotoMath para matemáticas?"}]$x$::jsonb
 WHERE slug = 'socratic-by-google' AND lang = 'es';

