UPDATE tools SET faq = $x$[{"a": "Synthesis is an AI-powered learning platform for K-12 students focused on math and problem-solving. Originally developed for SpaceX employees' children at Ad Astra school, it uses game-based challenges to build mathematical reasoning and critical thinking skills.", "q": "What is Synthesis?"}, {"a": "Synthesis offers a free trial. The subscription is $35/month per student. It's positioned as a premium education supplement rather than a replacement for school.", "q": "Is Synthesis free?"}, {"a": "Khan Academy is a broad free education platform covering all subjects with video lessons and practice problems. Synthesis focuses specifically on math and problem-solving through games, using a different pedagogical approach. Synthesis is premium; Khan Academy is free. Khanmigo adds AI tutoring to Khan Academy.", "q": "What is the difference between Synthesis and Khan Academy?"}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Synthesis es una plataforma de aprendizaje matemático para niños que nació en la escuela de SpaceX (Ad Astra School de Elon Musk). Usa videojuegos multijugador donde los niños resuelven problemas matemáticos y de pensamiento lógico en desafíos colaborativos. Fue considerada la mejor plataforma de matemáticas para niños en su lanzamiento.", "q": "¿Qué es Synthesis?"}, {"a": "Synthesis tiene un plan gratuito limitado para explorar. El plan completo cuesta $35/mes por familia. Khanmigo cuesta $9/mes o $44/año. Khan Academy (sin Khanmigo) es completamente gratuito.", "q": "¿Synthesis es gratuito?"}, {"a": "Synthesis está diseñado para niños de 6 a 14 años (primaria y secundaria baja). Khanmigo cubre más rango de edad — desde primaria hasta preparatoria e incluso universitaria para algunas materias.", "q": "¿Para qué edades es Synthesis?"}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Synthesis ist eine Lernplattform ursprünglich für SpaceX-Mitarbeiterkinder entwickelt. Es nutzt kollaborative Spiele und Simulationen um mathematisches Denken zu fördern. Kinder 5-14 Jahre spielen zusammen und lösen dabei komplexe mathematische Probleme.", "q": "Was ist Synthesis?"}, {"a": "Synthesis kostet $35/Monat. Khanmigo kostet $4/Monat als Add-on. Synthesis ist teurer aber bietet eine engagierende Spiel-Erfahrung. Für Eltern die ein engagierendes Mathe-Lernspiel suchen — Synthesis; für günstigen breiten Tutor — Khanmigo.", "q": "Wie viel kostet Synthesis?"}, {"a": "Synthesis ist primär auf Englisch. Die mathematischen Konzepte sind sprachübergreifend, aber die Spielanleitungen und Kommunikation sind auf Englisch. Für deutschsprachige Kinder ohne gute Englischkenntnisse kann das eine Barriere sein.", "q": "Synthesis für deutschsprachige Kinder: Ist es geeignet?"}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Synthesis (от SpaceX Education) — обучающая игровая платформа по математике для детей с акцентом на проблемное мышление. Khanmigo — ИИ-репетитор Khan Academy с Сократовским подходом для более широкого круга предметов. Synthesis — игры, Khanmigo — репетиторство.", "q": "Synthesis vs Khanmigo — в чём разница?"}, {"a": "Synthesis предлагает бесплатный пробный период. Подписка — около $35/мес. Khanmigo — $9/мес как дополнение к бесплатной Khan Academy.", "q": "Synthesis бесплатный?"}, {"a": "Нет намеренно. Khanmigo использует Сократовский метод — задаёт наводящие вопросы, чтобы ученик пришёл к ответу самостоятельно. Цель — понимание, а не списывание.", "q": "Khanmigo даёт ответы на домашние задания?"}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Khan Academy — безкоштовна навчальна платформа з відео і вправами. Synthesis — платформа з головоломками і командними завданнями для розвитку мислення. Khan Academy для стандартної програми; Synthesis для розвитку нестандартного мислення.", "q": "Synthesis vs Khan Academy — яка різниця?"}, {"a": "Synthesis від $35/міс. Khanmigo $44/рік або безкоштовно через партнерства зі школами. Khan Academy повністю безкоштовний.", "q": "Synthesis скільки коштує?"}, {"a": "Synthesis орієнтований на дітей 5-14 років. Khanmigo підходить для ширшого діапазону — від початкової школи до університету.", "q": "Synthesis для якого віку?"}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Synthesis ממוקד בחשיבה ביקורתית ובפתרון בעיות דרך משחקים. Khanmigo מורה AI לעזרה בחומר לימודי. Synthesis להאצה וגמישות; Khanmigo לתמיכה בחומר בית-ספרי.", "q": "Synthesis לעומת Khanmigo – מה ההבדל?"}, {"a": "Synthesis עולה $35/חודש לילד. Khanmigo ב-$9/חודש; ממתן חינמי בחלק מהמדינות.", "q": "Synthesis כמה עולה?"}, {"a": "Synthesis פותחה במקור לילדי עובדי SpaceX. הפכה לחברה עצמאית ב-2022 ופתחה לציבור. מייסדיה הגיעו מסביבת חינוך SpaceX.", "q": "Synthesis – מה הקשר ל-SpaceX?"}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Synthesis est meilleur pour développer la pensée créative et la résolution de problèmes de manière ludique. Khanmigo est meilleur pour l'aide aux devoirs et l'alignement avec le programme scolaire. Développement de la réflexion → Synthesis ; aide aux devoirs → Khanmigo.", "q": "Synthesis vs Khanmigo — lequel est le meilleur pour les enfants ?"}, {"a": "Synthesis coûte 35 $/mois. Khanmigo coûte 4 $/mois. Synthesis est nettement plus cher mais offre une expérience d'apprentissage très différente.", "q": "Synthesis est-il cher ?"}, {"a": "Synthesis est disponible internationalement. L'interface est principalement en anglais. Pour les enfants francophones, vérifiez la disponibilité du contenu en français sur leur site.", "q": "Synthesis est-il disponible en France ?"}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Synthesis é mais voltado para pensamento matemático e lógico através de jogos para crianças. Khanmigo é um tutor geral mais alinhado ao currículo escolar. Para pensamento criativo e matemático, Synthesis; para apoio escolar geral, Khanmigo.", "q": "Synthesis vs Khanmigo — qual é melhor para crianças?"}, {"a": "Synthesis custa $35/mês por aluno. Não tem plano gratuito permanente. Khanmigo custa $44/ano. Khan Academy é gratuita.", "q": "Synthesis é gratuito?"}, {"a": "Synthesis está disponível internacionalmente mas o conteúdo é principalmente em inglês. Para crianças que estudam em inglês ou aprendem o idioma, pode ser valioso. Para currículo brasileiro em português, pode não ser ideal.", "q": "Synthesis é adequado para crianças brasileiras?"}]$x$::jsonb
