UPDATE tools SET faq = $x$[{"a": "Tableau Viewer is $15/user/month, Explorer is $42/user/month, and Creator is $75/user/month. Enterprise pricing varies. Tableau is significantly more expensive than alternatives but widely considered the gold standard for complex enterprise analytics.", "q": "How much does Tableau cost?"}, {"a": "Tableau AI refers to Einstein AI features embedded in Tableau, including natural language querying (ask questions of your data), AI-generated insights, and automated anomaly detection. These features require Tableau+ or Tableau with Salesforce Einstein licensing.", "q": "What is Tableau AI?"}]$x$::jsonb
