UPDATE tools SET faq = $x$[{"a": "Sí. Looker Studio es completamente gratuito para individuos y equipos. Google ofrece hasta 1.000 informes gratuitos. Looker Studio Pro ($9/usuario/mes) añade funciones de colaboración empresarial. Tableau empieza desde $75/usuario/mes.", "q": "¿Looker Studio es gratuito?"}, {"a": "Son el mismo producto. Google Data Studio fue renombrado a Looker Studio en 2022. Looker Studio sigue siendo la herramienta gratuita de reportes de Google, con las mismas funciones de siempre más nuevas integraciones.", "q": "¿Looker Studio vs Google Data Studio?"}]$x$::jsonb
 WHERE slug = 'tableau-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Ja. Looker Studio ist vollständig kostenlos für Einzelnutzer. Looker Studio Pro kostet $9/Benutzer/Monat und fügt erweiterte Verwaltungs- und Kollaborations-Features für Teams hinzu.", "q": "Ist Looker Studio wirklich kostenlos?"}, {"a": "Beide sind starke Dashboard-Tools. Looker Studio ist kostenlos und Google-zentriert. Power BI ($10/Benutzer/Monat) ist tiefer in Microsoft 365 integriert und leistungsfähiger für komplexe Datenmodelle. Im Google-Ökosystem — Looker Studio; im Microsoft-Ökosystem — Power BI.", "q": "Looker Studio vs Power BI: Was ist besser?"}]$x$::jsonb
 WHERE slug = 'tableau-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Tableau Viewer — $15/пользователь/мес, Explorer — $42/пользователь/мес, Creator — $75/пользователь/мес. Корпоративные цены варьируются. Tableau значительно дороже альтернатив, но широко считается золотым стандартом для сложной корпоративной аналитики.", "q": "Сколько стоит Tableau?"}, {"a": "Tableau AI относится к функциям Einstein AI, встроенным в Tableau: запросы на естественном языке, ИИ-генерируемые инсайты и автоматическое обнаружение аномалий. Эти функции требуют лицензирования Tableau+ или Tableau с Salesforce Einstein.", "q": "Что такое Tableau AI?"}]$x$::jsonb
