UPDATE tools SET faq = $x$[{"a": "Так. Looker Studio (раніше Data Studio) повністю безкоштовний. Tableau починається від $75/користувач/міс (Creator). Power BI безкоштовний для базового використання; Premium від $10/користувач/міс.", "q": "Looker Studio безкоштовний?"}, {"a": "Так. Looker Studio популярний для e-commerce аналітики: GA4, Google Ads, Search Console. Є безліч готових шаблонів для e-commerce дашбордів. Для інтеграції з Facebook Ads або іншими платформами потрібні сторонні конектори.", "q": "Looker Studio для e-commerce?"}]$x$::jsonb
