UPDATE tools SET faq = $x$[{"a": "Tickeron is an AI trading platform that uses machine learning to generate trading signals, recognize chart patterns, and predict stock movements. It provides AI-generated buy/sell signals for stocks, ETFs, forex, and crypto without requiring manual technical analysis.", "q": "What is Tickeron?"}, {"a": "Tickeron's AI signals have mixed reviews. Like all trading signal services, past performance doesn't guarantee future results. Users report useful pattern recognition, but the accuracy varies by market conditions. Always use risk management regardless of signal source.", "q": "Is Tickeron accurate?"}, {"a": "Yes. Many traders use TradingView for charting and manual analysis, and separately monitor Tickeron signals. TradingView does not integrate directly with Tickeron, so you'd manage them in separate windows.", "q": "Can I use Tickeron and TradingView together?"}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Las señales de IA de Tickeron muestran resultados históricos pero, como toda predicción de mercado, no garantizan rentabilidad futura. Tickeron es transparente sobre la precisión histórica de sus patrones. Para traders que quieren asistencia IA — útil como referencia; para trading real — siempre requiere criterio propio.", "q": "¿Tickeron es fiable para señales de trading?"}, {"a": "Tickeron tiene un plan gratuito limitado. Los planes de pago empiezan desde $17/mes con acceso a más funciones de IA y señales. TradingView tiene plan gratuito sólido; planes de pago desde $12.95/mes.", "q": "¿Tickeron es gratuito?"}, {"a": "Los indicadores más populares en TradingView son: RSI, MACD, Bollinger Bands, EMA (medias móviles), Volume Profile y Fibonacci. TradingView tiene miles de indicadores de la comunidad además de los estándar. Puedes programar tus propios indicadores con Pine Script.", "q": "¿Cuáles son los mejores indicadores de TradingView?"}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Tickeron ist eine KI-Trading-Plattform die automatisch Handelsmuster erkennt, Signale generiert und AI Robots für automatisiertes Trading anbietet. Es kombiniert technische Analyse mit KI um Kauf- und Verkaufssignale zu identifizieren.", "q": "Was ist Tickeron?"}, {"a": "Tickeron ist einsteigerfreundlicher für KI-gestützte Signals ohne tiefes Chart-Wissen. TradingView hat eine steilere Lernkurve für technische Analyse. Aber TradingView ist kostenlos einsteigerfreundlich für einfaches Chart-Lesen.", "q": "Tickeron vs TradingView: Welches ist für Anfänger?"}, {"a": "Tickeron beginnt ab $90/Monat für Basis-Features. Höhere Pläne für mehr AI Robots und Signale. TradingView hat einen kostenlosen Plan; Essential ab $14,95/Monat.", "q": "Wie viel kostet Tickeron?"}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Tickeron — ИИ-торговая платформа с автоматическими сигналами и роботами. TradingView — профессиональная платформа для графиков с инструментами технического анализа. Tickeron предлагает ИИ-рекомендации, TradingView — инструменты для самостоятельного анализа.", "q": "Tickeron vs TradingView — в чём разница?"}, {"a": "Tickeron предлагает ограниченный бесплатный план. Платные планы от $90/мес. TradingView бесплатен с базовыми функциями; Essential — $12.95/мес.", "q": "Tickeron бесплатный?"}, {"a": "TradingView добавил ИИ-скринеры и ИИ-функции в Pine Script. Но основная сила — инструменты ручного технического анализа и сообщество. Tickeron более специализирован на автоматических ИИ-сигналах.", "q": "TradingView имеет ИИ-функции?"}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Tickeron — ШІ-торгова платформа що автоматично розпізнає торгові патерни, генерує сигнали і пропонує AI Robots для автоматизованої торгівлі. Поєднує технічний аналіз із ШІ для визначення сигналів.", "q": "Що таке Tickeron?"}, {"a": "Tickeron більш зручний для початківців з ШІ-сигналами без глибоких знань графіків. TradingView має крутіший поріг входу для технічного аналізу. Але TradingView безкоштовно зручний для простого читання графіків.", "q": "Tickeron vs TradingView — що для початківців?"}, {"a": "Tickeron від $90/міс для базових функцій. Вищі плани для більше AI Robots і сигналів. TradingView має безкоштовний план; Essential від $14,95/міс.", "q": "Скільки коштує Tickeron?"}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Tickeron פלטפורמת מסחר AI שמזהה דפוסי מסחר, מייצרת אותות ומציעה AI Robots לאוטומציה. משלב ניתוח טכני עם AI.", "q": "מה זה Tickeron?"}, {"a": "Tickeron ידידותי יותר למתחילים עם אותות AI. TradingView דורש ידע בניתוח טכני. אך TradingView חינמי ומצוין לקריאת גרפים בסיסית.", "q": "Tickeron לעומת TradingView – למתחילים?"}, {"a": "Tickeron מ-$90/חודש לתכניות בסיסיות. TradingView מציע תוכנית חינמית; Essential מ-$14.95/חודש.", "q": "Tickeron כמה עולה?"}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Tickeron est une plateforme de trading IA qui reconnaît automatiquement les patterns de marché, génère des signaux et propose des AI Robots pour le trading automatisé. Elle combine l'analyse technique avec l'IA pour identifier les signaux d'achat et de vente.", "q": "Qu'est-ce que Tickeron ?"}, {"a": "Tickeron est plus accessible pour les débutants souhaitant des signaux IA sans connaissances approfondies en graphiques. TradingView a une courbe d'apprentissage plus importante pour l'analyse technique. Mais TradingView est gratuit et facile à utiliser pour la lecture basique de graphiques.", "q": "Tickeron vs TradingView — lequel est meilleur pour les débutants ?"}, {"a": "Tickeron commence à partir de 90 $/mois pour les fonctionnalités de base. Les plans supérieurs pour plus d'AI Robots et de signaux. TradingView a un plan gratuit ; Essential à partir de 14,95 $/mois.", "q": "Combien coûte Tickeron ?"}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Tickeron é uma plataforma de trading com IA que reconhece padrões de mercado automaticamente, gera sinais e oferece AI Robots para trading automatizado. Combina análise técnica com IA para identificar sinais de compra e venda.", "q": "O que é o Tickeron?"}, {"a": "Tickeron é mais acessível para iniciantes que querem sinais de IA sem conhecimentos avançados em gráficos. TradingView tem curva de aprendizado maior para análise técnica. Mas TradingView é gratuito e fácil para leitura básica de gráficos.", "q": "Tickeron vs TradingView — qual é melhor para iniciantes?"}, {"a": "Tickeron começa a partir de $90/mês para funcionalidades básicas. Planos superiores para mais AI Robots e sinais. TradingView tem plano gratuito; Essential a partir de $14,95/mês.", "q": "Quanto custa o Tickeron?"}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Koyfin is a fundamental analysis platform — financial data, earnings, metrics, and company research. TradingView is a technical analysis and charting platform — price charts, indicators, and trading community. Investors doing fundamental research use Koyfin; active traders use TradingView.", "q": "What is the difference between Koyfin and TradingView?"}, {"a": "TradingView has a generous free plan with up to 3 indicators per chart and limited alerts. Essential plan is $14.95/month, Plus is $29.95/month, and Premium is $59.95/month for more indicators, alerts, and data feeds.", "q": "Is TradingView free?"}, {"a": "Many investors use both — Koyfin for fundamental research (earnings, financial metrics, peer comparison) and TradingView for technical analysis (price charts, entry/exit timing). They complement each other for investors who consider both fundamentals and technicals.", "q": "Can I use both Koyfin and TradingView?"}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Bloomberg es la herramienta profesional institucional ($2.000+/mes). TradingView es la mejor opción para traders retail e inversores individuales — mejores gráficos del mercado consumer a un precio accesible. Para traders no institucionales, TradingView es el estándar de facto.", "q": "¿TradingView o Bloomberg para traders?"}, {"a": "FinChat (anteriormente conocido como Fiscal AI) es una plataforma de análisis financiero con IA. Permite hacer preguntas en lenguaje natural sobre empresas públicas: 'cuál fue el margen bruto de Apple en Q3 2024', analizar earnings calls y comparar métricas financieras entre competidores.", "q": "¿Qué es FinChat?"}, {"a": "TradingView tiene datos fundamentales básicos (P/E, EPS, ingresos) pero no está especializado en análisis fundamental profundo. Para análisis fundamental serio — FinChat, Koyfin o Tikr son más completos. TradingView es imbatible en análisis técnico y gráficos.", "q": "¿TradingView tiene análisis fundamental?"}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "TradingView ist für technische Analyse: Charts, Indikatoren, Handelsideen. Finchat ist für fundamentale KI-Analyse: Sie stellen Fragen zu Unternehmensberichten. TradingView für Trader; Finchat für langfristige Investoren die Unternehmen tief analysieren.", "q": "TradingView vs Finchat: Was ist der Unterschied?"}, {"a": "Pine Script ist TradingView's eigene Programmiersprache für benutzerdefinierte Indikatoren und Handelssysteme. Sie können eigene technische Indikatoren schreiben und backtesten. Die Community teilt tausende Pine Script-Indikatoren kostenlos.", "q": "Was ist Pine Script?"}, {"a": "Finchat hat Daten für internationale Märkte inklusive DACH-Aktien. Die Tiefe der KI-Analyse kann für kleinere deutsche Unternehmen geringer sein als für US-Großunternehmen wo mehr Dokumentation verfügbar ist.", "q": "Finchat für deutsche Aktien: Ist es gut?"}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "TradingView — для технических трейдеров и тех, кто анализирует графики. Finchat — для фундаментальных инвесторов, изучающих финансовую отчётность компаний. Это разные инструменты для разных стилей инвестирования.", "q": "TradingView vs Finchat — для кого каждый?"}, {"a": "Finchat — ИИ-финансовый аналитик с доступом к 750 000+ KPI из отчётности публичных компаний. Задайте вопрос на естественном языке — получите данные из 10-K, 10-Q и звонков с аналитиками с ссылками на источники.", "q": "Что такое Finchat?"}, {"a": "Да. TradingView интегрируется с рядом брокеров (Interactive Brokers, Alpaca и другими), позволяя торговать прямо из интерфейса. Это уникальная функция, которой нет у большинства чисто аналитических платформ.", "q": "Можно ли торговать через TradingView?"}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "TradingView для технічного аналізу: графіки, індикатори, торгові ідеї. Finchat для фундаментального ШІ-аналізу: ставте запитання до корпоративних звітів. TradingView для трейдерів; Finchat для довгострокових інвесторів.", "q": "TradingView vs Finchat — яка різниця?"}, {"a": "Pine Script — власна мова програмування TradingView для кастомних індикаторів і торгових систем. Можна писати і тестувати власні технічні індикатори. Спільнота ділиться тисячами Pine Script-індикаторів безкоштовно.", "q": "Що таке Pine Script?"}, {"a": "Finchat має дані для міжнародних ринків. Для українських акцій охоплення може бути обмеженим. Для великих міжнародних компаній доступні повноцінний аналіз і документація.", "q": "Finchat для українських акцій?"}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "TradingView לניתוח טכני. Finchat לניתוח פונדמנטלי עם AI. TradingView לסוחרים; Finchat למשקיעים שמנתחים חברות.", "q": "TradingView לעומת Finchat – מה ההבדל?"}, {"a": "Pine Script היא שפת התכנות של TradingView לכתיבת אינדיקטורים מותאמים אישית ואסטרטגיות מסחר. הקהילה משתפת אלפי scripts חינם.", "q": "מה זה Pine Script?"}, {"a": "TradingView תומך במניות ת\"א, Tel Aviv 35 ומניות ישראליות נוספות. נתוני זמן אמת לבורסת ת\"א דורשים subscription מתאים.", "q": "TradingView לישראל – האם זה תקין?"}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "TradingView est pour l'analyse technique : graphiques, indicateurs, idées de trading. Finchat est pour l'analyse IA fondamentale : posez des questions sur les rapports d'entreprise. TradingView pour les traders ; Finchat pour les investisseurs long terme.", "q": "TradingView vs Finchat — quelle est la différence ?"}, {"a": "Pine Script est le langage de programmation propriétaire de TradingView pour créer des indicateurs et systèmes de trading personnalisés. Vous pouvez écrire et backtester vos propres indicateurs techniques. La communauté partage des milliers d'indicateurs Pine Script gratuitement.", "q": "Qu'est-ce que Pine Script ?"}, {"a": "Finchat couvre les marchés internationaux incluant les actions françaises (CAC40). La profondeur de l'analyse IA peut être moindre pour les petites capitalisations françaises que pour les grandes entreprises américaines où plus de documentation est disponible.", "q": "Finchat pour les actions françaises — est-il efficace ?"}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "TradingView é para análise técnica: gráficos, indicadores, ideias de trading. Finchat é para análise fundamentalista com IA: faça perguntas sobre relatórios de empresas. TradingView para traders; Finchat para investidores de longo prazo.", "q": "TradingView vs Finchat — qual é a diferença?"}, {"a": "Pine Script é a linguagem de programação proprietária do TradingView para criar indicadores e sistemas de trading personalizados. Você pode escrever e fazer backtest dos seus próprios indicadores técnicos. A comunidade compartilha milhares de indicadores Pine Script gratuitamente.", "q": "O que é Pine Script?"}, {"a": "Finchat cobre mercados internacionais incluindo ações da B3. A profundidade da análise com IA pode ser menor para pequenas empresas brasileiras que para grandes empresas americanas onde mais documentação está disponível.", "q": "Finchat para ações brasileiras — é eficaz?"}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Uizard is an AI-powered UI design tool that turns sketches, screenshots, or text descriptions into digital wireframes and mockups. It's designed for non-designers — product managers, founders, and entrepreneurs who need to visualize app ideas quickly without learning Figma.", "q": "What is Uizard?"}, {"a": "Uizard has a free plan with 2 projects and limited AI features. Pro is $19/month and Business is $49/month for more projects, AI generation credits, and team collaboration.", "q": "Is Uizard free?"}, {"a": "Uizard can export designs that can be opened in Figma. This workflow — generate wireframes in Uizard, refine in Figma — is used by teams that start with rough concepts and move to professional design.", "q": "Can Uizard export to Figma?"}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Uizard es ideal en fases tempranas para validar ideas rápidamente — un fundador puede crear un prototipo funcional en minutos sin diseñador. Figma es mejor cuando el equipo crece y necesita un sistema de diseño formal. Muchas startups empiezan en Uizard y migran a Figma al escalar.", "q": "¿Uizard o Figma para startups?"}, {"a": "Uizard tiene un plan gratuito con 3 proyectos y funciones limitadas. Los planes de pago empiezan desde $12/mes (Pro). Figma tiene plan gratuito para 3 proyectos; planes de pago desde $15/mes.", "q": "¿Uizard es gratuito?"}, {"a": "Autodesigner es la función IA estrella de Uizard — describes la app que quieres en texto ('aplicación de fitness para seguimiento de rutinas') y Uizard genera automáticamente múltiples pantallas de UI con diseño coherente. Es el flujo más rápido para convertir una idea en un prototipo visual.", "q": "¿Qué es Uizard Autodesigner?"}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Uizard ist ein KI-Design-Tool das Wireframes und App-Mockups aus Text-Beschreibungen, Screenshots oder Hand-Sketches generiert. Es ist primär für nicht-technische Nutzer — Produkt-Manager, Gründer und Business-Analysten die App-Ideen schnell visualisieren wollen.", "q": "Was ist Uizard?"}, {"a": "Uizard hat einen kostenlosen Plan mit 3 Projekten und begrenzten KI-Features. Pro beginnt ab $12/Monat, Business ab $39/Monat. Figma hat einen kostenlosen Plan; Professional ab $15/Benutzer/Monat.", "q": "Ist Uizard kostenlos?"}, {"a": "Nicht für professionelle Designer. Uizard ist für die schnelle Konzept-Visualisierung ohne Design-Kenntnisse. Figma ist das Profi-Tool für präzises UI/UX-Design. Uizard kann Figma ergänzen: Uizard für erste Konzepte, Figma für die finale Ausarbeitung.", "q": "Kann Uizard Figma ersetzen?"}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Uizard — ИИ-инструмент прототипирования, позволяющий не-дизайнерам создавать макеты приложений и сайтов. Умеет преобразовывать скетчи и скриншоты в редактируемые прототипы, генерировать дизайны по текстовым описаниям.", "q": "Что такое Uizard?"}, {"a": "Нет. Uizard — для быстрого прототипирования и не-дизайнеров. Figma — для профессионального производственного дизайна. Uizard идеален для демонстрации концепции, Figma — для финального продукта.", "q": "Uizard заменяет Figma?"}, {"a": "Uizard предлагает бесплатный план с ограниченными проектами и генерациями ИИ. Starter — $12/мес, Pro — $29/мес. Figma имеет бесплатный план для индивидуальных пользователей.", "q": "Uizard бесплатный?"}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Так. Uizard розроблений спеціально для non-дизайнерів: founders, product managers і розробників що хочуть створювати прототипи. Figma потужніший але потребує більше навчання.", "q": "Uizard для не-дизайнерів?"}, {"a": "Uizard має безкоштовний план з обмеженнями. Pro від $12/міс. Figma безкоштовний для особистого використання; Professional $15/редактор/міс.", "q": "Uizard безкоштовний?"}, {"a": "Uizard простіший і орієнтований на швидкі прототипи для не-дизайнерів. Figma — professional дизайн-інструмент для продуктових команд. Для ідей і валідації — Uizard; для реального продукту — Figma.", "q": "Uizard vs Figma — яка головна різниця?"}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Uizard מהיר יותר לאב-טיפוס ראשוני ולא-מעצבים. Figma AI לעיצוג UX/UI מקצועי ומפורט. לרעיונות מהירים — Uizard; לעיצוג מלא — Figma.", "q": "Uizard מול Figma AI — מה לבחור?"}, {"a": "ל-Uizard יש תוכנית חינמית עם 3 פרויקטים. Starter מ-12$/חודש. Figma יש תוכנית חינמית; Professional מ-15$/עורך/חודש.", "q": "Uizard בחינם?"}, {"a": "כן. Uizard יכול לזהות רכיבי UI מתוך screenshots ולהמיר לעיצוג הניתן לעריכה. שימושי להנדסה לאחור של עיצובים קיימים.", "q": "Uizard מ-screenshot ל-design — האם זה עובד?"}]$x$::jsonb
