UPDATE tools SET faq = $x$[{"a": "Uizard est clairement plus accessible pour les non-designers : générez des maquettes en minutes à partir de descriptions. Figma est puissant mais a une courbe d'apprentissage importante. Pour les PM et fondateurs sans compétences en design, Uizard.", "q": "Uizard vs Figma — lequel est le meilleur pour un non-designer ?"}, {"a": "Uizard a un plan gratuit avec 3 projets. Pro à partir de 12 $/mois. Figma a un plan gratuit ; Professional à partir de 15 $/éditeur/mois.", "q": "Uizard est-il gratuit ?"}, {"a": "Oui. C'est l'une des fonctionnalités phares d'Uizard : téléchargez un screenshot de n'importe quelle app et Uizard le convertit en maquette modifiable. C'est très utile pour recréer des interfaces existantes ou s'inspirer de designs.", "q": "Uizard peut-il convertir des screenshots en maquettes ?"}]$x$::jsonb
