UPDATE tools SET faq = $x$[{"a": "Uizard é para protótipos rápidos por não-designers. Figma é o padrão para design profissional de produto. Para ideação rápida, Uizard; para design profissional e colaboração em equipe, Figma.", "q": "Uizard vs Figma AI — qual usar?"}, {"a": "Uizard tem plano gratuito com 2 projetos. Planos pagos a partir de $12/mês. Figma tem plano gratuito com até 3 projetos; planos pagos a partir de $12/mês.", "q": "Uizard é gratuito?"}, {"a": "Sim, este é um dos principais recursos do Uizard. Você fotografa um esboço à mão e ele converte automaticamente em wireframe digital editável. Muito útil para reuniões de ideação.", "q": "Uizard consegue converter sketches em wireframes?"}]$x$::jsonb
