UPDATE tools SET faq = $x$[{"a": "Uptrends.ai is an AI-powered stock market analysis tool focused on identifying price momentum and trend signals. It uses machine learning to screen thousands of stocks and alert investors to emerging trends before they become obvious to the broader market.", "q": "What is Uptrends.ai?"}, {"a": "Koyfin is better for long-term fundamental investors who need deep financial data and company metrics. Uptrends.ai is better for momentum-oriented investors who want AI to identify shorter-term trend opportunities. Long-term value investors typically get more from Koyfin.", "q": "Which is better for long-term investors?"}]$x$::jsonb
