 WHERE slug = 'uptrends-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Uptrends AI — ИИ-ориентированный инструмент для получения быстрых инсайтов по рынку. Koyfin — полноценная финансовая платформа с глубокими данными по акциям, экономике и портфелю. Uptrends проще и доступнее, Koyfin мощнее для серьёзного анализа.", "q": "Uptrends AI vs Koyfin — что выбрать?"}, {"a": "Uptrends AI — ИИ-платформа для инвесторов, предоставляющая анализ акций, рыночные тренды и торговые идеи через разговорный интерфейс. Позиционируется как ИИ-ассистент для принятия инвестиционных решений.", "q": "Что такое Uptrends AI?"}]$x$::jsonb
