UPDATE tools SET faq = $x$[{"a": "Uptrends AI — ШІ-інвестиційний інструмент що аналізує ринкові тренди і визначає сигнали для нових цінових рухів. Використовує машинне навчання для розпізнавання патернів і попередження інвесторів про можливості.", "q": "Що таке Uptrends AI?"}, {"a": "Koyfin має міжнародне охоплення. Для менших ринків глибина даних може бути нижчою ніж для великих US компаній де більше документації.", "q": "Koyfin для польських або українських акцій?"}]$x$::jsonb
