UPDATE tools SET faq = $x$[{"a": "Uptrends AI est un outil d'investissement IA qui analyse les tendances de marché et identifie les signaux de mouvements de prix émergents. Il utilise le machine learning pour reconnaître des patterns dans les données de marché.", "q": "Qu'est-ce que Uptrends AI ?"}, {"a": "Koyfin couvre les marchés internationaux incluant les bourses européennes (Euronext Paris, Frankfurt). Pour les composantes du CAC40 et du DAX, de bonnes données fondamentales sont disponibles. La couverture peut être moins profonde pour les petites capitalisations européennes.", "q": "Koyfin pour les actions européennes — est-il bon ?"}]$x$::jsonb
