UPDATE tools SET faq = $x$[{"a": "Bubble is a no-code application builder — it's for building web apps with databases, logic, and user interactions. Webflow is a no-code website builder focused on design and CMS. Bubble builds apps; Webflow builds websites.", "q": "What is the difference between Bubble and Webflow?"}, {"a": "Webflow has a CMS (Content Management System) for structured content like blog posts and product listings. It's not a full application database — for user data, transactions, or complex logic, you'd need Bubble or a custom backend.", "q": "Does Webflow have a database?"}, {"a": "Webflow's Starter plan is free. Bubble also has a free plan. Paid plans are comparable — Webflow Core starts at $29/mo, Bubble Starter at $32/mo. Costs scale differently: Webflow charges per site traffic, Bubble charges per app workload.", "q": "Which is cheaper — Bubble or Webflow?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Depende del producto. Si construyes una aplicación SaaS con usuarios, datos y lógica — Bubble. Si construyes el sitio web de marketing de tu startup — Webflow. Muchas startups usan ambas: Webflow para el sitio de marketing y Bubble para el producto.", "q": "¿Bubble o Webflow para startups?"}, {"a": "Varias startups notables comenzaron en Bubble: Dividend Finance, Teal (gestión de carrera), varios MVPs de Y Combinator. Bubble es reconocido en el ecosistema no-code como la plataforma más seria para construir productos reales antes de contratar desarrolladores.", "q": "¿Qué apps famosas se construyeron en Bubble?"}, {"a": "Webflow tiene lógica básica (formularios, filtros, miembros) pero no está diseñado para aplicaciones complejas con base de datos propia y lógica de negocio. Para funcionalidades de app reales — Bubble. Webflow es mejor para sitios con contenido dinámico pero no para productos SaaS.", "q": "¿Puede Webflow construir aplicaciones?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Bubble für Web-Apps: Sie brauchen Nutzeraccounts, Datenbank und komplexe Logik — z.B. ein SaaS-Produkt oder Marktplatz. Webflow für Marketing-Websites: Sie brauchen eine schöne, schnelle Website mit CMS aber keine App-Logik.", "q": "Bubble oder Webflow: Was soll ich wählen?"}, {"a": "Bubble erstellt Web-Apps die im Browser laufen. Für native iOS/Android-Apps können Sie Bubble-Apps als PWA verpacken oder Tools wie BDK Native verwenden. Für echte native Apps sind FlutterFlow oder React Native besser geeignet.", "q": "Kann Bubble eine App für den App-Store erstellen?"}, {"a": "Webflow hat eingebautes E-Commerce für einfache Online-Shops. Für komplexere E-Commerce-Anforderungen (große Produktkataloge, komplexe Varianten) ist Shopify leistungsfähiger. Webflow ist gut für Design-orientierte kleine Shops.", "q": "Webflow für E-Commerce: Ist das gut?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Bubble — конструктор no-code приложений: для создания веб-приложений с базами данных, логикой и пользовательскими взаимодействиями. Webflow — конструктор сайтов с фокусом на дизайн и CMS. Bubble строит приложения, Webflow строит сайты.", "q": "В чём разница между Bubble и Webflow?"}, {"a": "У Webflow есть CMS для структурированного контента (статьи блога, каталог товаров). Это не полноценная база данных приложения — для пользовательских данных, транзакций или сложной логики нужен Bubble или собственный бэкенд.", "q": "Есть ли у Webflow база данных?"}, {"a": "Стартовый план Webflow бесплатный. У Bubble тоже есть бесплатный план. Платные планы сопоставимы: Webflow Core от $29/мес, Bubble Starter от $32/мес. Стоимость масштабируется по-разному.", "q": "Что дешевле — Bubble или Webflow?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Bubble для стартапів що будують SaaS або застосунки з бізнес-логікою і базами даних. Webflow для маркетингових сайтів і агентств. Для MVP з функціональністю — Bubble; для красивого сайту — Webflow.", "q": "Bubble vs Webflow — що обрати для стартапу?"}, {"a": "Так, Bubble масштабується. Великі застосунки з тисячами користувачів працюють на Bubble. Для дуже великого навантаження потрібні вищі плани і оптимізація запитів до бази даних.", "q": "Чи можна масштабувати Bubble-застосунок?"}, {"a": "Webflow — візуальний конструктор сайтів з чистим кодом. WordPress — CMS з тисячами плагінів і більшою гнучкістю контенту. Webflow для дизайнерів що хочуть контроль; WordPress для контент-важких сайтів з великою екосистемою.", "q": "Webflow vs WordPress — яка різниця?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Bubble לאפליקציות web עם לוגיקה ומסד נתונים. Webflow לאתרים ויזואליים ו-CMS. SaaS ו-Web App – Bubble; אתרי שיווק ועיצוב – Webflow.", "q": "Bubble לעומת Webflow – מה לבחור?"}, {"a": "Bubble לאפליקציות web מורכבות. Glide לאפליקציות פשוטות ממקורות Google Sheets. Bubble עוצמתי יותר; Glide מהיר יותר להשקה.", "q": "Bubble לעומת Glide – מה ההבדל?"}, {"a": "Webflow מצוין ל-SEO – HTML נקי, meta tags, sitemap אוטומטי ו-301 redirects. אחד הפתרונות הטובים ביותר ל-SEO בין בוני האתרים ללא קוד.", "q": "Webflow SEO – כמה זה טוב?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Bubble est pour créer des applications web complexes (SaaS, marketplaces). Webflow est pour les sites web marketing et de contenu. Application web avec logique métier → Bubble ; site marketing ou portfolio → Webflow.", "q": "Bubble vs Webflow — lequel est le meilleur ?"}, {"a": "Oui. Webflow produit du HTML sémantique propre, des temps de chargement rapides et offre un contrôle total des balises SEO. C'est l'un des meilleurs constructeurs de sites web pour le SEO.", "q": "Webflow est-il adapté au SEO ?"}, {"a": "Oui. Bubble est capable de créer des marketplaces, des plateformes de réservation et des applications de style Airbnb. Des centaines de startups ont construit leur MVP sur Bubble. La performance peut être limitée à très grande échelle.", "q": "Bubble peut-il créer un clone d'Airbnb ?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Bubble é para construir aplicativos com lógica de negócios complexa. Webflow é para criar sites belos com CMS. Para apps SaaS, Bubble; para sites de marketing de alta qualidade, Webflow.", "q": "Bubble vs Webflow — qual escolher?"}, {"a": "Sim, Bubble é frequentemente usado para criar marketplaces, plataformas de aluguel e outros modelos de negócios complexos. Tem integrações com Stripe para pagamentos e suporte a multiusuários.", "q": "Posso criar um marketplace no Bubble?"}, {"a": "Webflow tem funcionalidades básicas de e-commerce. Para lojas menores, funciona bem. Para e-commerce complexo com muitos produtos, Shopify pode ser mais adequado.", "q": "Webflow é bom para e-commerce?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "Writesonic is an AI content platform for marketers and businesses. It generates blog posts, ads, product descriptions, and landing pages. Chatsonic (its chatbot) has Google Search access for current information. It also generates AI images via Photosonic.", "q": "What is Writesonic used for?"}, {"a": "Writesonic has a free trial with 25 credits. Individual plan starts at $16/month, Small Team at $45/month. Enterprise plans are custom. It's generally cheaper than Jasper at equivalent feature levels.", "q": "Is Writesonic free?"}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Jasper empieza en $49/mes (Creator) para usuarios individuales, $69/mes (Teams) para equipos pequeños. El plan Business es personalizado. Writesonic tiene plan gratuito limitado y planes de pago desde $16/mes.", "q": "¿Cuánto cuesta Jasper?"}, {"a": "Sí. Jasper tiene una función de documento largo que puede generar artículos de 1.500-3.000 palabras desde un brief. También tiene plantillas para blogs, anuncios, correos y más. Siempre requiere revisión humana.", "q": "¿Puede Jasper escribir artículos de blog completos?"}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Jasper beginnt ab $49/Monat (Creator, 1 Sitz) bis zu $125/Monat (Pro, 5 Sitze) und Enterprise-Plänen. Writesonic beginnt ab $20/Monat (Individual) mit günstigeren Optionen. Beide haben kostenlose Testversionen.", "q": "Wie viel kostet Jasper?"}, {"a": "Ja. Jasper unterstützt über 30 Sprachen darunter Deutsch. Die Qualität ist für Englisch am besten, aber Deutsch wird gut unterstützt. Für deutschsprachigen Marketing-Content ist Jasper eine praktikable Lösung, obwohl native Texte immer einer Überprüfung bedürfen.", "q": "Kann ich Jasper auf Deutsch nutzen?"}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Writesonic — ИИ-контент-платформа для маркетологов и бизнеса. Генерирует публикации в блогах, рекламные тексты, описания товаров и лендинги. Chatsonic (его чатбот) имеет доступ к Google Поиску для актуальной информации. Также генерирует ИИ-изображения через Photosonic.", "q": "Для чего используется Writesonic?"}, {"a": "У Writesonic есть бесплатный пробный период с 25 кредитами. Individual plan начинается от $16/мес, Small Team — $45/мес. Корпоративные планы — индивидуальные. В целом дешевле Jasper при сопоставимых функциях.", "q": "Writesonic бесплатный?"}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Jasper від $49/міс (Creator, 1 місце) до $125/міс (Pro, 5 місць) і Enterprise. Writesonic від $20/міс. Обидва мають пробні версії.", "q": "Скільки коштує Jasper?"}, {"a": "Jasper підтримує більше 30 мов включно з українською. Якість найкраща для англійської, але українська підтримується. Рекомендується перевірити і відредагувати результати для критичного контенту.", "q": "Jasper підтримує українську мову?"}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "Jasper מ-49$/חודש (Creator, מושב 1) עד 125$/חודש (Pro, 5 מושבים) ו-Enterprise. Writesonic מ-20$/חודש. לשניהם יש גרסאות ניסיון.", "q": "כמה עולה Jasper?"}, {"a": "Jasper תומך ביותר מ-30 שפות כולל עברית. האיכות טובה ביותר לאנגלית, אבל עברית נתמכת. מומלץ לבדוק ולערוך תוצאות לתוכן קריטי.", "q": "האם Jasper תומך בעברית?"}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "Jasper à partir de 49 $/mois (Creator, 1 siège) jusqu'à 125 $/mois (Pro, 5 sièges) et Enterprise. Writesonic à partir de 20 $/mois. Les deux ont des essais gratuits.", "q": "Combien coûte Jasper ?"}, {"a": "Oui. Jasper supporte plus de 30 langues dont le français. La qualité est meilleure pour l'anglais mais le français est bien supporté. Pour du contenu marketing en français, Jasper est une solution viable, mais une révision est toujours recommandée.", "q": "Jasper supporte-t-il le français ?"}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Jasper a partir de $49/mês (Creator, 1 assento) até $125/mês (Pro, 5 assentos) e Enterprise. Writesonic a partir de $20/mês. Ambos têm testes gratuitos.", "q": "Quanto custa o Jasper?"}, {"a": "Sim. Jasper suporta mais de 30 idiomas incluindo português. A qualidade é melhor para inglês, mas o português é bem suportado. Para conteúdo de marketing em português, Jasper é uma solução viável, mas revisão sempre é recomendada.", "q": "Jasper suporta português?"}]$x$::jsonb
