UPDATE tools SET faq = $x$[{"a": "YouLearn is an AI learning tool that lets you paste a YouTube video URL, PDF, or web article and then chat with the content. It extracts the key information and lets you ask questions, get summaries, and quiz yourself — particularly useful for learning from long video lectures.", "q": "What is YouLearn?"}, {"a": "YouLearn has a free plan with limited daily usage. Pro plan is $12/month for unlimited learning sessions. It's designed for students and self-learners who consume a lot of educational video content.", "q": "Is YouLearn free?"}, {"a": "YouLearn specializes in learning from video and web content — it handles YouTube URLs natively. NotebookLM specializes in research documents — PDFs, Google Docs, and uploaded files. YouLearn is for learning from video lectures; NotebookLM is for researching written sources.", "q": "What is the difference between YouLearn and NotebookLM?"}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "YouLearn permite conversaciones profundas sobre videos de YouTube con preguntas y respuestas. Recall crea tarjetas de memoria automáticamente de videos y artículos para repaso espaciado. Para entender en profundidad — YouLearn; para memorizar a largo plazo — Recall.", "q": "¿YouLearn o Recall para aprender de YouTube?"}, {"a": "YouLearn tiene un plan gratuito con acceso limitado. Los planes de pago empiezan desde $12/mes. NotebookLM de Google es gratuito con límites generosos.", "q": "¿YouLearn es gratuito?"}, {"a": "Sí. NotebookLM acepta URLs de YouTube como fuentes — transcribe el video automáticamente y permite preguntas sobre el contenido. Sin embargo, YouLearn está más especializado en aprendizaje de video con funciones como quizzes y flashcards.", "q": "¿NotebookLM puede analizar videos de YouTube?"}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "YouLearn ist ein KI-Lernassistent der YouTube-Videos und Dokumente in interaktive Lernmaterialien umwandelt. Er generiert automatisch Zusammenfassungen, Quizfragen und Karteikarten aus dem Video-Content und ermöglicht Fragen an das Video zu stellen.", "q": "Was ist YouLearn?"}, {"a": "Recall ist breiter: Es speichert und verknüpft Wissen aus allen Quellen (Web, PDFs, Videos) in einer persönlichen Wissensdatenbank. YouLearn ist fokussierter auf aktives Lernen aus Videos mit Quiz-Generierung. Für Wissensmanagement — Recall; für aktives Lernen aus Videos — YouLearn.", "q": "YouLearn vs Recall: Was ist besser?"}, {"a": "YouLearn hat eine kostenlose Version mit begrenzten Funktionen. Kostenpflichtige Pläne bieten unbegrenzte Verarbeitung. NotebookLM ist vollständig kostenlos.", "q": "Ist YouLearn kostenlos?"}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "YouLearn специализируется на обучении по видео: анализирует YouTube и загруженные видео, создаёт конспекты и тесты. NotebookLM фокусируется на текстовых документах (PDF, заметки). YouLearn для видеообучения, NotebookLM для анализа документов.", "q": "YouLearn vs NotebookLM — в чём разница?"}, {"a": "YouLearn предлагает ограниченный бесплатный план. Pro-план для полного функционала. NotebookLM полностью бесплатен от Google с более щедрыми ограничениями.", "q": "YouLearn бесплатный?"}, {"a": "Да. NotebookLM может добавлять YouTube-видео как источники и транскрибировать их. Однако YouLearn более специализирован для обучения по видео с карточками и тестами.", "q": "NotebookLM поддерживает YouTube?"}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "YouLearn активніше навчає: тести, флешкарти і перевірка знань. NotebookLM пасивніший: відповідає на запитання і генерує подкасти. YouLearn для засвоєння; NotebookLM для дослідження і організації матеріалів.", "q": "YouLearn vs NotebookLM — що обрати для навчання?"}, {"a": "YouLearn має безкоштовний план з обмеженнями. Pro від $12/міс. NotebookLM повністю безкоштовний від Google.", "q": "YouLearn безкоштовний?"}, {"a": "Так. YouLearn аналізує YouTube відео і перетворює їх на інтерактивні уроки з тестами і конспектами. Ідеально для навчання з онлайн-курсів і лекцій.", "q": "YouLearn підтримує YouTube?"}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"a": "YouLearn ממוקד בלמידה אקטיבית עם flashcards ושאלות. NotebookLM ממוקד בניתוח ושיחה עם מסמכים. YouLearn לשינון; NotebookLM לחקירה.", "q": "YouLearn לעומת NotebookLM – מה עדיף?"}, {"a": "YouLearn מציע תוכנית חינמית עם הגבלות; Pro ב-$10/חודש. NotebookLM חינמי לחלוטין.", "q": "YouLearn חינמי?"}, {"a": "Anki כלי flashcard קלאסי עם spaced repetition. YouLearn מייצר flashcards אוטומטית מהחומר שלכם עם AI. YouLearn מהיר יותר להכנת חומר; Anki טוב יותר לשינון לטווח ארוך.", "q": "YouLearn לעומת Anki?"}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'he';

UPDATE tools SET faq = $x$[{"a": "YouLearn est meilleur pour l'apprentissage actif avec flashcards et quiz. NotebookLM est meilleur pour l'analyse et la recherche documentaire. Pour étudier activement → YouLearn ; pour analyser des sources de recherche → NotebookLM.", "q": "YouLearn vs NotebookLM — lequel est le meilleur pour les étudiants ?"}, {"a": "YouLearn a un plan gratuit avec des limites. Les plans payants à partir de 14 $/mois. NotebookLM est gratuit.", "q": "YouLearn est-il gratuit ?"}, {"a": "Oui. YouLearn peut analyser des vidéos YouTube en français (avec sous-titres). Il génère des résumés et flashcards basés sur le contenu de la vidéo.", "q": "YouLearn fonctionne-t-il avec des vidéos YouTube en français ?"}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "YouLearn é para aprender a partir de vídeos do YouTube. NotebookLM é para analisar documentos e PDFs. Para conteúdo em vídeo, YouLearn; para documentos e pesquisa, NotebookLM.", "q": "YouLearn vs NotebookLM — qual usar?"}, {"a": "YouLearn tem plano gratuito com uso limitado. Planos pagos a partir de $12/mês. NotebookLM do Google é gratuito.", "q": "YouLearn é gratuito?"}, {"a": "Sim, YouLearn funciona com vídeos em português no YouTube. A transcrição e análise funcionam para vídeos em múltiplos idiomas.", "q": "YouLearn funciona com vídeos em português?"}]$x$::jsonb
